    nested
        .declare_alias(named_alias("Chained", vec!["T".to_owned()], "Direct"))
        .unwrap_or_else(|error| panic!("alias: {error}"));
    assert_eq!(
        nested
            .finish()
            .refused("an alias chained to a mismatched alias")
            .code(),
        AdtDiagnosticCode::AliasArity
    );
}

