            .unwrap_or_else(|error| panic!("source: {source}; syntax phase failed: {error:?}"));
        let admitted = analyze_package_types(&syntax).unwrap_or_else(|error| {
            panic!("source: {source}; type analysis failed internally: {error:?}")
