    );
    assert!(gantry::advertises_any_profile());

    let contract: Contract = read_json(&root.join(CONTRACT_PATH));
    let mut owned = contract
        .requirement_assignments
        .into_iter()
        .filter(|assignment| {
            assignment
                .evidence_owners
                .iter()
                .any(|owner| owner == ISSUE)
        })
        .map(|assignment| {
            (
                assignment.requirement,
                assignment.clause,
                assignment.profiles,
            )
        })
        .collect::<Vec<_>>();
    owned.sort();
    assert_eq!(owned, expected_owned_rows());

    let index_bytes = read(&root.join(INDEX_PATH));
    let index: PublicationIndex = decode(&index_bytes, INDEX_PATH);
    let resolved = validate_index(&root, &specification, &specification_sha256, &index)
        .unwrap_or_else(|error| panic!("invalid async publication: {error}"));
    validate_report(&root, &index_bytes, &resolved)
        .unwrap_or_else(|error| panic!("invalid async publication report: {error}"));

    let guide = read_text(&root.join(RELEASE_GUIDE_PATH));
    for required in [
        "manual-driving",
        "ExecutorAdapter",
        "GNT-ASYNC-REL-001",
        "Candidate source",
        "source-free resume",
        "hosted macOS",
        "stable-media power-loss",
    ] {
        assert!(guide.contains(required), "release guide omitted {required}");
    }
    assert!(read_text(&root.join("README.md")).contains(RELEASE_GUIDE_PATH));
    assert!(read_text(&root.join("docs/README.md")).contains("async-execution-release.md"));
    assert!(read_text(&root.join("protocol/README.md")).contains("GNT-ASYNC-REL-001"));
    assert!(read_text(&root.join("crates/gantry/src/lib.rs")).contains("ExecutorAdapter"));
}

#[test]
fn async_publication_validator_rejects_release_and_integrity_overclaims() {
    let root = workspace_root();
    let specification = read(&root.join("SPEC.md"));
    let specification_sha256 = sha256(&specification);
    let adoption: AdoptionGate = read_json(&root.join(ADOPTION_PATH));

    let mut blocked = adoption.clone();
    blocked.status = "blocked".to_owned();
    blocked.blocked_by = vec!["GNT-ASYNC-REL-001".to_owned()];
    blocked.advertises_profiles.clear();
    assert!(validate_adoption(&blocked, &specification_sha256).is_err());

    let index_bytes = read(&root.join(INDEX_PATH));
    let mut index: PublicationIndex = decode(&index_bytes, INDEX_PATH);
    index.artifacts[0].sha256 = "0".repeat(64);
    assert!(validate_index(&root, &specification, &specification_sha256, &index).is_err());
}

fn validate_adoption(adoption: &AdoptionGate, specification_sha256: &str) -> Result<(), String> {
    if adoption.format != "gantry.async-execution-adoption/v1"
        || adoption.gate != "GNT-ASYNC-GATE-000"
        || adoption.status != "verified"
        || adoption.specification_sha256 != specification_sha256
        || adoption
            .amended_profiles
            .iter()
            .map(String::as_str)
            .ne(PROFILES)
        || adoption
            .advertises_profiles
            .iter()
            .map(String::as_str)
            .ne(PROFILES)
        || !adoption.blocked_by.is_empty()
    {
        return Err("publication adoption is incomplete or overclaims profiles".to_owned());
    }
    Ok(())
}

fn validate_index(
    root: &Path,
    specification: &[u8],
    specification_sha256: &str,
    index: &PublicationIndex,
) -> Result<BTreeMap<String, (String, Vec<u8>)>, String> {
    if (index.publication_index.major, index.publication_index.minor) != (1, 0)
        || (index.source_language.major, index.source_language.minor) != (1, 0)
        || index.publication_revision != format!("gantry-v1-{specification_sha256}")
        || index
            .artifacts
            .iter()
            .map(|artifact| artifact.id.as_str())
            .ne(REQUIRED_ARTIFACTS)
    {
        return Err("publication identity or membership differs".to_owned());
    }

    let mut resolved = BTreeMap::new();
    let mut protocols = BTreeSet::new();
    let mut release_guide_seen = false;
    for artifact in &index.artifacts {
        if !artifact
            .uri
            .starts_with("https://github.com/NFJones/gantry/releases/download/v1.0.0/")
            || artifact.profiles.windows(2).any(|pair| pair[0] >= pair[1])
            || artifact
                .requirements
                .windows(2)
                .any(|pair| pair[0] >= pair[1])
            || artifact
                .protocols
                .windows(2)
                .any(|pair| pair[0].family >= pair[1].family)
        {
            return Err(format!("unordered artifact metadata for {}", artifact.id));
        }
        for protocol in &artifact.protocols {
            if (protocol.major, protocol.minor) != (1, 0)
                || !protocols.insert(protocol.family.as_str())
            {
                return Err("protocol allocation differs".to_owned());
            }
        }

        let path = artifact_path(root, &artifact.id);
        let bytes = read_result(&path)?;
        if artifact.byte_length != bytes.len().to_string() || artifact.sha256 != sha256(&bytes) {
            return Err(format!("artifact integrity differs: {}", artifact.id));
        }
        if artifact.id == "gantry.spec" {
            if artifact.media_type != "text/markdown" || bytes != specification {
                return Err("published specification differs from SPEC.md".to_owned());
            }
        } else {
            if artifact.media_type != "application/json" {
                return Err(format!("artifact media type differs: {}", artifact.id));
            }
            let bundle: PublicationArtifact = decode(&bytes, &path.display().to_string());
            if bundle.format != "gantry.publication-artifact/v1"
                || bundle.id != artifact.id
                || bundle.specification_sha256 != specification_sha256
                || bundle.protocols != artifact.protocols
                || bundle.profiles != artifact.profiles
                || bundle.requirements != artifact.requirements
                || bundle.files.is_empty()
                || bundle
                    .files
                    .windows(2)
                    .any(|pair| pair[0].path >= pair[1].path)
            {
                return Err(format!("artifact envelope differs: {}", artifact.id));
            }
            for file in bundle.files {
                if file.path.starts_with("docs/reference/")
                    || file.byte_length != file.content.len().to_string()
                    || file.sha256 != sha256(file.content.as_bytes())
                    || file.content.as_bytes() != read_result(&root.join(&file.path))?
                    || !matches!(
                        file.media_type.as_str(),
                        "application/json" | "text/markdown" | "text/plain" | "text/x-rust"
                    )
                {
                    return Err(format!("published source differs: {}", file.path));
                }
                release_guide_seen |= file.path == RELEASE_GUIDE_PATH;
            }
        }
        resolved.insert(artifact.id.clone(), (relative_path(root, &path)?, bytes));
    }
    if !release_guide_seen || protocols.len() != 10 {
        return Err("publication omits release guidance or a protocol family".to_owned());
    }
    Ok(resolved)
}

fn validate_report(
    root: &Path,
    index_bytes: &[u8],
    resolved: &BTreeMap<String, (String, Vec<u8>)>,
) -> Result<(), String> {
    let report_bytes = read_result(&root.join(REPORT_PATH))?;
    let report: VerificationReport = decode(&report_bytes, REPORT_PATH);
    if report.format != "gantry.publication-verification/v1"
        || report.publication_set_identity != sha256(index_bytes)
        || report.index.path != INDEX_PATH
        || report.index.byte_length != index_bytes.len().to_string()
        || report.index.sha256 != sha256(index_bytes)
        || report.artifacts.len() != REQUIRED_ARTIFACTS.len()
    {
        return Err("verification report identity differs".to_owned());
    }
    for artifact in report.artifacts {
        let (path, bytes) = resolved
            .get(&artifact.id)
            .ok_or_else(|| format!("unknown report artifact {}", artifact.id))?;
        if &artifact.path != path
            || artifact.byte_length != bytes.len().to_string()
            || artifact.sha256 != sha256(bytes)
        {
            return Err(format!("report artifact differs: {}", artifact.id));
        }
    }
    Ok(())
}

fn expected_owned_rows() -> Vec<(String, String, Vec<String>)> {
    let all_profiles = PROFILES
        .iter()
        .map(|profile| (*profile).to_owned())
        .collect::<Vec<String>>();
    vec![
        (
            "GNT-1.0".to_owned(),
            "clause-001".to_owned(),
            all_profiles.clone(),
        ),
        (
            "GNT-1.5".to_owned(),
            "clause-002".to_owned(),
            all_profiles.clone(),
        ),
        (
            "GNT-15.0".to_owned(),
            "clause-005".to_owned(),
            vec!["embedding".to_owned()],
        ),
        (
            "GNT-15.8".to_owned(),
            "clause-001".to_owned(),
            vec!["embedding".to_owned()],
        ),
        ("GNT-2.1".to_owned(), "clause-001".to_owned(), all_profiles),
    ]
}

fn artifact_path(root: &Path, id: &str) -> PathBuf {
    let name = if id == "gantry.spec" {
        "SPEC.md".to_owned()
    } else {
        format!("{id}.json")
    };
    root.join("protocol/publication/v1").join(name)
}

fn relative_path(root: &Path, path: &Path) -> Result<String, String> {
    path.strip_prefix(root)
        .map_err(|_| format!("{} is outside the workspace", path.display()))
        .map(|path| path.to_string_lossy().replace('\\', "/"))
}

fn decode<T: serde::de::DeserializeOwned>(bytes: &[u8], path: &str) -> T {
    serde_json::from_slice(bytes).unwrap_or_else(|error| panic!("could not decode {path}: {error}"))
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    decode(&read(path), &path.display().to_string())
}

fn read(path: &Path) -> Vec<u8> {
    read_result(path).unwrap_or_else(|error| panic!("{error}"))
}

fn read_result(path: &Path) -> Result<Vec<u8>, String> {
    fs::read(path).map_err(|error| format!("could not read {}: {error}", path.display()))
}

fn read_text(path: &Path) -> String {
    fs::read_to_string(path)
        .unwrap_or_else(|error| panic!("could not read {}: {error}", path.display()))
}

fn sha256(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

//! Frozen requirement assignments and executable evidence for executor-backed recovery.

use std::fs;
use std::path::Path;

use serde_json::Value;

/// Verifies REC-001's exact frozen assignment rows and linked recovery regressions.
#[test]
fn async_recovery_evidence_matches_frozen_assignments() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let read = |path: &str| -> Value {
        serde_json::from_slice(
            &fs::read(root.join(path)).unwrap_or_else(|error| panic!("read {path}: {error}")),
        )
        .unwrap_or_else(|error| panic!("decode {path}: {error}"))
    };
    let manifest = read("protocol/conformance/async-recovery-v1.json");
    let gate = read("protocol/conformance/async-execution-contract-v1.json");
    let review = read("protocol/requirements/reviewed-v1.json");
    assert_eq!(manifest["format"], "gantry.async-recovery-evidence/v1");
    assert_eq!(manifest["issue"], "GNT-ASYNC-REC-001");
    assert_eq!(
        manifest["specification_sha256"],
        review["specification_sha256"]
    );
    let assignments = gate["requirement_assignments"]
        .as_array()
        .unwrap_or_else(|| panic!("missing frozen assignments"));
    let expected = assignments
        .iter()
        .filter(|row| {
            row["evidence_owners"]
                .as_array()
                .is_some_and(|owners| owners.iter().any(|owner| owner == "GNT-ASYNC-REC-001"))
        })
        .map(|row| {
            serde_json::json!({
                "requirement": row["requirement"],
                "clause": row["clause"],
                "profiles": row["profiles"]
            })
        })
        .collect::<Vec<_>>();
    assert_eq!(expected.len(), 11);
    assert_eq!(manifest["requirements"], Value::Array(expected));

    let capabilities = manifest["capabilities"]
        .as_array()
        .unwrap_or_else(|| panic!("missing capabilities"));
    assert_eq!(capabilities.len(), 14);
    let mut previous = "";
    for capability in capabilities {
        let id = capability["id"]
            .as_str()
            .unwrap_or_else(|| panic!("missing capability id"));
        assert!(id > previous, "noncanonical capability order: {id}");
        previous = id;
        let evidence = capability["evidence"]
            .as_str()
            .unwrap_or_else(|| panic!("missing evidence"));
        let (path, anchor) = evidence
            .split_once('#')
            .unwrap_or_else(|| panic!("missing anchor: {evidence}"));
        let source = fs::read_to_string(root.join(path))
            .unwrap_or_else(|error| panic!("read {path}: {error}"));
        assert!(
            source.contains(&format!("fn {anchor}(")),
            "missing regression: {evidence}"
        );
    }
    assert_eq!(manifest["exclusions"].as_array().map(Vec::len), Some(3));
}

//! Current-contract evidence validation for executable source-task lowering.

use std::fs;
use std::path::{Path, PathBuf};

use serde::Deserialize;
use sha2::{Digest, Sha256};

const MANIFEST_PATH: &str = "protocol/conformance/async-source-lowering-v1.json";
const CONTRACT_PATH: &str = "protocol/conformance/async-execution-contract-v1.json";
const ISSUE: &str = "GNT-ASYNC-LOWER-001";
const FORMAT: &str = "gantry.async-source-lowering-evidence/v1";

const CAPABILITIES: &[(&str, &str)] = &[
    (
        "closed-generic-task-body-identity",
        "crates/gantry-conformance/tests/executable_bridge.rs#generic_task_bodies_have_closed_distinct_identities",
    ),
    (
        "independent-nested-task-bodies",
        "crates/gantry-conformance/tests/executable_bridge.rs#nested_task_bodies_preserve_captures_and_joinall_order",
    ),
    (
        "join-expression-lowering",
        "crates/gantry-conformance/tests/executable_bridge.rs#join_operand_preserves_surrounding_expression",
    ),
    (
        "retained-task-program-codec",
        "crates/gantry-conformance/tests/executable_bridge.rs#analyzed_task_program_round_trips_through_retained_codec",
    ),
    (
        "runtime-profile-rejection",
        "crates/gantry-conformance/tests/executable_bridge.rs#analyzed_concurrent_entry_reaches_the_existing_profile_rejection",
    ),
    (
        "typed-spawn-join-captures",
        "crates/gantry-conformance/tests/executable_bridge.rs#concurrent_source_lowers_spawn_join_and_typed_captures",
    ),
];

#[derive(Clone, Debug, Deserialize)]
struct EvidenceManifest {
    format: String,
    specification_sha256: String,
    issue: String,
    implementation: Implementation,
    requirements: Vec<RequirementEvidence>,
    artifacts: Vec<Artifact>,
    capabilities: Vec<Capability>,
    claim: Claim,
    exclusions: Vec<String>,
}

#[derive(Clone, Debug, Deserialize)]
struct Implementation {
    commit: String,
    subject: String,
}

#[derive(Clone, Debug, Deserialize, Eq, Ord, PartialEq, PartialOrd)]
struct RequirementEvidence {
    requirement: String,
    clause: String,
    profiles: Vec<String>,
}

#[derive(Clone, Debug, Deserialize)]
struct Artifact {
    path: String,
    sha256: String,
}

#[derive(Clone, Debug, Deserialize)]
struct Capability {
    id: String,
    evidence: String,
}

#[derive(Clone, Debug, Deserialize)]
struct Claim {
    profiles: Vec<String>,
    advertises_profiles: Vec<String>,
    assignment_scope: String,
    full_clause_coverage: bool,
}

#[derive(Debug, Deserialize)]
struct Contract {
    requirement_assignments: Vec<RequirementAssignment>,
}

#[derive(Debug, Deserialize)]
struct RequirementAssignment {
    requirement: String,
    clause: String,
    profiles: Vec<String>,
    evidence_owners: Vec<String>,
}

#[test]
fn checked_in_async_source_lowering_evidence_is_current_and_narrow() {
    let root = workspace_root();
    let manifest: EvidenceManifest = read_json(&root.join(MANIFEST_PATH));
    assert_eq!(validate_manifest(&root, &manifest), Ok(()));
}

#[test]
fn async_source_lowering_evidence_rejects_tampering_and_overclaiming() {
    let root = workspace_root();
    let manifest: EvidenceManifest = read_json(&root.join(MANIFEST_PATH));

    let mut stale = manifest.clone();
    stale.artifacts[0].sha256 = "0".repeat(64);
    assert!(validate_manifest(&root, &stale).is_err());

    let mut incomplete = manifest.clone();
    incomplete.capabilities.pop();
    assert!(validate_manifest(&root, &incomplete).is_err());

    let mut reassigned = manifest.clone();
    reassigned.requirements.pop();
    assert!(validate_manifest(&root, &reassigned).is_err());

    let mut overclaimed = manifest.clone();
    overclaimed
        .claim
        .advertises_profiles
        .push("concurrent-evaluator".to_owned());
    assert!(validate_manifest(&root, &overclaimed).is_err());

    let mut runtime_claim = manifest;
    runtime_claim.exclusions.remove(0);
    assert!(validate_manifest(&root, &runtime_claim).is_err());
}

fn validate_manifest(root: &Path, manifest: &EvidenceManifest) -> Result<(), String> {
    if manifest.format != FORMAT || manifest.issue != ISSUE {
        return Err("source lowering evidence identity differs".to_owned());
    }
    if manifest.specification_sha256 != sha256(&read(root.join("SPEC.md"))?) {
        return Err("source lowering evidence uses another specification".to_owned());
    }
    if manifest.implementation.commit != "b91ac8143ecf9847d927126e6ea05b03426bfb9c"
        || manifest.implementation.subject
            != "Lower concurrent source into independent executable task bodies."
    {
        return Err("source lowering implementation provenance differs".to_owned());
    }

    validate_requirements(root, &manifest.requirements)?;
    validate_artifacts(root, &manifest.artifacts)?;
    validate_capabilities(root, &manifest.capabilities, &manifest.artifacts)?;
    validate_claim(&manifest.claim, &manifest.exclusions)
}

fn validate_requirements(root: &Path, declared: &[RequirementEvidence]) -> Result<(), String> {
    let contract: Contract = read_json(&root.join(CONTRACT_PATH));
    let mut assigned = contract
        .requirement_assignments
        .into_iter()
        .filter(|assignment| {
            assignment
                .evidence_owners
                .iter()
                .any(|owner| owner == ISSUE)
        })
        .map(|assignment| RequirementEvidence {
            requirement: assignment.requirement,
            clause: assignment.clause,
            profiles: assignment.profiles,
        })
        .collect::<Vec<_>>();
    assigned.sort();
    let mut declared = declared.to_vec();
    declared.sort();
    if declared != assigned
        || declared
            != [
                RequirementEvidence {
                    requirement: "GNT-15.8".to_owned(),
                    clause: "clause-001".to_owned(),
                    profiles: vec!["embedding".to_owned()],
                },
                RequirementEvidence {
                    requirement: "GNT-3-M-SPAWN".to_owned(),
                    clause: "clause-001".to_owned(),
                    profiles: vec!["concurrent-evaluator".to_owned()],
                },
            ]
    {
        return Err("source lowering frozen requirement assignments differ".to_owned());
    }
    Ok(())
}

fn validate_artifacts(root: &Path, artifacts: &[Artifact]) -> Result<(), String> {
    let expected = [
        "crates/gantry-analysis/src/bodies.rs",
        "crates/gantry-analysis/src/executable.rs",
        "crates/gantry-conformance/tests/executable_bridge.rs",
        CONTRACT_PATH,
    ];
    if artifacts
        .iter()
        .map(|artifact| artifact.path.as_str())
        .ne(expected)
    {
        return Err("source lowering artifact inventory differs".to_owned());
    }
    for artifact in artifacts {
        if artifact.sha256 != sha256(&read(root.join(&artifact.path))?) {
            return Err(format!(
                "source lowering artifact is stale: {}",
                artifact.path
            ));
        }
    }
    Ok(())
}

fn validate_capabilities(
    root: &Path,
    capabilities: &[Capability],
    artifacts: &[Artifact],
) -> Result<(), String> {
    if capabilities
        .iter()
        .map(|capability| (capability.id.as_str(), capability.evidence.as_str()))
        .ne(CAPABILITIES.iter().copied())
    {
        return Err("source lowering capability evidence differs".to_owned());
    }
    for capability in capabilities {
        let (path, anchor) = capability
            .evidence
            .split_once('#')
            .ok_or_else(|| format!("evidence has no anchor: {}", capability.evidence))?;
        if !artifacts.iter().any(|artifact| artifact.path == path) {
            return Err(format!("evidence path is not authenticated: {path}"));
        }
        let source = String::from_utf8(read(root.join(path))?)
            .map_err(|error| format!("evidence source is not UTF-8: {error}"))?;
        if !source.contains(&format!("fn {anchor}")) {
            return Err(format!(
                "evidence anchor is absent: {}",
                capability.evidence
            ));
        }
    }
    Ok(())
}

fn validate_claim(claim: &Claim, exclusions: &[String]) -> Result<(), String> {
    let expected_exclusions = [
        "This evidence does not claim runtime coordinator behavior, executor submission, native child scheduling, join settlement, detachment, or cancellation.",
        "The assigned GNT-3-M-SPAWN clause includes downstream runtime obligations that this lowering evidence does not cover.",
        "The assigned GNT-15.8 clause includes publication-set and full conformance-corpus obligations that this lowering evidence does not cover.",
        "This evidence publishes no analyzer, concurrent-evaluator, embedding, evaluator, or durable-runtime profile claim.",
    ];
    if !claim.profiles.is_empty()
        || !claim.advertises_profiles.is_empty()
        || claim.assignment_scope
            != "lowering-relevant slices of the exact frozen GNT-ASYNC-LOWER-001 assignments"
        || claim.full_clause_coverage
        || exclusions != expected_exclusions
    {
        return Err("source lowering evidence overclaims its scope".to_owned());
    }
    Ok(())
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| unreachable!("conformance crate has a workspace root"))
}

fn read(path: PathBuf) -> Result<Vec<u8>, String> {
    fs::read(&path).map_err(|error| format!("could not read {}: {error}", path.display()))
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    let bytes =
        fs::read(path).unwrap_or_else(|error| panic!("could not read {}: {error}", path.display()));
    serde_json::from_slice(&bytes)
        .unwrap_or_else(|error| panic!("could not decode {}: {error}", path.display()))
}

fn sha256(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

//! Machine-checked conformance for capability-instance authority.
//!
//! These tests exercise the public identity and lattice model of
//! [`gantry::ir::authority`] for `GNT-3-T-AUTHORITY-INSTANCES`,
//! `GNT-3-T-AUTHORITY-LINEAGE`, `GNT-3-T-AUTHORITY-REVOCATION`,
//! `GNT-3-T-AUTHORITY-ADMISSION`, `GNT-7.2-authority-rebinding`, and
//! `GNT-11.6-authority-instance-compatibility`. They check the model that the
//! specification makes normative, not a runtime authority store: no test here
//! observes a live instance, a host service, or a protected payload.

use std::collections::BTreeSet;

use gantry::ir::generated::RecoveryClass;
use gantry::ir::{
    AdmissionRequest, AncestorFences, AuthorityBindingId, AuthorityChangeClass, AuthorityError,
    AuthorityGeneration, AuthorityInstance, AuthorityLeasePolicy, AuthorityRequirementId,
    AuthorityRight, CanonicalCallableIdentity, CanonicalImplementationIdentity, CanonicalPath,
    CanonicalSignature, ExternalOutcome, FenceCategory, FenceLatches, FenceState,
    GenerationRelation, LeaseRelation, LineageRelation, RightsRelation, RightsSet, TypeDescriptor,
    TypeExpression,
};
use sha2::{Digest, Sha256};

/// The capability family used by every fixture requirement.
const FAMILY: &str = "action";

#[test]
fn instance_identity_is_canonical_and_distinct_from_requirement() {
    let requirement = fixture_requirement();
    let binding = fixture_binding(&requirement, "crate::Fixture");
    let instance = AuthorityInstance::bind(
        requirement.clone(),
        binding.clone(),
        read_only_rights(),
        AuthorityLeasePolicy::Unleased,
        false,
    )
    .unwrap_or_else(|_| unreachable!("fixture binding satisfies its requirement"));

    assert!(instance.id().as_str().starts_with("instance:"));
    assert_eq!(instance.id().digest_hex().len(), 64);
    assert!(
        instance
            .id()
            .digest_hex()
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (byte.is_ascii_lowercase()))
    );

    // The instance identity is not the requirement identity, the binding
    // identity, or a callable-site identity, and it is not a naive re-hash of
    // the requirement text, because derivation is domain-separated.
    assert_ne!(instance.id().as_str(), requirement.as_str());
    assert_ne!(instance.id().as_str(), binding.as_str());
    let callable = CanonicalCallableIdentity::free(&fixture_path(), &[TypeDescriptor::STRING]);
    assert_ne!(instance.id().as_str(), callable.as_str());
    let naive = format!("{:x}", Sha256::digest(requirement.as_str().as_bytes()));
    assert_ne!(instance.id().digest_hex(), naive);
    assert!(!instance.id().as_str().starts_with("capability-"));

    // Identity is canonical: equal inputs derive one identity, and a different
    // binding, generation, or lineage root derives another.
    let repeated = AuthorityInstance::bind(
        requirement.clone(),
        binding.clone(),
        read_only_rights(),
        AuthorityLeasePolicy::Unleased,
        false,
    )
    .unwrap_or_else(|_| unreachable!("fixture binding satisfies its requirement"));
    assert_eq!(instance.id(), repeated.id());
    let descendant = instance
        .attenuate(read_only_rights(), AuthorityLeasePolicy::Unleased)
        .unwrap_or_else(|_| unreachable!("equal rights neither amplify nor empty a set"));
    assert_ne!(descendant.id(), instance.id());
    let previous_id = instance.id().clone();
    let rebound = instance
        .rebind(fixture_binding(&requirement, "crate::Replacement"))
        .unwrap_or_else(|_| unreachable!("a live instance rebinds"));
    assert_ne!(rebound.id(), &previous_id);
}

#[test]
fn capability_instances_arise_only_from_binding_or_derivation() {
    let requirement = fixture_requirement();
    let other = AuthorityRequirementId::new(
        &fixture_path(),
        &CanonicalSignature::action(
            RecoveryClass::Idempotent,
            &fixture_path(),
            &[],
            &TypeDescriptor::STRING,
        ),
        FAMILY,
        RecoveryClass::Idempotent,
    )
    .unwrap_or_else(|_| unreachable!("fixture family is portable"));

    // A binding that satisfies another requirement cannot be bound to this one.
    let mismatched = AuthorityInstance::bind(
        requirement.clone(),
        fixture_binding(&other, "crate::Fixture"),
        read_only_rights(),
        AuthorityLeasePolicy::Unleased,
        false,
    );
    assert_eq!(mismatched, Err(AuthorityError::RequirementMismatch));

    // An instance must carry at least one right, and a capability family is a
    // portable lowercase name.
    assert_eq!(
        AuthorityInstance::bind(
            requirement.clone(),
            fixture_binding(&requirement, "crate::Fixture"),
            RightsSet::empty(),
            AuthorityLeasePolicy::Unleased,
            false,
        ),
        Err(AuthorityError::EmptyRights)
    );
    assert_eq!(
        AuthorityRequirementId::new(
            &fixture_path(),
            &CanonicalSignature::action(
                RecoveryClass::ReadOnly,
                &fixture_path(),
                &[],
                &TypeDescriptor::STRING
            ),
            "Action",
            RecoveryClass::ReadOnly,
        ),
        Err(AuthorityError::InvalidCapabilityFamily)
    );

    // Derivation is the only other origin, and only an owned instance derives.
    let instance = fixture_instance(
        read_only_rights(),
        AuthorityLeasePolicy::Unleased,
        false,
        "crate::Fixture",
    );
    let descendant = instance
        .attenuate(read_only_rights(), AuthorityLeasePolicy::Unleased)
        .unwrap_or_else(|_| unreachable!("equal rights neither amplify nor empty a set"));
    assert_eq!(descendant.parent(), Some(instance.id()));
    assert!(!descendant.is_sharable());
}

