#[test]
fn section_37_anchors_and_nonclaims_are_published() {
    let spec = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/../../SPEC.md"))
        .unwrap_or_else(|error| panic!("SPEC.md: {error}"));
    assert_eq!(CALLABLE_CLAUSES.len(), 13);
    for clause in CALLABLE_CLAUSES {
        assert!(
            spec.contains(&format!("<a id=\"{clause}\"></a>")),
            "{clause} is not published"
        );
        assert!(
            spec.contains(&format!("**[{clause}] ")),
            "{clause} carries no clause text"
        );
    }
    assert_eq!(CallableDiagnosticCode::ALL.len(), 12);
    for code in CallableDiagnosticCode::ALL {
        assert!(
            spec.contains(&format!("`{}`", code.code())),
            "{} is not published",
            code.code()
        );
    }
    assert!(
        spec.contains(
            "closure types are unadmitted except as defined by the Section 37 callable contract"
        ),
        "GNT-3-T-GENERIC-CALL does not record the Section 37 admission"
    );
    assert!(
        spec.contains("admits the source callable type form in a signature annotation")
            && spec.contains("`occurrence` field")
            && spec.contains("`signature` for a parameter or result annotation")
            && spec.contains("`binding-annotation` for the annotation of a `let` binding")
            && spec.contains(
                "`boundary-position` for a parameter or result annotation of the entry point"
            )
            && spec.contains("`open-member` for a signature annotation")
            && spec.contains(
                "`non-signature` for an annotation that is not a parameter or result annotation"
            )
            && spec.contains(
                "`instantiation-argument` for a callable type that a generic call reaches"
            )
            && spec.contains("`nested-component` for a type form that is a component"),
        "GNT-37.0 does not publish the callable type admission and occurrence classes"
    );
}

