    let events = catalog["events"]
        .as_array()
        .unwrap_or_else(|| unreachable!("canonical events are an array"));
    let public_events = EVENT_KINDS
        .iter()
        .map(|definition| (definition.kind.wire_name(), definition.layer.wire_name()))
