            .capabilities
            .iter()
            .map(|capability| capability.evidence.as_str())
            .collect::<Vec<_>>(),
        [
            "crates/gantry-conformance/tests/public_protocol_formats.rs#published_public_formats_match_exact_bytes_and_reject_mutations",
