fn generated_conformance_manifest_and_corpus_are_exact_and_complete() {
    let root = workspace_root();
    let corpus_bytes = read(&root.join(CORPUS_PATH));
    let manifest_bytes = read(&root.join(MANIFEST_PATH));
    assert_canonical_and_schema_valid(&root, CORPUS_SCHEMA_PATH, &corpus_bytes);
    assert_canonical_and_schema_valid(&root, MANIFEST_SCHEMA_PATH, &manifest_bytes);

    let corpus: CorpusIndex = decode(&corpus_bytes, CORPUS_PATH);
    let manifest: ConformanceManifest = decode(&manifest_bytes, MANIFEST_PATH);
    let review: RequirementReview = read_json(&root.join(REVIEW_PATH));
    let generated: GeneratedRequirements = read_json(&root.join(REQUIREMENTS_PATH));
    let specification_sha256 = sha256(&read(&root.join("SPEC.md")));

    assert_eq!(corpus.format, "gantry.conformance-corpus-index/v1");
    assert_eq!(manifest.format, "gantry.conformance-manifest/v1");
    assert_eq!(corpus.specification_sha256, specification_sha256);
    assert_eq!(manifest.specification_sha256, specification_sha256);
    assert_eq!(review.specification_sha256, specification_sha256);
    assert!(
        corpus
            .entries
            .windows(2)
            .all(|pair| pair[0].evidence < pair[1].evidence)
    );

    let expected = expected_corpus(&review);
    assert_eq!(corpus.entries.len(), expected.len());
    for entry in &corpus.entries {
        let mappings = expected
            .get(&entry.evidence)
            .unwrap_or_else(|| panic!("unknown corpus evidence {}", entry.evidence));
        assert_eq!(&entry.mappings, mappings, "{}", entry.evidence);
        assert!(entry.mappings.windows(2).all(|pair| pair[0] < pair[1]));
        assert_eq!(
            entry.profiles,
            mappings
                .iter()
                .map(|mapping| mapping.profile.clone())
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>()
        );
        assert_eq!(
            entry.roles,
            mappings
                .iter()
                .flat_map(|mapping| mapping.roles.iter().cloned())
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>()
        );
        assert_anchor_exists(&root, &entry.evidence);
    }
    assert_eq!(manifest.requirement_registry.path, REQUIREMENTS_PATH);
    assert_digest(
        &root,
        &manifest.requirement_registry.path,
        &manifest.requirement_registry.sha256,
    );
    assert_eq!(
        manifest.requirement_registry.requirement_count,
        generated.requirements.len()
    );
    assert_eq!(
        manifest.requirement_registry.clause_count,
        generated
            .requirements
            .iter()
            .map(|requirement| requirement.clauses.len())
            .sum::<usize>()
    );
    assert_eq!(
        manifest.requirement_registry.mapping_count,
        review
            .requirements
            .iter()
            .map(|requirement| {
                requirement
                    .clauses
                    .iter()
                    .map(|clause| clause.profile_reviews.len())
                    .sum::<usize>()
            })
            .sum::<usize>()
    );
    assert_eq!(manifest.corpus.path, CORPUS_PATH);
    assert_eq!(manifest.corpus.sha256, sha256(&corpus_bytes));
    assert_eq!(manifest.corpus.evidence_count, corpus.entries.len());
    assert_eq!(
        manifest.corpus.mapping_count,
        corpus
            .entries
            .iter()
            .map(|entry| entry.mappings.len())
            .sum::<usize>()
    );

    assert_eq!(manifest.schemas.len(), 2);
    for schema in &manifest.schemas {
        assert_digest(&root, &schema.path, &schema.sha256);
    }
    assert_eq!(manifest.negative_vectors.path, NEGATIVE_PATH);
    assert_digest(
        &root,
        &manifest.negative_vectors.path,
        &manifest.negative_vectors.sha256,
    );

    assert!(
        manifest
            .manifests
            .windows(2)
            .all(|pair| pair[0].path < pair[1].path)
    );
    for source in &manifest.manifests {
        assert_digest(&root, &source.path, &source.sha256);
        let value: serde_json::Value = read_json(&root.join(&source.path));
        assert_eq!(
            value.get("format").and_then(serde_json::Value::as_str),
            Some(source.format.as_str())
        );
    }

    assert!(
        manifest
            .gates
            .windows(2)
            .all(|pair| pair[0].gate < pair[1].gate)
    );
    for gate in &manifest.gates {
        assert!(matches!(gate.status.as_str(), "blocked" | "verified"));
        assert_digest(&root, &gate.path, &gate.sha256);
    }
    assert!(
        manifest
            .gates
            .iter()
            .any(|gate| { gate.gate == "GNT-ASYNC-GATE-000" && gate.status == "verified" })
    );

    let expected_profiles = expected_profile_results(&review);
    assert_eq!(manifest.profile_results.len(), 6);
    for result in &manifest.profile_results {
        assert_eq!(
            result.status,
            if result.planned_count == 0 {
                "verified"
            } else {
                "blocked"
            }
        );
        assert_eq!(
            expected_profiles.get(&result.profile),
            Some(&(
                result.covered_count,
                result.not_applicable_count,
                result.planned_count,
            ))
        );
    }

    assert_eq!(manifest.proofs.len(), 11);
    assert!(
        manifest
            .proofs
            .windows(2)
            .all(|pair| pair[0].path < pair[1].path)
    );
    for proof in &manifest.proofs {
        assert!(matches!(proof.kind.as_str(), "argument" | "model"));
        assert_digest(&root, &proof.path, &proof.sha256);
    }
}

#[test]
fn conformance_publication_negative_goldens_are_rejected() {
    let root = workspace_root();
    let negatives: NegativeCatalog = read_json(&root.join(NEGATIVE_PATH));
    assert_eq!(
        negatives.format,
        "gantry.conformance-publication-negatives/v1"
    );
    assert_eq!(negatives.cases.len(), 6);
    assert!(
        negatives
            .cases
            .windows(2)
            .all(|pair| pair[0].name < pair[1].name)
    );

    for case in negatives.cases {
        let (path, schema_path) = match case.target.as_str() {
            "corpus" => (CORPUS_PATH, CORPUS_SCHEMA_PATH),
            "manifest" => (MANIFEST_PATH, MANIFEST_SCHEMA_PATH),
            other => panic!("unknown negative target {other}"),
        };
        let mut value: serde_json::Value = read_json(&root.join(path));
        mutate(&mut value, &case.mutation);
        let bytes = serde_json::to_vec(&value)
            .unwrap_or_else(|error| panic!("could not encode negative {}: {error}", case.name));
        let document = StrictJsonDocument::decode(bytes, json_limits(4_000_000))
            .unwrap_or_else(|error| panic!("negative {} is not strict JSON: {error:?}", case.name));
        let validator =
            SchemaValidator::compile(read(&root.join(schema_path)), json_limits(4_000_000))
                .unwrap_or_else(|error| panic!("could not compile {schema_path}: {error:?}"));
        let errors = validator
            .validate(&document)
            .unwrap_or_else(|error| panic!("could not validate {}: {error:?}", case.name));
        assert!(!errors.is_empty(), "accepted negative {}", case.name);
    }
}

fn expected_corpus(review: &RequirementReview) -> BTreeMap<String, Vec<CorpusMapping>> {
    let mut expected = BTreeMap::<String, Vec<CorpusMapping>>::new();
    for requirement in &review.requirements {
        for clause in &requirement.clauses {
            for profile_review in &clause.profile_reviews {
                match profile_review.state.as_str() {
                    "covered" => {
                        assert!(!profile_review.evidence.is_empty());
                        assert!(profile_review.rationale.is_none());
                        for evidence in &profile_review.evidence {
                            expected
                                .entry(evidence.clone())
                                .or_default()
                                .push(CorpusMapping {
                                    requirement: requirement.id.clone(),
                                    clause: clause.key.clone(),
                                    profile: profile_review.profile.clone(),
                                    roles: clause.roles.clone(),
                                });
                        }
                    }
                    "not-applicable" => {
                        assert!(profile_review.evidence.is_empty());
                        assert!(
                            profile_review
                                .rationale
                                .as_deref()
                                .is_some_and(|value| !value.is_empty())
                        );
                    }
                    "planned" | "in-progress" | "unresolved" => {
                        assert!(profile_review.evidence.is_empty());
                    }
                    other => panic!("unclosed review state {other}"),
                }
            }
        }
    }
    for mappings in expected.values_mut() {
        mappings.sort();
        mappings.dedup();
    }
    expected
}

fn expected_profile_results(review: &RequirementReview) -> BTreeMap<String, (usize, usize, usize)> {
    let mut results = BTreeMap::<String, (usize, usize, usize)>::new();
    for requirement in &review.requirements {
        for clause in &requirement.clauses {
            for profile_review in &clause.profile_reviews {
                let counts = results.entry(profile_review.profile.clone()).or_default();
                match profile_review.state.as_str() {
                    "covered" => counts.0 += 1,
                    "not-applicable" => counts.1 += 1,
                    "planned" | "in-progress" | "unresolved" => counts.2 += 1,
                    other => panic!("unclosed review state {other}"),
                }
            }
        }
    }
    results
}

fn mutate(value: &mut serde_json::Value, mutation: &str) {
    let root = value
        .as_object_mut()
        .unwrap_or_else(|| panic!("publication fixture root is not an object"));
    match mutation {
        "add-root-field" => {
            root.insert("unexpected".to_owned(), serde_json::Value::Null);
        }
        "missing-entries" => {
            root.remove("entries");
        }
        "missing-gates" => {
            root.remove("gates");
        }
        "wrong-format" => {
            root.insert(
                "format".to_owned(),
                serde_json::Value::String("gantry.unknown/v1".to_owned()),
            );
        }
        other => panic!("unknown conformance-publication mutation {other}"),
    }
}

fn assert_canonical_and_schema_valid(root: &Path, schema_path: &str, bytes: &[u8]) {
    let document = StrictJsonDocument::decode(bytes.to_vec(), json_limits(4_000_000))
        .unwrap_or_else(|error| panic!("could not decode canonical output: {error:?}"));
    let canonical = CanonicalJson::from_document(&document)
        .unwrap_or_else(|error| panic!("canonicalization failed: {error:?}"));
    assert_eq!(
        canonical.bytes(),
        bytes.strip_suffix(b"\n").unwrap_or(bytes)
    );
    let validator = SchemaValidator::compile(read(&root.join(schema_path)), json_limits(4_000_000))
        .unwrap_or_else(|error| panic!("could not compile {schema_path}: {error:?}"));
    assert_eq!(validator.validate(&document), Ok(Vec::new()));
}

fn assert_anchor_exists(root: &Path, anchor: &str) {
    let (path, symbol) = anchor
        .split_once('#')
        .unwrap_or_else(|| panic!("invalid evidence anchor {anchor}"));
    let source = fs::read_to_string(root.join(path))
        .unwrap_or_else(|error| panic!("could not read evidence source {path}: {error}"));
    assert!(
        source.contains(&format!("fn {symbol}(")) || source.contains(&format!("fn {symbol}<")),
        "missing evidence symbol {anchor}"
    );
}

fn assert_digest(root: &Path, path: &str, expected: &str) {
    assert_eq!(sha256(&read(&root.join(path))), expected, "{path}");
}

fn sha256(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

const fn json_limits(maximum: u64) -> JsonLimits {
    JsonLimits {
        maximum_bytes: maximum,
        maximum_nesting_depth: maximum,
        maximum_nodes: maximum,
        maximum_string_scalars: maximum,
        maximum_list_items: maximum,
    }
}

fn decode<T: serde::de::DeserializeOwned>(bytes: &[u8], path: &str) -> T {
    serde_json::from_slice(bytes).unwrap_or_else(|error| panic!("could not decode {path}: {error}"))
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    decode(&read(path), &path.display().to_string())
}

fn read(path: &Path) -> Vec<u8> {
    fs::read(path).unwrap_or_else(|error| panic!("could not read {}: {error}", path.display()))
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

//! Machine-checked conformance for the pure Section 32 constant model.
//!
//! The tests use declared classes, members, operations, work records, dependency
//! facts, sealed predicates, package state, and application state only. They neither
//! parse source, evaluate a real initializer, link a package, execute a loader, nor
//! create runtime state.

use std::fs;
use std::path::{Path, PathBuf};

use gantry::ir::{
    ApplicationStateDeclaration, ApplicationStateOwner, CONSTANT_CLAUSES, CONSTANT_INT_LIMIT,
    CONSTANT_NON_CLAIM_ORDER, CONSTANT_NON_CLAIMS, CanonicalPath, ConstantAdmissibility,
    ConstantConversion, ConstantDeclaration, ConstantDiagnosticCode, ConstantEffect, ConstantError,
    ConstantExpression, ConstantMember, ConstantNonClaim, ConstantNonClaimAssertion,
    ConstantOperation, ConstantPackage, ConstantRefusalReason, ConstantSelection, ConstantState,
    ConstantValueClass, ConstantWork, EvaluationLimits, FeatureName, MAX_CONSTANT_PATH_BYTES,
    MAX_DECLARED_NAME_BYTES, PackageLoadFact, PackageStateClass, TargetKind, TargetPredicate,
    TargetPredicateName, admit_package_state, admit_sealed_predicate_name,
    check_constant_non_claims, checked_float, checked_int,
};

const A: &str = "crate::pkg::a";
const B: &str = "crate::pkg::b";
const C: &str = "crate::pkg::c";
const D: &str = "crate::pkg::d";
const EXTERNAL: &str = "crate::dep::k";

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .unwrap_or_else(|| panic!("conformance crate has a workspace parent"))
        .to_path_buf()
}

/// Returns the refusal produced by one rejected constant decision.
fn refuse<T>(outcome: Result<T, ConstantError>, context: &str) -> ConstantError {
    match outcome {
        Ok(_) => panic!("{context}: the decision must be refused"),
        Err(error) => error,
    }
}

fn canonical(value: &str) -> CanonicalPath {
    CanonicalPath::new(value)
        .unwrap_or_else(|error| panic!("the fixture path {value} is canonical: {error}"))
}

fn limits() -> EvaluationLimits {
    EvaluationLimits::new(64, 8, 16, 256)
        .unwrap_or_else(|error| panic!("the fixture limits are nonzero: {error}"))
}

fn expression(path: &str) -> ConstantExpression {
    ConstantExpression::new(path, &[ConstantOperation::Literal], &[])
        .unwrap_or_else(|error| panic!("the fixture initializer is admissible: {error}"))
}

fn plain_declaration(path: &str, class: ConstantValueClass) -> ConstantDeclaration {
    declaration(path, class, &[], true, ConstantSelection::Unconditional)
}

fn declaration(
    path: &str,
    class: ConstantValueClass,
    dependencies: &[&str],
    exported: bool,
    selection: ConstantSelection,
) -> ConstantDeclaration {
    declare_with(path, class, &[], dependencies, exported, selection)
}

fn declare_with(
    path: &str,
    class: ConstantValueClass,
    members: &[ConstantMember],
    dependencies: &[&str],
    exported: bool,
    selection: ConstantSelection,
) -> ConstantDeclaration {
    ConstantDeclaration::new(
        path,
        ConstantAdmissibility::Admissible(class),
        members,
        &expression(path),
        dependencies,
        exported,
        selection,
    )
    .unwrap_or_else(|error| panic!("the fixture declaration {path} is admissible: {error}"))
}

fn member(class: ConstantValueClass) -> ConstantMember {
    ConstantMember::new(ConstantAdmissibility::Admissible(class), &[])
        .unwrap_or_else(|error| panic!("the fixture member {class:?} is admissible: {error}"))
}

fn compound_member(class: ConstantValueClass, members: &[ConstantMember]) -> ConstantMember {
    ConstantMember::new(ConstantAdmissibility::Admissible(class), members).unwrap_or_else(|error| {
        panic!("the fixture compound member {class:?} is admissible: {error}")
    })
}

fn oversized_path() -> String {
    format!("crate::{}", "a".repeat(MAX_CONSTANT_PATH_BYTES))
}

fn evaluate(package: &mut ConstantPackage, path: &str, canonical_value: &str) {
    let work = ConstantWork::new(4, 2, 2, 8);
    package
        .record_evaluation(path, work, canonical_value)
        .unwrap_or_else(|error| panic!("the fixture constant `{path}` evaluates: {error}"));
}

fn feature_selection(feature: &str, active: bool) -> ConstantSelection {
    let name = FeatureName::new(feature)
        .unwrap_or_else(|error| panic!("the fixture feature {feature} is valid: {error}"));
    ConstantSelection::SealedPredicate {
        predicate: TargetPredicate::FeatureEnabled(name),
        active,
    }
}

fn identity_of(declarations: &[(&str, &str)]) -> String {
    let mut package = ConstantPackage::new(limits());
    for (path, value) in declarations {
        package
            .declare(plain_declaration(path, ConstantValueClass::Int))
            .unwrap_or_else(|error| panic!("`{path}` declares once: {error}"));
        evaluate(&mut package, path, value);
    }
    package
        .interface()
        .unwrap_or_else(|error| panic!("the fixture interface publishes: {error}"))
        .identity()
        .as_str()
        .to_owned()
}

fn interface_paths(package: &ConstantPackage) -> Vec<String> {
    package
        .interface()
        .unwrap_or_else(|error| panic!("the fixture interface publishes: {error}"))
        .entries()
        .keys()
        .map(|path| path.as_str().to_owned())
        .collect()
}

#[test]
fn section_32_anchors_and_closed_vocabularies_are_published() {
    assert_eq!(CONSTANT_CLAUSES.len(), 13);
    let specification = fs::read_to_string(workspace_root().join("SPEC.md"))
        .unwrap_or_else(|error| panic!("could not read SPEC.md: {error}"));
    for clause in CONSTANT_CLAUSES {
        assert!(
            specification.contains(&format!("<a id=\"{clause}\"></a>")),
            "Section 32 must publish {clause}"
        );
    }
    for class in ConstantValueClass::ALL {
        assert_eq!(
            ConstantValueClass::from_wire_name(class.wire_name()),
            Some(class)
        );
    }
    assert_eq!(ConstantValueClass::ALL.len(), 11);
    assert_eq!(ConstantValueClass::from_wire_name("map"), None);
    assert!(ConstantValueClass::Struct.carries_members());
    assert!(!ConstantValueClass::List.carries_members());
    assert_eq!(ConstantRefusalReason::ALL.len(), 10);
    for reason in ConstantRefusalReason::ALL {
        assert_eq!(
            ConstantRefusalReason::from_wire_name(reason.wire_name()),
            Some(reason)
        );
    }
    assert_eq!(ConstantOperation::ALL.len(), 16);
    for operation in ConstantOperation::ALL {
        assert_eq!(
            ConstantOperation::from_wire_name(operation.wire_name()),
            Some(operation)
        );
    }
    assert_eq!(ConstantEffect::ALL.len(), 8);
    for effect in ConstantEffect::ALL {
        assert_eq!(
            ConstantEffect::from_wire_name(effect.wire_name()),
            Some(effect)
        );
    }
    assert_eq!(
        ConstantState::ALL.map(ConstantState::wire_name),
        ["declared", "evaluated", "refused"]
    );
    assert_eq!(CONSTANT_NON_CLAIMS.len(), ConstantNonClaim::ALL.len());
    let spellings = ConstantDiagnosticCode::ALL
        .iter()
        .map(|code| code.as_str())
        .collect::<Vec<&str>>();
    let mut sorted = spellings.clone();
    sorted.sort_unstable();
    assert_eq!(
        spellings, sorted,
        "the frozen diagnostic registry is in canonical spelling order"
    );
    for code in ConstantDiagnosticCode::ALL {
        assert_eq!(
            ConstantDiagnosticCode::from_wire_name(code.as_str()),
            Some(code)
        );
        assert!(CONSTANT_CLAUSES.contains(&code.requirement()));
        assert!(
            specification.contains(code.as_str()),
            "Section 32.6 must publish the frozen spelling {}",
            code.as_str()
        );
    }
}

#[test]
fn declarations_bind_canonical_identity_and_reject_mutation() {
    let mut package = ConstantPackage::new(limits());
    package
        .declare(plain_declaration(A, ConstantValueClass::Int))
        .unwrap_or_else(|error| panic!("`{A}` declares once: {error}"));
    assert_eq!(
        refuse(
            package.declare(plain_declaration(A, ConstantValueClass::Bool)),
            "a duplicate canonical path"
        )
        .code(),
        ConstantDiagnosticCode::InvalidDeclaration
    );
    for spelling in [
        "",
        "   ",
        "pkg::a",
        "not a path",
        "crate::",
        "crate::a::",
        "crate::a::1bad",
    ] {
        let error = refuse(
            ConstantExpression::new(spelling, &[ConstantOperation::Literal], &[]),
            "a non-canonical path spelling",
        );
        assert_eq!(
            error.code(),
            ConstantDiagnosticCode::InvalidDeclaration,
            "`{spelling}` must be refused as non-canonical"
        );
    }
    let oversized = oversized_path();
    assert!(oversized.len() > MAX_CONSTANT_PATH_BYTES);
    assert_eq!(
        refuse(
            ConstantExpression::new(oversized.as_str(), &[ConstantOperation::Literal], &[]),
            "an oversized constant path"
        )
        .code(),
        ConstantDiagnosticCode::InvalidDeclaration
    );
    assert_eq!(
        refuse(
            ConstantDeclaration::new(
                A,
                ConstantAdmissibility::Admissible(ConstantValueClass::Int),
                &[],
                &expression(A),
                &[oversized.as_str()],
                false,
                ConstantSelection::Unconditional,
            ),
            "an oversized dependency path"
        )
        .code(),
        ConstantDiagnosticCode::InvalidDeclaration
    );
    let mut external = ConstantPackage::new(limits());
    assert_eq!(
        refuse(
            external.admit_external(oversized.as_str()),
            "an oversized external path"
        )
        .code(),
        ConstantDiagnosticCode::InvalidDeclaration
    );
    assert_eq!(
        refuse(
            ConstantDeclaration::new(
                B,
                ConstantAdmissibility::Admissible(ConstantValueClass::Unit),
                &[],
                &expression(C),
                &[],
                false,
                ConstantSelection::Unconditional,
            ),
            "an initializer with a different path"
        )
        .code(),
        ConstantDiagnosticCode::InvalidDeclaration
    );
    assert_eq!(
        refuse(
            ConstantDeclaration::new(
                D,
                ConstantAdmissibility::Admissible(ConstantValueClass::Int),
                &[],
                &expression(D),
                &[D],
                false,
                ConstantSelection::Unconditional,
            ),
            "a self-declared dependency"
        )
        .code(),
        ConstantDiagnosticCode::Cycle
    );
    evaluate(&mut package, A, "7");
    assert_eq!(package.state(A), Some(ConstantState::Evaluated));
    assert_eq!(package.value(A), Some("7"));
    assert_eq!(
        refuse(
            package.record_evaluation(A, ConstantWork::new(1, 1, 1, 1), "8"),
            "a second evaluation of an immutable constant"
        )
        .code(),
        ConstantDiagnosticCode::InvalidDeclaration
    );
    assert_eq!(
        refuse(
            package.record_refusal(A, ConstantDiagnosticCode::Overflow),
            "a refusal of an evaluated constant"
        )
        .code(),
        ConstantDiagnosticCode::InvalidDeclaration
    );
    assert_eq!(
        package.value(A),
        Some("7"),
        "the canonical value is immutable"
    );
    let mut undeclared = ConstantPackage::new(limits());
    assert_eq!(
        refuse(
            undeclared.record_evaluation(A, ConstantWork::new(1, 1, 1, 1), "1"),
            "an undeclared constant"
        )
        .code(),
        ConstantDiagnosticCode::UnresolvedDependency
    );
    assert_eq!(canonical(A).as_str(), A);
}

#[test]
fn admissible_and_refused_classes_are_closed() {
    for reason in ConstantRefusalReason::ALL {
        let outcome = ConstantDeclaration::new(
            A,
            ConstantAdmissibility::Refused(reason),
            &[],
            &expression(A),
            &[],
            true,
            ConstantSelection::Unconditional,
        );
        assert_eq!(
            refuse(outcome, "a refused constant class").code(),
            ConstantDiagnosticCode::InadmissibleType
        );
    }
    assert_eq!(
        ConstantAdmissibility::Admissible(ConstantValueClass::Float).class(),
        Some(ConstantValueClass::Float)
    );
    assert_eq!(
        ConstantAdmissibility::Refused(ConstantRefusalReason::SealedModelJudgment).class(),
        None
    );
    for class in ConstantValueClass::ALL {
        let members = if class.carries_members() {
            vec![member(ConstantValueClass::Unit)]
        } else {
            Vec::new()
        };
        let declared = declare_with(
            A,
            class,
            &members,
            &[],
            true,
            ConstantSelection::Unconditional,
        );
        assert_eq!(declared.class(), class);
        assert_eq!(declared.members().len(), members.len());
    }
}

#[test]
fn struct_and_enum_members_are_adjudicated() {
    let members = [
        member(ConstantValueClass::Int),
        member(ConstantValueClass::String),
    ];
    let declared = declare_with(
        A,
        ConstantValueClass::Struct,
        &members,
        &[],
        true,
        ConstantSelection::Unconditional,
    );
    assert_eq!(declared.members().len(), 2);
    let enumeration = declare_with(
        B,
        ConstantValueClass::Enum,
        &[member(ConstantValueClass::Unit)],
        &[],
        true,
        ConstantSelection::Unconditional,
    );
    assert_eq!(enumeration.class(), ConstantValueClass::Enum);
    assert_eq!(
        refuse(
            ConstantDeclaration::new(
                A,
                ConstantAdmissibility::Admissible(ConstantValueClass::Enum),
                &[],
                &expression(A),
                &[],
                true,
                ConstantSelection::Unconditional,
            ),
            "a memberless enum class"
        )
        .code(),
        ConstantDiagnosticCode::InadmissibleType
    );
    assert_eq!(
        refuse(
            ConstantMember::new(
                ConstantAdmissibility::Refused(ConstantRefusalReason::LiveResource),
                &[],
            ),
            "a member with a refused class"
        )
        .code(),
        ConstantDiagnosticCode::InadmissibleType
    );
    assert_eq!(
        refuse(
            ConstantMember::new(
                ConstantAdmissibility::Admissible(ConstantValueClass::Struct),
                &[],
            ),
            "a memberless struct member"
        )
        .code(),
        ConstantDiagnosticCode::InadmissibleType
    );
    assert_eq!(
        refuse(
            ConstantMember::new(
                ConstantAdmissibility::Admissible(ConstantValueClass::Int),
                &[member(ConstantValueClass::Int)],
            ),
            "nested members on a member class that carries none"
        )
        .code(),
        ConstantDiagnosticCode::InvalidDeclaration
    );
    let nested = compound_member(
        ConstantValueClass::Struct,
        &[compound_member(
            ConstantValueClass::Enum,
            &[member(ConstantValueClass::Unit)],
        )],
    );
    let nested_declaration = declare_with(
        C,
        ConstantValueClass::Struct,
        &[nested],
        &[],
        true,
        ConstantSelection::Unconditional,
    );
    assert_eq!(nested_declaration.members().len(), 1);
    assert_eq!(
        nested_declaration.members()[0].class(),
        Some(ConstantValueClass::Struct)
    );
    assert_eq!(
        nested_declaration.members()[0].members().len(),
        1,
        "a member carries its own declared members"
    );
    assert_eq!(
        refuse(
            ConstantDeclaration::new(
                A,
                ConstantAdmissibility::Admissible(ConstantValueClass::Int),
                &members,
                &expression(A),
                &[],
                true,
                ConstantSelection::Unconditional,
            ),
            "members on a class that carries none"
        )
        .code(),
        ConstantDiagnosticCode::InvalidDeclaration
    );
}

