#[derive(Debug, Deserialize)]
struct MachineDiagnostic {
    phase: String,
    severity: String,
    category: String,
    code: String,
    message: String,
    primary: MachineSpan,
    fields: BTreeMap<String, String>,
}

#[derive(Debug, Deserialize)]
struct MachineSpan {
