/// Every failed cancellation cut retains exactly the last committed machine.
#[test]
fn cancellation_commit_failures_retain_authoritative_machine_and_budget() {
    for failed_commit in 2..=5 {
        let storage = Arc::new(InstrumentedJournalStore::default());
        let adapter: Arc<dyn JournalStorage> = storage.clone();
        let (_interpreter, _lifecycle, owned, execution, _signal, journal) =
            start_owned_lifecycle("cancellation-cut-failure", adapter);
        storage
            .fail_commit_number
            .store(failed_commit, Ordering::Release);
        let reason = CancellationReason::new(
            CancellationReasonCategory::Caller,
            Some(Arc::from("stop")),
            None,
            32,
        )
        .unwrap_or_else(|error| panic!("reason failed: {error:?}"));
        let result = block_on(owned.cancel_execution(execution, reason));
        assert!(
            matches!(result, DurableCancelExecutionResult::Failed { .. }),
            "commit {failed_commit}: {result:?}"
        );
        let prefix = read_prefix(storage.as_ref(), &journal);
        let (_, authoritative) = recover_authoritative_prefix_with_retained_program(&prefix)
            .unwrap_or_else(|error| panic!("prefix failed: {error:?}"));
        let retained = owned
            .test_retained_projection()
            .unwrap_or_else(|| panic!("failed owner lost retained state"));
        assert_eq!(retained.latest_sequence(), authoritative.latest_sequence());
        assert_eq!(
            retained.machine().checkpoint(),
            authoritative.machine().checkpoint(),
            "commit {failed_commit}: uncommitted machine state leaked"
        );
        assert_eq!(
            retained.machine().budget_checkpoint(),
            authoritative.machine().budget_checkpoint(),
            "commit {failed_commit}: uncommitted budget leaked"
        );
        assert_eq!(
            owned.test_committed_budget(),
            authoritative.machine().budget_checkpoint(),
            "commit {failed_commit}: budget observer differs from committed prefix"
        );
    }
}

fn start_owned_lifecycle(
    journal_name: &str,
    storage: Arc<dyn JournalStorage>,
) -> (
    InterpreterLifecycle,
    DurableLifecycleCoordinator,
    Arc<gantry::DurableOwnedExecution>,
    gantry::identity::ProtocolIdentity,
    gantry::host::contracts::CancellationSignal,
    JournalId,
) {
    let services = Arc::new(Services::default());
    let configuration = test_configuration(Arc::clone(&services));
    start_owned_lifecycle_with_configuration(journal_name, storage, services, configuration)
}

fn start_owned_lifecycle_with_configuration(
    journal_name: &str,
    storage: Arc<dyn JournalStorage>,
    services: Arc<Services>,
    configuration: InterpreterConfiguration,
) -> (
    InterpreterLifecycle,
    DurableLifecycleCoordinator,
    Arc<gantry::DurableOwnedExecution>,
    gantry::identity::ProtocolIdentity,
    gantry::host::contracts::CancellationSignal,
    JournalId,
) {
    let root = TempDirectory::new(
        b"agents { worker } default agent = worker; action read_only inspect(value: Int) -> Int; fn main() {}",
    );
    let selection = selection();
    let journal_id = JournalId::new(journal_name)
        .unwrap_or_else(|error| panic!("journal identity failed: {error:?}"));
    let clock = FixedClock;
    let preflight = Arc::new(ResolvedPreflight::new("agents-v1", "actions-v1"));
    let interpreter_lifecycle = InterpreterLifecycle::new(&configuration);
    let allocator = FreshIdentityAllocator::default();
    let package = AnalyzePackageCoordinator::new(
        &allocator,
        services.as_ref(),
        &clock,
        gantry_conformance::blocking_work(),
    );
    let start = StartExecutionCoordinator::new(
        &package,
        &interpreter_lifecycle,
        &configuration,
        &allocator,
        preflight.clone(),
    );
    let durable =
        DurableStartExecutionCoordinator::new(start, &configuration, Arc::clone(&storage));
    let accepted = match block_on(durable.start(DurableStartExecutionRequest {
        journal_id: journal_id.clone(),
        start: start_request(&root.0, &selection),
    })) {
        DurableStartExecutionResult::Accepted(accepted) => accepted,
        DurableStartExecutionResult::Rejected(failure) => {
            panic!("durable lifecycle fixture was rejected: {failure:?}")
        }
    };
    let execution_id = accepted.execution_id();
    let signal = accepted
        .handle()
        .cancellation_signal()
        .unwrap_or_else(|error| panic!("cancellation signal was unavailable: {error:?}"));
    let lifecycle = DurableLifecycleCoordinator::new(Arc::clone(&storage));
    let owned = block_on(lifecycle.open_owned_execution(
        journal_id.clone(),
        accepted.test_ownership_token().clone(),
        accepted.handle().clone(),
        execution_id,
    ))
    .unwrap_or_else(|error| panic!("durable execution could not be opened: {error:?}"));
    (
        interpreter_lifecycle,
        lifecycle,
        owned,
        execution_id,
        signal,
        journal_id,
    )
}

fn read_prefix(storage: &dyn JournalStorage, journal_id: &JournalId) -> JournalPrefixV1 {
    block_on(storage.read_prefix(ReadJournalPrefixV1 {
        journal_id: journal_id.clone(),
