                LogicalValue::structure(
                    "crate::Counter",
                    vec![(
                        "value".to_owned(),
                        LogicalValue::integer(
                            GantryInt::new(1)
                                .unwrap_or_else(|| unreachable!("fixture integer is valid")),
                        ),
                    )],
                    DEFAULT_VALUE_LIMITS,
                )
                .unwrap_or_else(|error| panic!("counter fixture failed: {error:?}")),
