        .unwrap_or_else(|error| panic!("identity failed: {error}"));
    let task = root_task_identity(execution);
    let holder = LogicalValue::structure(
        "crate::Holder",
        vec![(
            "counter".to_owned(),
            LogicalValue::structure(
                "crate::Counter",
                vec![(
                    "value".to_owned(),
