        assert!(
            gantry::ir::CanonicalCallableIdentity::from_canonical_string(
                identity.as_str(),
                u64::MAX,
            )
            .is_ok()
        );
    }
    for callee in program
        .workflows()
        .iter()
        .flat_map(|workflow| &workflow.instructions)
        .filter_map(|instruction| match &instruction.kind {
