            ForeignFailureKind::from_wire_name(kind.wire_name())
        );
        assert_eq!(kind.as_str(), kind.wire_name());
        assert_eq!(kind.requirement(), "GNT-23.2-foreign-failure-taxonomy");
        assert_ne!(
