    state: String,
    evidence: Vec<String>,
}

#[test]
fn checked_in_frontend_profile_gate_is_current() {
    let root = workspace_root();
    let manifest: Manifest = read_json(&root.join(MANIFEST_PATH));
    assert!(gantry::advertised_profiles().contains(&gantry::ConformanceProfile::Frontend));
    assert!(gantry_conformance::evidence_revision_is_expected(
        &manifest.specification.sha256,
        gantry::PROFILE_SPECIFICATION_REVISION,
    ));
    assert_eq!(validate_manifest(&root, &manifest), Ok(()));
}

#[test]
fn frontend_profile_gate_rejects_stale_artifacts_and_overclaiming() {
    let root = workspace_root();
    let manifest: Manifest = read_json(&root.join(MANIFEST_PATH));

    let mut stale = manifest.clone();
    stale.artifacts[0].sha256 = "0".repeat(64);
    assert!(validate_manifest(&root, &stale).is_err());

    let mut overclaim = manifest;
    overclaim.claim.profiles.push("analyzer".to_owned());
    assert!(validate_manifest(&root, &overclaim).is_err());
}

fn validate_manifest(root: &Path, manifest: &Manifest) -> Result<(), String> {
    if manifest.format != "gantry.frontend-gate-evidence/v1"
        || manifest.gate != "GNT-GATE-200"
        || manifest.status != "verified"
        || manifest.profile != "frontend"
    {
        return Err("frontend gate identity or status is invalid".to_owned());
    }
    if manifest.claim.profiles != ["frontend"]
        || manifest.claim.advertises_profiles != manifest.claim.profiles
        || manifest.claim.excludes_profiles
            != [
                "analyzer",
                "concurrent-evaluator",
                "durable-runtime",
                "embedding",
                "evaluator",
            ]
        || !gantry::PROFILE_CLAIMS_ENABLED
        || !gantry::advertised_profiles().contains(&gantry::ConformanceProfile::Frontend)
    {
        return Err("frontend claim is invalid or overstates another profile".to_owned());
    }

    validate_file_digest(root, &manifest.specification, "specification")?;
    validate_sorted_unique(
        "prerequisite issues",
        manifest
            .prerequisites
            .iter()
            .map(|prerequisite| prerequisite.issue.as_str()),
    )?;
    for prerequisite in &manifest.prerequisites {
        validate_commit(root, prerequisite)?;
    }

    validate_sorted_unique(
        "artifact paths",
        manifest
            .artifacts
            .iter()
            .map(|artifact| artifact.path.as_str()),
    )?;
    for artifact in &manifest.artifacts {
        validate_file_digest(root, artifact, "artifact")?;
    }

    let review: RequirementReview = read_json(&root.join("protocol/requirements/reviewed-v1.json"));
    let section14: Section14Review =
        read_json(&root.join("protocol/requirements/section14-v1.json"));
    if review.specification_sha256 != manifest.specification.sha256
        || section14.specification_sha256 != manifest.specification.sha256
    {
        return Err("frontend evidence uses another specification revision".to_owned());
    }

    let mut applicable_clause_count = 0_usize;
    let mut covered_count = 0_usize;
    let mut not_applicable_count = 0_usize;
    for requirement in &review.requirements {
        for clause in &requirement.clauses {
            if !clause.profiles.iter().any(|profile| profile == "frontend") {
                continue;
            }
            applicable_clause_count += 1;
            let profile_review = clause
                .profile_reviews
                .iter()
                .find(|profile_review| profile_review.profile == "frontend")
                .ok_or_else(|| {
                    format!(
                        "frontend review is missing: {}:{}",
                        requirement.id, clause.key
                    )
                })?;
            match profile_review.state.as_str() {
                "covered" if !profile_review.evidence.is_empty() => {
                    covered_count += 1;
                    for evidence in &profile_review.evidence {
                        validate_evidence_anchor(root, evidence)?;
                    }
                }
                "not-applicable"
                    if profile_review.evidence.is_empty()
                        && profile_review
                            .rationale
                            .as_deref()
                            .is_some_and(|rationale| !rationale.is_empty()) =>
                {
                    not_applicable_count += 1;
                }
                _ => {
                    return Err(format!(
                        "frontend review is not closed: {}:{}",
                        requirement.id, clause.key
                    ));
                }
            }
        }
    }
    if manifest.review_summary.applicable_clause_count != applicable_clause_count
        || manifest.review_summary.covered_count != covered_count
        || manifest.review_summary.not_applicable_count != not_applicable_count
        || applicable_clause_count != covered_count + not_applicable_count
    {
        return Err("frontend review summary differs from reviewed applicability".to_owned());
    }

    if manifest.section14_excerpt_count != section14.excerpts.len()
        || section14
            .excerpts
            .iter()
            .any(|excerpt| excerpt.state != "covered" || excerpt.evidence.is_empty())
    {
        return Err("Section 14 authoring evidence is incomplete".to_owned());
    }
    if manifest.validation_commands.is_empty() || manifest.environment_gaps.len() != 1 {
        return Err("validation commands or environment gaps are incomplete".to_owned());
    }
    Ok(())
}

fn validate_evidence_anchor(root: &Path, evidence: &str) -> Result<(), String> {
    let (path, test) = evidence
        .split_once('#')
        .ok_or_else(|| format!("evidence anchor has no test: {evidence}"))?;
    if !path.starts_with("crates/gantry-conformance/tests/") || !path.ends_with(".rs") {
        return Err(format!(
            "evidence is not a public conformance test: {evidence}"
        ));
    }
    let source = fs::read_to_string(root.join(path))
        .map_err(|error| format!("could not read evidence {path}: {error}"))?;
    if !source.contains(&format!("fn {test}(")) {
        return Err(format!("evidence test is missing: {evidence}"));
    }
    Ok(())
}

fn validate_file_digest(root: &Path, file: &FileDigest, kind: &str) -> Result<(), String> {
    let bytes = fs::read(root.join(&file.path))
        .map_err(|error| format!("could not read {kind} {}: {error}", file.path))?;
    let actual = format!("{:x}", Sha256::digest(bytes));
    if actual != file.sha256 {
        return Err(format!("{kind} digest differs: {}", file.path));
    }
    Ok(())
}

fn validate_commit(root: &Path, prerequisite: &Prerequisite) -> Result<(), String> {
    let ancestor = Command::new("git")
        .current_dir(root)
        .args(["merge-base", "--is-ancestor", &prerequisite.commit, "HEAD"])
        .status()
        .map_err(|error| format!("could not inspect prerequisite commit: {error}"))?;
    if !ancestor.success() {
        return Err(format!(
            "prerequisite commit is not an ancestor: {}",
            prerequisite.issue
        ));
    }
    let subject = Command::new("git")
        .current_dir(root)
        .args(["show", "-s", "--format=%s", &prerequisite.commit])
        .output()
        .map_err(|error| format!("could not read prerequisite subject: {error}"))?;
    let actual = String::from_utf8(subject.stdout)
        .map_err(|error| format!("prerequisite subject is not UTF-8: {error}"))?;
    if actual.trim_end() != prerequisite.subject {
        return Err(format!(
            "prerequisite subject differs: {}",
            prerequisite.issue
        ));
    }
    Ok(())
}

fn validate_sorted_unique<'a>(
    name: &str,
    values: impl IntoIterator<Item = &'a str>,
) -> Result<(), String> {
    let values = values.into_iter().collect::<Vec<_>>();
    let unique = values.iter().copied().collect::<BTreeSet<_>>();
    if values.windows(2).any(|pair| pair[0] >= pair[1]) || unique.len() != values.len() {
        return Err(format!("{name} are not sorted and unique"));
    }
    Ok(())
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| unreachable!("conformance crate has a workspace root"))
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    let bytes = fs::read(path);
    assert!(bytes.is_ok(), "could not read {}", path.display());
    let value =
        bytes.and_then(|bytes| serde_json::from_slice(&bytes).map_err(std::io::Error::other));
    assert!(value.is_ok(), "could not decode {}", path.display());
    value.unwrap_or_else(|_| unreachable!("checked above"))
}

//! Requirement-indexed executable evidence for the frontend lexical owner.

use std::fs;
use std::path::{Path, PathBuf};

use gantry::frontend::{
    LexContext, LexError, Lexer, PromptDelimiter, Punctuation, ReservedWord, TokenKind,
};
use gantry::source::{SourceLimits, SourceSnapshotBuilder};
use serde::Deserialize;

const EVIDENCE_ID: &str = "crates/gantry-conformance/tests/frontend_lexical_evidence.rs#lexical_requirement_vectors_cover_reviewed_clauses";

#[derive(Debug, Deserialize)]
struct EvidenceManifest {
    format: String,
    specification_sha256: String,
    issue: String,
    entries: Vec<EvidenceEntry>,
}

#[derive(Clone, Debug, Deserialize, Eq, Ord, PartialEq, PartialOrd)]
struct EvidenceEntry {
    requirement: String,
    clause: String,
}

#[derive(Debug, Deserialize)]
struct RequirementReview {
    specification_sha256: String,
    requirements: Vec<Requirement>,
}

#[derive(Debug, Deserialize)]
struct Requirement {
    id: String,
    clauses: Vec<Clause>,
}

#[derive(Debug, Deserialize)]
struct Clause {
    key: String,
    profile_reviews: Vec<ProfileReview>,
}

#[derive(Debug, Deserialize)]
struct ProfileReview {
    profile: String,
    state: String,
    evidence: Vec<String>,
}

#[test]
fn reviewed_frontend_lexical_evidence_is_closed() {
    let root = workspace_root();
    let manifest: EvidenceManifest =
        read_json(&root.join("protocol/conformance/frontend-lexical-v1.json"));
    let review: RequirementReview = read_json(&root.join("protocol/requirements/reviewed-v1.json"));

    assert_eq!(manifest.format, "gantry.frontend-lexical-evidence/v1");
    assert_eq!(manifest.issue, "GNT-FE-001");
    assert!(gantry_conformance::evidence_revision_is_expected(
        &manifest.specification_sha256,
        &review.specification_sha256,
    ));
    assert!(!manifest.entries.is_empty());
    assert!(manifest.entries.windows(2).all(|pair| pair[0] < pair[1]));

    for entry in manifest.entries {
        let clause = review
            .requirements
            .iter()
            .find(|requirement| requirement.id == entry.requirement)
            .and_then(|requirement| {
                requirement
                    .clauses
                    .iter()
                    .find(|clause| clause.key == entry.clause)
            })
            .unwrap_or_else(|| panic!("missing {}:{}", entry.requirement, entry.clause));
        let review = clause
            .profile_reviews
            .iter()
            .find(|review| review.profile == "frontend")
            .unwrap_or_else(|| {
                panic!(
                    "missing frontend review for {}:{}",
                    entry.requirement, entry.clause
                )
            });
        assert_eq!(
            review.state, "covered",
            "{}:{}",
            entry.requirement, entry.clause
        );
        assert!(
            review
                .evidence
                .iter()
                .any(|evidence| evidence == EVIDENCE_ID),
            "{}:{}",
            entry.requirement,
            entry.clause
        );
    }
}

#[test]
fn lexical_requirement_vectors_cover_reviewed_clauses() {
    let source = concat!(
        "\u{feff}/* outer /* inner */ */ action agent agents as attempt Bool break ",
        "continue crate Decision decide default detach discard effects else enum Err false Float fn ",
        "fork for idempotent if impl in inline Int join joinall let limit List loop match mod ",
        "mut new non_idempotent None null Ok OperationError Option prompt pure read_only Result ",
        "return retry_limit self Self session Some spawn String struct super trait true Tuple ",
        "unbounded Unit until use using when where while with α_2 _ 0 1_000 2.5e+2 ",
        ":: -> => == != <= >= && || += -= *= /= %= ",
        "\"a\\n\\u{1f642}\" r#\"raw \\\\ text\"#"
    );
    with_lexer(source, 256, |lexer| {
        let reserved = [
            "action",
            "agent",
            "agents",
            "as",
            "attempt",
            "Bool",
            "break",
            "continue",
            "crate",
            "Decision",
            "decide",
            "default",
            "detach",
            "discard",
            "effects",
            "else",
            "enum",
            "Err",
            "false",
            "Float",
            "fn",
            "fork",
            "for",
            "idempotent",
            "if",
            "impl",
            "in",
            "inline",
            "Int",
            "join",
            "joinall",
            "let",
            "limit",
            "List",
            "loop",
            "match",
            "mod",
            "mut",
            "new",
            "non_idempotent",
            "None",
            "null",
            "Ok",
            "OperationError",
            "Option",
            "prompt",
            "pure",
            "read_only",
            "Result",
            "return",
            "retry_limit",
            "self",
            "Self",
            "session",
            "Some",
            "spawn",
            "String",
            "struct",
            "super",
            "trait",
            "true",
            "Tuple",
            "unbounded",
            "Unit",
            "until",
            "use",
            "using",
            "when",
            "where",
            "while",
            "with",
        ];
        for spelling in reserved {
            assert_eq!(
                ReservedWord::from_spelling(spelling).map(ReservedWord::spelling),
                Some(spelling)
            );
            assert!(matches!(
                lexer.next(LexContext::Ordinary).map(|token| token.kind().clone()),
                Ok(TokenKind::ReservedWord(word)) if word.spelling() == spelling
            ));
        }
        assert!(matches!(
            lexer.next(LexContext::Ordinary).map(|token| token.kind().clone()),
            Ok(TokenKind::Identifier(value)) if &*value == "α_2"
        ));
        assert!(matches!(
            lexer
                .next(LexContext::Ordinary)
                .map(|token| token.kind().clone()),
            Ok(TokenKind::Punctuation(Punctuation::Underscore))
        ));
        assert!(
            matches!(lexer.next(LexContext::Ordinary).map(|token| token.kind().clone()), Ok(TokenKind::IntegerLiteral(value)) if &*value == "0")
        );
        assert!(
            matches!(lexer.next(LexContext::Ordinary).map(|token| token.kind().clone()), Ok(TokenKind::IntegerLiteral(value)) if &*value == "1_000")
        );
        assert!(
            matches!(lexer.next(LexContext::Ordinary).map(|token| token.kind().clone()), Ok(TokenKind::FloatLiteral(value)) if &*value == "2.5e+2")
        );

        for punctuation in [
            Punctuation::PathSeparator,
            Punctuation::ThinArrow,
            Punctuation::FatArrow,
            Punctuation::EqualEqual,
            Punctuation::NotEqual,
            Punctuation::LessEqual,
            Punctuation::GreaterEqual,
            Punctuation::AndAnd,
            Punctuation::OrOr,
            Punctuation::PlusEqual,
            Punctuation::MinusEqual,
            Punctuation::StarEqual,
            Punctuation::SlashEqual,
            Punctuation::PercentEqual,
        ] {
            assert!(matches!(
                lexer.next(LexContext::Ordinary).map(|token| token.kind().clone()),
                Ok(TokenKind::Punctuation(actual)) if actual == punctuation
            ));
        }
        assert!(
            matches!(lexer.next(LexContext::Ordinary).map(|token| token.kind().clone()), Ok(TokenKind::StringLiteral(value)) if &*value == "a\n🙂")
        );
        assert!(
            matches!(lexer.next(LexContext::Ordinary).map(|token| token.kind().clone()), Ok(TokenKind::RawStringLiteral(value)) if &*value == "raw \\\\ text")
        );
        assert!(matches!(
            lexer
                .next(LexContext::Ordinary)
                .map(|token| token.kind().clone()),
            Ok(TokenKind::EndOfFile)
        ));
    });

    for (source, code) in [
        ("01", "invalid-number"),
        ("1_", "invalid-number"),
        ("1e+", "invalid-number"),
        ("\"line\nfeed\"", "literal-line-terminator"),
        ("\"\\u{D800}\"", "invalid-unicode-escape"),
        ("r#\"unterminated", "unterminated-raw-string"),
        ("/* unterminated", "unterminated-block-comment"),
        ("// hidden \u{feff}\nvalue", "unexpected-byte-order-mark"),
    ] {
        with_lexer(source, 16, |lexer| {
            assert!(matches!(
                lexer.next(LexContext::Ordinary),
                Err(LexError::Diagnostic(ref diagnostic)) if diagnostic.code.as_str() == code
            ));
        });
    }

    with_lexer("123 1_2", 8, |lexer| {
        assert!(
            matches!(lexer.next(LexContext::DirectiveInteger).map(|token| token.kind().clone()), Ok(TokenKind::DirectiveInteger(value)) if &*value == "123")
        );
        assert!(
            matches!(lexer.next(LexContext::DirectiveInteger).map(|token| token.kind().clone()), Ok(TokenKind::IntegerLiteral(value)) if &*value == "1_2")
        );
    });

    with_lexer("r#\"a $$${Some(\"draft\")} z\"#", 32, |lexer| {
        let token = lexer
            .next(LexContext::PromptTemplate)
            .unwrap_or_else(|_| unreachable!("valid prompt template"));
        let TokenKind::PromptTemplate(template) = token.kind() else {
            unreachable!("prompt template token")
        };
        assert_eq!(template.delimiter(), PromptDelimiter::Raw);
        assert_eq!(template.literals(), &["a $".into(), " z".into()]);
        assert_eq!(template.interpolations()[0].source(), "Some(\"draft\")");
    });

    with_lexer("\"\"\"\n  first\n    second\\nline\n  \"\"\"", 8, |lexer| {
        let token = lexer
            .next(LexContext::PromptTemplate)
            .unwrap_or_else(|_| unreachable!("valid block prompt"));
        let TokenKind::PromptTemplate(template) = token.kind() else {
            unreachable!("prompt template token")
        };
        assert_eq!(template.delimiter(), PromptDelimiter::Block);
        assert_eq!(template.literals(), &["first\n  second\nline".into()]);
    });
}

fn with_lexer<T>(source: &str, token_limit: u64, test: impl FnOnce(&mut Lexer<'_>) -> T) -> T {
    let limits = SourceLimits::new(1, 1_000_000, 1_000_000, token_limit, 64)
        .unwrap_or_else(|_| unreachable!("positive limits"));
    let mut builder = SourceSnapshotBuilder::new(limits);
    assert!(builder.add_file("main.gnt", source.as_bytes()).is_ok());
    let mut snapshot = builder.finish();
    let (records, counters) = snapshot.records_and_counters_mut();
    let record = records
        .first()
        .unwrap_or_else(|| unreachable!("one source"));
    let mut lexer =
        Lexer::new(record, counters).unwrap_or_else(|_| unreachable!("valid UTF-8 fixture"));
    test(&mut lexer)
}

