static NEXT_TEMP: AtomicU64 = AtomicU64::new(0);

struct TempDirectory(PathBuf);

impl TempDirectory {
    fn new(source: &str) -> Self {
        let suffix = NEXT_TEMP.fetch_add(1, Ordering::Relaxed);
        let path = std::env::temp_dir().join(format!(
            "gantry-interpreter-facade-{}-{suffix}",
            std::process::id()
        ));
        fs::create_dir(&path)
            .unwrap_or_else(|error| panic!("could not create {}: {error}", path.display()));
        fs::write(path.join("main.gnt"), source)
            .unwrap_or_else(|error| panic!("could not write facade fixture: {error}"));
        Self(path)
    }
}

impl Drop for TempDirectory {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

/// Executor fixture that holds the first task after semantic completion but
/// before its submitted-task handle becomes physically settled.
struct CompletionGateExecutor {
    inner: DeterministicExecutor,
    gate_first_task: AtomicBool,
    at_gate: CancellationSignal,
    release: CancellationSignal,
}

impl CompletionGateExecutor {
    fn new() -> Self {
        Self {
            inner: DeterministicExecutor::new([], []),
            gate_first_task: AtomicBool::new(true),
            at_gate: CancellationSignal::default(),
            release: CancellationSignal::default(),
        }
    }

    async fn wait_until_gated(&self) {
        self.at_gate.cancelled().await;
    }

    fn release(&self) {
        let _ = self.release.cancel();
    }
}

impl ExecutorAdapter for CompletionGateExecutor {
    fn spawn(&self, task: OwnedTaskFuture) -> Result<Box<dyn SubmittedTask>, HostError> {
        if self.gate_first_task.swap(false, Ordering::AcqRel) {
            let at_gate = self.at_gate.clone();
            let release = self.release.clone();
            self.inner.spawn(Box::pin(async move {
                let result = task.await;
                let _ = at_gate.cancel();
                release.cancelled().await;
                result
            }))
        } else {
            self.inner.spawn(task)
        }
    }

    fn sleep<'a>(&'a self, _: DurationMicros) -> HostFuture<'a, Result<(), HostError>> {
        Box::pin(std::future::pending())
    }

    fn yield_now<'a>(&'a self) -> HostFuture<'a, Result<(), HostError>> {
        self.inner.yield_now()
    }

    fn sample_inclusive(&self, range: InclusiveJitterRange) -> Result<u64, HostError> {
        self.inner.sample_inclusive(range)
    }
}

#[test]
fn public_interpreter_drives_and_observes_one_sequential_execution() {
    let root = TempDirectory::new("fn main() -> Int { 1 + 2 }");
    let identities = Arc::new(DeterministicIdentitySource::new(
        (1_u8..=16).map(|byte| Ok([byte; 32])),
    ));
    let executor = Arc::new(CompletionGateExecutor::new());
    let clock = execution_clock(1);
    let integration = Arc::new(ScriptedIntegration::new([], []));
    let configuration = configuration(executor.clone(), identities);
    let interpreter = Interpreter::new(
        configuration,
        clock,
        integration.clone(),
        integration.clone(),
        integration,
    );
    let selection = selection();

    let started = block_on(interpreter.start_execution(StartExecutionRequest {
        package_root: &root.0,
        protocol_selection: &selection,
        required_peers: &[],
        entry_input: None,
        root_session: None,
        event_delivery: None,
    }));
    let StartExecutionResult::Accepted(accepted) = started else {
        panic!("valid deterministic execution was rejected")
    };
    let execution_id = accepted.execution_id();
    let handle = accepted.handle().clone();
    let initial = interpreter
        .query_execution(execution_id)
        .unwrap_or_else(|error| panic!("initial query failed: {error}"))
        .unwrap_or_else(|| panic!("accepted execution was not registered"));
    assert!(initial.foreground.is_none());
    assert!(initial.terminal.is_none());

    drop(accepted);
    let completed = block_on(interpreter.await_terminal(&handle))
        .unwrap_or_else(|error| panic!("terminal await failed: {error:?}"))
        .unwrap_or_else(|| panic!("accepted execution disappeared"));
    let foreground = completed
        .foreground
        .as_ref()
        .unwrap_or_else(|| panic!("foreground outcome was not fixed"));
    let gantry::runtime::MachineOutcome::Succeeded(value) = foreground else {
        panic!("deterministic execution did not succeed")
    };
    assert!(matches!(value.view(), LogicalValueView::Int(value) if value.get() == 3));
    assert_eq!(
        completed
            .terminal
            .as_ref()
            .map(|terminal| &terminal.foreground),
        completed.foreground.as_ref()
    );

    assert_eq!(
        block_on(interpreter.await_foreground(&handle))
            .unwrap_or_else(|error| panic!("foreground await failed: {error}")),
        Some(completed.clone())
    );
    assert_eq!(
        block_on(interpreter.await_terminal(&handle))
            .unwrap_or_else(|error| panic!("terminal await failed: {error}")),
        Some(completed.clone())
    );
    let cancellation = caller_cancellation_reason(Some(Arc::from("late")), 32)
        .unwrap_or_else(|error| panic!("cancellation reason failed: {error:?}"));
    assert!(matches!(
        block_on(interpreter.cancel_execution(execution_id, cancellation)),
        Ok(CancellationRecord::AlreadyTerminal(snapshot)) if *snapshot == completed
    ));

    block_on(executor.wait_until_gated());
    let mut first_shutdown = pin!(interpreter.shutdown());
    assert!(poll_once(first_shutdown.as_mut()).is_pending());
    executor.release();
    let first_shutdown =
        block_on(first_shutdown).unwrap_or_else(|error| panic!("shutdown failed: {error:?}"));
    let repeated_shutdown = block_on(interpreter.shutdown())
        .unwrap_or_else(|error| panic!("repeated shutdown failed: {error:?}"));
    assert!(Arc::ptr_eq(&first_shutdown, &repeated_shutdown));
    assert!(first_shutdown.orderly);
    assert!(first_shutdown.cohort.is_empty());
}

