            protected_diagnostic: None,
        })],
        [Ok(0)],
    ));
    let interpreter = Interpreter::new(
        configuration(
            executor,
            Arc::new(DeterministicIdentitySource::new(
                (97_u8..=120).map(|byte| Ok([byte; 32])),
            )),
        ),
        execution_clock(9),
        integration.clone(),
        integration.clone(),
        integration,
    );
    let selection = selection();
    let StartExecutionResult::Accepted(accepted) =
        block_on(interpreter.start_execution(StartExecutionRequest {
            package_root: &root.0,
            protocol_selection: &selection,
            required_peers: &[],
            entry_input: None,
            root_session: None,
            event_delivery: None,
        }))
    else {
        panic!("valid retry execution was rejected")
    };
    let handle = accepted.handle().clone();
    drop(accepted);
    let snapshot = block_on(interpreter.await_terminal(&handle))
        .unwrap_or_else(|error| panic!("retry execution await failed: {error:?}"))
        .unwrap_or_else(|| panic!("accepted retry execution disappeared"));
    assert!(matches!(
        snapshot.foreground,
        Some(gantry::runtime::MachineOutcome::Failed(ref failure))
            if failure.code
                == gantry::runtime::RuntimeCode::Operation(
                    gantry::portable::RuntimeErrorCategory::ExecutorFailure
                )
    ));
    assert_eq!(
        snapshot
            .terminal
            .as_ref()
            .map(|terminal| &terminal.foreground),
        snapshot.foreground.as_ref()
    );
}

