#[test]
fn last_external_facade_runs_unclean_cleanup_with_internal_activity_references() {
    let root = TempDirectory::new(
        "action read_only lookup() -> String;\nfn main() -> String { action lookup() }",
    );
    let executor = Arc::new(DeterministicConcurrentExecutor::default());
    let response_dropped = Arc::new(AtomicBool::new(false));
    let integration = Arc::new(PendingIntegration {
        response_dropped: Arc::clone(&response_dropped),
    });
    let weak = Arc::downgrade(&integration);
    let interpreter = interpreter(
        Arc::clone(&executor),
        integration.clone(),
        integration.clone(),
        integration,
    );
    let final_owner = interpreter.clone();
    let selection = selection();
    let mut start = Box::pin(interpreter.start_execution(StartExecutionRequest {
        package_root: &root.0,
        protocol_selection: &selection,
        required_peers: &[],
        entry_input: None,
        root_session: None,
        event_delivery: None,
    }));
    let deadline = Instant::now() + Duration::from_secs(2);
    while executor.task_ids().is_empty() {
        assert!(poll_once(start.as_mut()).is_pending());
        assert!(
            Instant::now() < deadline,
            "start did not transfer pending preflight ownership"
        );
        std::thread::yield_now();
    }
    assert_eq!(executor.task_ids(), [0]);
    drop(start);

    drop(interpreter);
    assert!(weak.upgrade().is_some());
    assert!(!response_dropped.load(Ordering::Acquire));
    assert_eq!(executor.poll_task(0), Ok(DeterministicTaskPoll::Pending));

    assert!(catch_unwind(AssertUnwindSafe(|| drop(final_owner))).is_ok());
    assert!(response_dropped.load(Ordering::Acquire));
    assert!(weak.upgrade().is_none());
    assert_eq!(executor.poll_task(0), Ok(DeterministicTaskPoll::Stopped));
}

#[test]
fn dropped_shutdown_waiter_does_not_abandon_the_unique_coordinator() {
    let root = TempDirectory::new("fn main() -> Int { 7 }");
    let executor = Arc::new(DeterministicConcurrentExecutor::default());
    executor.control_sleeps();
    let integration = Arc::new(ScriptedIntegration::new([], []));
    let interpreter = interpreter(
        Arc::clone(&executor),
        integration.clone(),
        integration.clone(),
        integration,
    );
    let observer = interpreter.clone();
    let selection = selection();
    let StartExecutionResult::Accepted(accepted) =
        block_on(interpreter.start_execution(StartExecutionRequest {
            package_root: &root.0,
            protocol_selection: &selection,
            required_peers: &[],
            entry_input: None,
            root_session: None,
            event_delivery: None,
        }))
    else {
        panic!("valid shutdown fixture was rejected")
    };
    let handle = accepted.handle().clone();
    let cancellation = handle
        .cancellation_signal()
        .unwrap_or_else(|error| panic!("cancellation signal failed: {error:?}"));
    drop(accepted);

    let mut first_waiter = Box::pin(interpreter.shutdown());
    assert!(poll_once(first_waiter.as_mut()).is_pending());
    assert_eq!(executor.task_ids(), [0, 1]);
    drop(first_waiter);
    assert!(!cancellation.is_cancelled());

    assert_eq!(executor.poll_task(1), Ok(DeterministicTaskPoll::Pending));
    assert!(!cancellation.is_cancelled());
    executor
        .release_sleep(0)
        .unwrap_or_else(|error| panic!("grace timer release failed: {error:?}"));
    assert_eq!(executor.poll_task(1), Ok(DeterministicTaskPoll::Pending));
    assert!(cancellation.is_cancelled());
    assert!(executor.is_runnable(0));
    assert!(matches!(
        executor.poll_task(0),
        Ok(DeterministicTaskPoll::Settled(_))
    ));
    let execution = block_on(observer.await_terminal(&handle))
        .unwrap_or_else(|error| panic!("cancelled execution await failed: {error:?}"))
        .unwrap_or_else(|| panic!("cancelled execution disappeared"));
    assert!(execution.foreground.is_some());
    assert_eq!(
        execution
            .terminal
            .as_ref()
            .map(|terminal| &terminal.foreground),
        execution.foreground.as_ref()
    );
    assert!(executor.is_runnable(1));
    assert!(matches!(
        executor.poll_task(1),
        Ok(DeterministicTaskPoll::Settled(_))
    ));

    let report = block_on(observer.shutdown())
        .unwrap_or_else(|error| panic!("shared shutdown failed: {error:?}"));
    let repeated = block_on(interpreter.shutdown())
        .unwrap_or_else(|error| panic!("repeated shutdown failed: {error:?}"));
    assert!(Arc::ptr_eq(&report, &repeated));
    assert!(report.orderly);
    assert_eq!(report.cohort.len(), 1);
}

#[test]
fn dropped_cancellation_waiter_does_not_abandon_nondurable_cleanup() {
    let root = TempDirectory::new("fn main() -> Int { 7 }");
    let executor = Arc::new(DeterministicConcurrentExecutor::default());
    executor.control_sleeps();
    let integration = Arc::new(ScriptedIntegration::new([], []));
    let interpreter = interpreter(
        Arc::clone(&executor),
        integration.clone(),
        integration.clone(),
        integration,
    );
    let selection = selection();
    let StartExecutionResult::Accepted(accepted) =
        block_on(interpreter.start_execution(StartExecutionRequest {
            package_root: &root.0,
            protocol_selection: &selection,
            required_peers: &[],
            entry_input: None,
            root_session: None,
            event_delivery: None,
        }))
    else {
        panic!("valid cancellation fixture was rejected")
    };
    let execution_id = accepted.execution_id();
    let handle = accepted.handle().clone();
    let signal = handle
        .cancellation_signal()
        .unwrap_or_else(|error| panic!("cancellation signal failed: {error:?}"));
    let reason = caller_cancellation_reason(Some(Arc::from("drop-caller")), 32)
        .unwrap_or_else(|error| panic!("cancellation reason failed: {error:?}"));

    let mut cancellation = Box::pin(interpreter.cancel_execution(execution_id, reason.clone()));
    assert!(poll_once(cancellation.as_mut()).is_pending());
    assert_eq!(executor.task_ids(), [0, 1]);
    drop(cancellation);
    assert!(!signal.is_cancelled());

    assert_eq!(executor.poll_task(1), Ok(DeterministicTaskPoll::Pending));
    assert!(signal.is_cancelled());
    assert!(matches!(
        executor.poll_task(0),
        Ok(DeterministicTaskPoll::Settled(_))
    ));
    assert!(matches!(
        executor.poll_task(1),
        Ok(DeterministicTaskPoll::Settled(_))
    ));

    let terminal = block_on(interpreter.await_terminal(&handle))
        .unwrap_or_else(|error| panic!("terminal await failed: {error:?}"))
        .unwrap_or_else(|| panic!("cancelled execution disappeared"));
    assert!(terminal.terminal.is_some());
    let joined = block_on(interpreter.cancel_execution(execution_id, reason))
        .unwrap_or_else(|error| panic!("joining cancellation failed: {error:?}"));
    assert!(matches!(joined, CancellationRecord::Accepted { .. }));
}

#[test]
fn public_cancellation_aborts_a_submitted_unpolled_driver() {
    let root = TempDirectory::new("fn main() -> Int { 11 }");
    let executor = Arc::new(DeterministicConcurrentExecutor::default());
    executor.control_sleeps();
    let integration = Arc::new(ScriptedIntegration::new([], []));
    let interpreter = interpreter(
        Arc::clone(&executor),
        integration.clone(),
        integration.clone(),
        integration,
    );
    let selection = selection();
    let StartExecutionResult::Accepted(accepted) =
        block_on(interpreter.start_execution(StartExecutionRequest {
            package_root: &root.0,
            protocol_selection: &selection,
            required_peers: &[],
            entry_input: None,
            root_session: None,
            event_delivery: None,
        }))
    else {
        panic!("valid unpolled cancellation fixture was rejected")
    };
    let execution_id = accepted.execution_id();
    let reason = caller_cancellation_reason(Some(Arc::from("stop-unpolled")), 32)
        .unwrap_or_else(|error| panic!("cancellation reason failed: {error:?}"));
    let mut cancellation = Box::pin(interpreter.cancel_execution(execution_id, reason));
    assert!(poll_once(cancellation.as_mut()).is_pending());
