    let to_source = journal_site.release(
        &permissions,
        &protected,
        ReleaseDestination::OrdinarySource,
        &mut budget,
    );
    assert_eq!(
        to_source.decision(),
        ReleaseDecision::Rejected(ReleaseRejection::DestinationMismatch)
    );
