struct FixtureContext {
    program: Arc<MachineProgram>,
}

fn fixture_context(format: &str) -> FixtureContext {
    FixtureContext {
        program: if matches!(
            format,
            "combined-checkpoint/v5"
                | "machine-checkpoint/v4"
                | "gantry.concurrent-durable-evidence/v5"
        ) {
            successor_program()
        } else if format == "gantry.concurrent-durable-evidence/v5-operation" {
            operation_program()
        } else {
            program()
        },
    }
}

fn program() -> Arc<MachineProgram> {
    Arc::new(
        MachineProgram::new(vec![Workflow {
            path: path("crate::main"),
            parameters: Vec::<Parameter>::new(),
            result: TypeDescriptor::UNIT,
            effects: EffectSet::default(),
            instructions: vec![
                Instruction {
                    site: position(0),
                    ty: TypeDescriptor::UNIT,
                    kind: InstructionKind::Push(LogicalValue::unit()),
                },
                Instruction {
                    site: position(1),
                    ty: TypeDescriptor::UNIT,
                    kind: InstructionKind::Return,
                },
            ],
        }])
        .unwrap_or_else(|error| panic!("program failed: {error:?}")),
    )
}

fn operation_program() -> Arc<MachineProgram> {
    Arc::new(
        MachineProgram::new(vec![Workflow {
            path: path("crate::main"),
            parameters: Vec::new(),
            result: TypeDescriptor::UNIT,
            effects: EffectSet::default(),
            instructions: vec![
                Instruction {
                    site: position(0),
                    ty: TypeDescriptor::UNIT,
                    kind: InstructionKind::Operation,
                },
                Instruction {
                    site: position(1),
                    ty: TypeDescriptor::UNIT,
                    kind: InstructionKind::Return,
                },
            ],
        }])
        .unwrap_or_else(|error| panic!("operation program failed: {error:?}")),
    )
}

fn successor_program() -> Arc<MachineProgram> {
    let root_path = path("crate::main");
    let callable = CanonicalCallableIdentity::free(&root_path, &[]);
    let body_identity = TaskBodyIdentity::new(callable.clone(), position(0));
    let body = ExecutableTaskBody::new(
        body_identity.clone(),
        TypeDescriptor::UNIT,
        Vec::new(),
        ExecutableTaskContext::v1(),
        vec![
            Instruction {
                site: position(0),
                ty: TypeDescriptor::UNIT,
                kind: InstructionKind::Push(LogicalValue::unit()),
            },
            Instruction {
                site: position(1),
                ty: TypeDescriptor::UNIT,
                kind: InstructionKind::TaskComplete,
            },
        ],
    )
    .unwrap_or_else(|error| panic!("successor task body failed: {error:?}"));
    let root = Workflow {
        path: root_path,
        parameters: Vec::new(),
        result: TypeDescriptor::UNIT,
        effects: EffectSet::default(),
        instructions: vec![
            Instruction {
                site: position(0),
                ty: TypeDescriptor::UNIT,
                kind: InstructionKind::Spawn {
                    handle: ExecutableTaskHandle::new(Arc::from("child"), TypeDescriptor::UNIT)
                        .unwrap_or_else(|error| panic!("successor handle failed: {error:?}")),
                    body: body_identity,
                },
            },
            Instruction {
                site: position(1),
                ty: TypeDescriptor::UNIT,
                kind: InstructionKind::Push(LogicalValue::unit()),
            },
            Instruction {
                site: position(2),
                ty: TypeDescriptor::UNIT,
                kind: InstructionKind::Return,
            },
        ],
    };
    Arc::new(
        MachineProgram::with_task_bodies(vec![(callable, root)], vec![body])
            .unwrap_or_else(|error| panic!("successor program failed: {error:?}")),
    )
}

fn machine(
    program: Arc<MachineProgram>,
    execution: ProtocolIdentity,
    session: ProtocolIdentity,
) -> Machine {
    Machine::new_with_context(
        program,
        &path("crate::main"),
        Vec::new(),
        execution,
        MachineLimits::new(32, 4, 4, 8, 16, DEFAULT_VALUE_LIMITS)
            .unwrap_or_else(|| unreachable!("positive machine limits")),
        None,
        Some(session),
    )
    .unwrap_or_else(|error| panic!("machine failed: {error:?}"))
}

fn event_payload() -> EventPayload {
    EventPayload::from_validated_canonical_bytes(Arc::<[u8]>::from(&b"{}"[..]))
        .unwrap_or_else(|error| panic!("event payload failed: {error:?}"))
}

fn path(value: &str) -> CanonicalPath {
    CanonicalPath::new(value).unwrap_or_else(|error| panic!("path failed: {error}"))
}

fn position(value: u64) -> StructuralPosition {
    StructuralPosition::new(vec![value]).unwrap_or_else(|error| panic!("position failed: {error}"))
}

fn fresh(kind: IdentityKind, byte: u8) -> ProtocolIdentity {
    ProtocolIdentity::from_fresh_material(kind, [byte; 32])
        .unwrap_or_else(|error| panic!("identity failed: {error}"))
}

fn encode_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn decode_hex(value: &str) -> Vec<u8> {
    assert!(value.len().is_multiple_of(2));
    value
        .as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| {
            let pair = std::str::from_utf8(pair)
                .unwrap_or_else(|error| panic!("fixture hex failed: {error}"));
            u8::from_str_radix(pair, 16)
                .unwrap_or_else(|error| panic!("fixture hex failed: {error}"))
        })
        .collect()
}

fn write_fixture_golden(root: &Path, fixtures: &BTreeMap<String, Vec<u8>>) {
    let fixtures = fixtures
        .iter()
        .map(|(format, bytes)| {
            serde_json::json!({
                "format": format,
                "fixture_hex": encode_hex(bytes),
            })
        })
        .collect::<Vec<_>>();
    let mut bytes = serde_json::to_vec_pretty(&serde_json::json!({
        "format": "gantry.public-format-goldens/v1",
        "fixtures": fixtures,
    }))
    .unwrap_or_else(|error| panic!("could not render public-format golden: {error}"));
    bytes.push(b'\n');
    fs::write(root.join(GOLDEN_PATH), bytes)
        .unwrap_or_else(|error| panic!("could not write {GOLDEN_PATH}: {error}"));
}

fn sha256(bytes: &[u8]) -> String {
    use sha2::{Digest, Sha256};

    format!("{:x}", Sha256::digest(bytes))
}

fn specification_revision(root: &Path) -> String {
    use sha2::{Digest, Sha256};

    format!(
        "{:x}",
        Sha256::digest(
            fs::read(root.join("SPEC.md"))
                .unwrap_or_else(|error| panic!("could not read SPEC.md: {error}"))
        )
    )
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    let bytes =
        fs::read(path).unwrap_or_else(|error| panic!("could not read {}: {error}", path.display()));
    serde_json::from_slice(&bytes)
        .unwrap_or_else(|error| panic!("could not decode {}: {error}", path.display()))
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

//! Independent validation of the canonical Gantry publication-index contract.

use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};

use gantry::canonical_json::CanonicalJson;
use gantry::schema::SchemaValidator;
use gantry::strict_json::{JsonLimits, StrictJsonDocument};
use serde::Deserialize;
use serde_json::{Map, Value};
use sha2::{Digest, Sha256};

const INDEX_PATH: &str = "protocol/goldens/publication-index-v1.canonical.json";
const NEGATIVES_PATH: &str = "protocol/goldens/publication-index-v1.negatives.json";
const SCHEMA_PATH: &str = "protocol/schemas/publication-index-v1.schema.json";

const REQUIRED_ARTIFACTS: [&str; 7] = [
    "gantry.authoring",
    "gantry.conformance",
    "gantry.embedding",
    "gantry.ir",
    "gantry.journal",
    "gantry.spec",
    "gantry.values",
];

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct NegativeVectors {
    format: String,
    cases: Vec<NegativeCase>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct NegativeCase {
    name: String,
    mutation: String,
}

#[test]
fn canonical_publication_index_fixture_is_exact_and_complete() {
    let root = workspace_root();
    let bytes = read(&root.join(INDEX_PATH));
    let schema = read(&root.join(SCHEMA_PATH));
    let document = decode(&bytes);
    let canonical = CanonicalJson::from_document(&document)
        .unwrap_or_else(|error| panic!("index canonicalization failed: {error:?}"));
    assert_eq!(
        canonical.bytes(),
        bytes.strip_suffix(b"\n").unwrap_or(&bytes)
    );

    let validator = SchemaValidator::compile(schema, json_limits(2_000_000))
        .unwrap_or_else(|error| panic!("publication schema failed: {error:?}"));
    assert_eq!(validator.validate(&document), Ok(Vec::new()));

    let index: Value = serde_json::from_slice(&bytes)
        .unwrap_or_else(|error| panic!("publication fixture failed: {error}"));
    assert_eq!(validate_index(&root, &index), Ok(()));
}

#[test]
fn publication_index_negative_fixtures_are_all_rejected() {
    let root = workspace_root();
    let source: Value = serde_json::from_slice(&read(&root.join(INDEX_PATH)))
        .unwrap_or_else(|error| panic!("publication fixture failed: {error}"));
    let negatives: NegativeVectors = read_json(&root.join(NEGATIVES_PATH));
    assert_eq!(negatives.format, "gantry.publication-index-negatives/v1");
    assert_eq!(negatives.cases.len(), 20);
    assert!(
        negatives
            .cases
            .windows(2)
            .all(|pair| pair[0].name < pair[1].name)
    );

    for case in negatives.cases {
        let mutated = mutate(&source, &case.mutation);
        assert!(
            validate_index(&root, &mutated).is_err(),
            "accepted negative publication fixture {} ({})",
            case.name,
            case.mutation
        );
    }
}

fn validate_index(root: &Path, index: &Value) -> Result<(), String> {
    let object = exact_object(
        index,
        &[
            "artifacts",
            "publication_index",
            "publication_revision",
            "source_language",
        ],
    )?;
    validate_version(field(object, "publication_index")?)?;
    validate_version(field(object, "source_language")?)?;
    let revision = string(field(object, "publication_revision")?)?;
    if revision.is_empty() {
        return Err("publication revision is empty".to_owned());
    }

    let requirements = registered_requirements(root)?;
    let requirement_names = requirements
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    let profiles = BTreeSet::from([
        "analyzer",
        "concurrent-evaluator",
        "durable-runtime",
        "embedding",
        "evaluator",
        "frontend",
    ]);
    let protocols = BTreeSet::from([
        "canonical-ir",
        "configuration",
        "embedding",
        "event",
        "hook",
        "journal",
        "recovery-projection",
        "source-language",
        "source-map",
        "value",
    ]);
    let artifacts = array(field(object, "artifacts")?)?;
    if artifacts.len() != REQUIRED_ARTIFACTS.len() {
        return Err("publication artifact set is incomplete".to_owned());
    }

    let mut ids = BTreeSet::new();
    let mut uris = BTreeSet::new();
    let mut defined_protocols = BTreeSet::new();
    let mut prior_id: Option<&str> = None;
    for (index, artifact) in artifacts.iter().enumerate() {
        let artifact = exact_object(
            artifact,
            &[
                "byte_length",
                "id",
                "media_type",
                "profiles",
                "protocols",
                "requirements",
                "sha256",
                "uri",
            ],
        )?;
        let id = string(field(artifact, "id")?)?;
        if REQUIRED_ARTIFACTS.get(index) != Some(&id)
            || prior_id.is_some_and(|prior| prior >= id)
            || !ids.insert(id)
        {
            return Err("artifact identifiers are missing, duplicated, or unordered".to_owned());
        }
        prior_id = Some(id);

        let uri = string(field(artifact, "uri")?)?;
        if !uri.starts_with("https://") || !uri.contains("/v1/") || !uris.insert(uri) {
            return Err("artifact URI is not absolute, versioned, and unique".to_owned());
        }
        let media_type = string(field(artifact, "media_type")?)?;
        if media_type.split_once('/').is_none()
            || media_type.bytes().any(|byte| byte.is_ascii_uppercase())
        {
            return Err("artifact media type is invalid".to_owned());
        }
        let byte_length = string(field(artifact, "byte_length")?)?;
        if !decimal_string(byte_length) || byte_length != "0" {
            return Err("fixture artifact length differs".to_owned());
        }
        let sha256 = string(field(artifact, "sha256")?)?;
        if !lowercase_sha256(sha256) || sha256 != format!("{:x}", Sha256::digest([])) {
            return Err("fixture artifact digest differs".to_owned());
        }

        validate_sorted_members(field(artifact, "profiles")?, &profiles, "profile")?;
        validate_sorted_members(
            field(artifact, "requirements")?,
            &requirement_names,
            "requirement",
        )?;
        let declared_protocols = array(field(artifact, "protocols")?)?;
        let mut prior_family: Option<&str> = None;
        for protocol in declared_protocols {
            let protocol = exact_object(protocol, &["family", "major", "minor"])?;
            let family = string(field(protocol, "family")?)?;
            if prior_family.is_some_and(|prior| prior >= family)
                || !protocols.contains(family)
                || !defined_protocols.insert(family)
            {
                return Err("protocol definitions are unknown, duplicated, or unordered".to_owned());
            }
            prior_family = Some(family);
            if field(protocol, "major")?.as_u64() != Some(1)
                || field(protocol, "minor")?.as_u64() != Some(0)
            {
                return Err("protocol version is not exactly 1.0".to_owned());
            }
        }
    }
    if ids != REQUIRED_ARTIFACTS.into_iter().collect() || defined_protocols != protocols {
        return Err("publication does not define the exact artifact and protocol sets".to_owned());
    }
    if object.contains_key("active_index_digest") {
        return Err("publication recursively embeds its active index".to_owned());
    }
    Ok(())
}

fn mutate(source: &Value, mutation: &str) -> Value {
    let mut value = source.clone();
    let root = value
        .as_object_mut()
        .unwrap_or_else(|| unreachable!("fixture root is an object"));
    match mutation {
        "add-root-field" => {
            root.insert("unexpected".to_owned(), Value::Bool(true));
        }
        "duplicate-family-definition" => {
            let protocols = artifact_mut(root, 3)["protocols"]
                .as_array_mut()
                .unwrap_or_else(|| unreachable!("protocols are an array"));
            protocols.push(protocols[0].clone());
        }
        "duplicate-artifact-id" => copy_artifact_field(root, 0, 1, "id"),
        "duplicate-artifact-uri" => copy_artifact_field(root, 0, 1, "uri"),
        "leading-zero-byte-length" => set_artifact(root, 0, "byte_length", "00"),
        "invalid-media-type" => set_artifact(root, 0, "media_type", "not-a-media-type"),
        "uppercase-sha256" => set_artifact(root, 0, "sha256", &"A".repeat(64)),
        "remove-required-artifact" => {
            artifacts_mut(root).pop();
        }
        "reverse-artifact-order" => artifacts_mut(root).reverse(),
        "reverse-profile-order" => artifact_mut(root, 1)["profiles"]
            .as_array_mut()
            .unwrap_or_else(|| unreachable!("profiles are an array"))
            .reverse(),
        "reverse-protocol-order" => artifact_mut(root, 2)["protocols"]
            .as_array_mut()
            .unwrap_or_else(|| unreachable!("protocols are an array"))
            .reverse(),
        "reverse-requirement-order" => {
            artifact_mut(root, 0)["requirements"] =
                serde_json::json!(["GNT-15.8-publication-integrity", "GNT-15.8"]);
        }
        "embed-active-index-digest" => {
            root.insert(
                "active_index_digest".to_owned(),
                Value::String("0".repeat(64)),
            );
        }
        "unknown-profile" => artifact_mut(root, 0)["profiles"] = serde_json::json!(["unknown"]),
        "unknown-protocol" => {
            artifact_mut(root, 2)["protocols"][0]["family"] = Value::String("unknown".to_owned());
        }
        "unknown-requirement" => {
            artifact_mut(root, 0)["requirements"] = serde_json::json!(["GNT-UNKNOWN"]);
        }
        "unversioned-uri" => set_artifact(
            root,
            0,
            "uri",
            "https://gantry.example/publication/gantry.authoring.json",
        ),
        "wrong-byte-length" => set_artifact(root, 0, "byte_length", "1"),
        "wrong-digest" => set_artifact(root, 0, "sha256", &"0".repeat(64)),
        "wrong-index-version" => root["publication_index"]["major"] = Value::from(2),
        other => panic!("unknown publication mutation {other}"),
    }
    value
}

fn registered_requirements(root: &Path) -> Result<BTreeSet<String>, String> {
    let registry: Value =
        read_json(&root.join("protocol/requirements/generated/requirements-v1.json"));
    let requirements = array(
        registry
            .get("requirements")
            .ok_or_else(|| "requirement registry has no requirements".to_owned())?,
    )?;
    requirements
        .iter()
        .map(|requirement| {
            requirement
                .get("id")
                .and_then(Value::as_str)
                .map(str::to_owned)
                .ok_or_else(|| "requirement registry contains an invalid ID".to_owned())
        })
        .collect()
}

fn validate_sorted_members(
    value: &Value,
    allowed: &BTreeSet<&str>,
    kind: &str,
) -> Result<(), String> {
    let values = array(value)?;
    let mut prior: Option<&str> = None;
    for value in values {
        let value = string(value)?;
        if prior.is_some_and(|prior| prior >= value) || !allowed.contains(value) {
            return Err(format!(
                "{kind} values are unknown, duplicated, or unordered"
            ));
        }
        prior = Some(value);
    }
    Ok(())
}

fn validate_version(value: &Value) -> Result<(), String> {
    let version = exact_object(value, &["major", "minor"])?;
    if field(version, "major")?.as_u64() != Some(1) || field(version, "minor")?.as_u64() != Some(0)
    {
        return Err("version is not exactly 1.0".to_owned());
    }
    Ok(())
}

fn exact_object<'a>(value: &'a Value, fields: &[&str]) -> Result<&'a Map<String, Value>, String> {
    let object = value
        .as_object()
        .ok_or_else(|| "expected a JSON object".to_owned())?;
    let actual = object.keys().map(String::as_str).collect::<BTreeSet<_>>();
    let expected = fields.iter().copied().collect::<BTreeSet<_>>();
    (actual == expected)
        .then_some(object)
        .ok_or_else(|| "object fields differ from the closed contract".to_owned())
}

fn field<'a>(object: &'a Map<String, Value>, name: &str) -> Result<&'a Value, String> {
    object
        .get(name)
        .ok_or_else(|| format!("missing field {name}"))
}

fn array(value: &Value) -> Result<&[Value], String> {
    value
        .as_array()
        .map(Vec::as_slice)
        .ok_or_else(|| "expected a JSON array".to_owned())
}

fn string(value: &Value) -> Result<&str, String> {
    value
        .as_str()
        .ok_or_else(|| "expected a JSON string".to_owned())
}

fn decimal_string(value: &str) -> bool {
    value == "0"
        || (!value.starts_with('0')
            && !value.is_empty()
            && value.bytes().all(|byte| byte.is_ascii_digit()))
}

fn lowercase_sha256(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
}

fn artifact_mut(root: &mut Map<String, Value>, index: usize) -> &mut Value {
    artifacts_mut(root)
        .get_mut(index)
        .unwrap_or_else(|| unreachable!("fixture artifact exists"))
}

fn artifacts_mut(root: &mut Map<String, Value>) -> &mut Vec<Value> {
    root.get_mut("artifacts")
        .and_then(Value::as_array_mut)
        .unwrap_or_else(|| unreachable!("fixture artifacts are an array"))
}

fn set_artifact(root: &mut Map<String, Value>, index: usize, field: &str, value: &str) {
    artifact_mut(root, index)[field] = Value::String(value.to_owned());
}

fn copy_artifact_field(root: &mut Map<String, Value>, source: usize, target: usize, field: &str) {
    let value = artifacts_mut(root)[source][field].clone();
    artifacts_mut(root)[target][field] = value;
}

fn decode(bytes: &[u8]) -> StrictJsonDocument {
    StrictJsonDocument::decode(bytes, json_limits(2_000_000))
        .unwrap_or_else(|error| panic!("strict JSON failed: {error:?}"))
}

fn json_limits(maximum: u64) -> JsonLimits {
    JsonLimits {
        maximum_bytes: maximum,
        maximum_nesting_depth: maximum,
        maximum_nodes: maximum,
        maximum_string_scalars: maximum,
        maximum_list_items: maximum,
    }
}

fn read(path: &Path) -> Vec<u8> {
    fs::read(path).unwrap_or_else(|error| panic!("could not read {}: {error}", path.display()))
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    serde_json::from_slice(&read(path))
        .unwrap_or_else(|error| panic!("could not decode {}: {error}", path.display()))
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

//! Independent validation of the active immutable Gantry publication set.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

use gantry::canonical_json::CanonicalJson;
use gantry::schema::SchemaValidator;
use gantry::strict_json::{JsonLimits, StrictJsonDocument};
use serde::Deserialize;
use serde_json::{Map, Value};
use sha2::{Digest, Sha256};

const ARTIFACT_SCHEMA_PATH: &str = "protocol/schemas/publication-artifact-v1.schema.json";
const INDEX_PATH: &str = "protocol/publication/index-v1.json";
const INDEX_SCHEMA_PATH: &str = "protocol/schemas/publication-index-v1.schema.json";
const NEGATIVES_PATH: &str = "protocol/goldens/publication-index-v1.negatives.json";
const REPORT_PATH: &str = "protocol/publication/verification-v1.json";
const REQUIREMENTS_PATH: &str = "protocol/requirements/generated/requirements-v1.json";
const ADOPTION_PATH: &str = "protocol/conformance/async-execution-adoption-v1.json";

const REQUIRED_ARTIFACTS: [&str; 7] = [
    "gantry.authoring",
    "gantry.conformance",
    "gantry.embedding",
    "gantry.ir",
    "gantry.journal",
    "gantry.spec",
    "gantry.values",
];

const PROTOCOL_FAMILIES: [&str; 10] = [
    "canonical-ir",
    "configuration",
    "embedding",
    "event",
    "hook",
    "journal",
    "recovery-projection",
    "source-language",
    "source-map",
    "value",
];

#[derive(Clone, Debug, Deserialize, Eq, PartialEq)]
#[serde(deny_unknown_fields)]
struct ProtocolVersion {
    family: String,
    major: u64,
    minor: u64,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct PublicationIndex {
    publication_index: Version,
    source_language: Version,
    publication_revision: String,
    artifacts: Vec<IndexArtifact>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct Version {
    major: u64,
    minor: u64,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct IndexArtifact {
    id: String,
    uri: String,
    media_type: String,
    byte_length: String,
    sha256: String,
    protocols: Vec<ProtocolVersion>,
    profiles: Vec<String>,
    requirements: Vec<String>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct PublicationArtifact {
    format: String,
    id: String,
    specification_sha256: String,
    protocols: Vec<ProtocolVersion>,
    profiles: Vec<String>,
    requirements: Vec<String>,
    files: Vec<ArtifactFile>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ArtifactFile {
    path: String,
    media_type: String,
    byte_length: String,
    sha256: String,
    content: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct VerificationReport {
    format: String,
    publication_set_identity: String,
    index: DigestRecord,
    artifacts: Vec<ReportArtifact>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct DigestRecord {
    path: String,
    byte_length: String,
    sha256: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ReportArtifact {
    id: String,
    path: String,
    byte_length: String,
    sha256: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct NegativeVectors {
    format: String,
    cases: Vec<NegativeCase>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct NegativeCase {
    name: String,
    mutation: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct AsyncAdoption {
    format: String,
    gate: String,
    status: String,
    specification_sha256: String,
    amended_profiles: Vec<String>,
    advertises_profiles: Vec<String>,
    blocked_by: Vec<String>,
}

#[test]
fn active_publication_set_is_canonical_complete_and_self_contained() {
    let root = workspace_root();
    let adoption: AsyncAdoption = read_json(&root.join(ADOPTION_PATH));
    assert_eq!(adoption.format, "gantry.async-execution-adoption/v1");
    assert_eq!(adoption.gate, "GNT-ASYNC-GATE-000");
    assert_eq!(adoption.status, "verified");
    assert_eq!(
        adoption.specification_sha256,
        sha256(&read(&root.join("SPEC.md")))
    );
    assert_eq!(adoption.amended_profiles.len(), 6);
    assert_eq!(adoption.advertises_profiles, adoption.amended_profiles);
    assert!(adoption.blocked_by.is_empty());
    assert!(!adoption.blocked_by.contains(&adoption.gate));
    assert!(gantry::advertises_any_profile());
    let index_bytes = read(&root.join(INDEX_PATH));
    assert_canonical_and_schema_valid(&root, INDEX_SCHEMA_PATH, &index_bytes);
    let index: PublicationIndex = decode(&index_bytes, INDEX_PATH);
    assert_eq!(
        (index.publication_index.major, index.publication_index.minor),
        (1, 0)
    );
    assert_eq!(
        (index.source_language.major, index.source_language.minor),
        (1, 0)
    );
    assert_eq!(
        index.publication_revision,
        format!("gantry-v1-{}", sha256(&read(&root.join("SPEC.md"))))
    );
    assert_eq!(
        index
            .artifacts
            .iter()
            .map(|artifact| artifact.id.as_str())
            .collect::<Vec<_>>(),
        REQUIRED_ARTIFACTS
    );

    let registered_requirements = registered_requirements(&root);
    let known_profiles = BTreeSet::from([
        "analyzer",
        "concurrent-evaluator",
        "durable-runtime",
        "embedding",
        "evaluator",
        "frontend",
    ]);
    let mut protocol_owners = BTreeMap::<String, String>::new();
    let mut uris = BTreeSet::new();
    let mut resolved = BTreeMap::<String, (String, Vec<u8>)>::new();
    let specification_sha256 = sha256(&read(&root.join("SPEC.md")));
    let publication_set_identity = sha256(&index_bytes);
    for artifact in &index.artifacts {
        assert!(
            artifact
                .uri
                .starts_with("https://github.com/NFJones/gantry/releases/download/v1.0.0/")
        );
        assert!(uris.insert(artifact.uri.as_str()));
        assert!(decimal_string(&artifact.byte_length));
        assert!(lowercase_sha256(&artifact.sha256));
        assert!(artifact.profiles.windows(2).all(|pair| pair[0] < pair[1]));
        assert!(
            artifact
                .requirements
                .windows(2)
                .all(|pair| pair[0] < pair[1])
        );
        assert!(
            artifact
                .profiles
                .iter()
                .all(|profile| known_profiles.contains(profile.as_str()))
        );
        assert!(
            artifact
                .requirements
                .iter()
                .all(|requirement| registered_requirements.contains(requirement))
        );
        assert!(
            artifact
                .protocols
                .windows(2)
                .all(|pair| pair[0].family < pair[1].family)
        );
        for protocol in &artifact.protocols {
            assert_eq!((protocol.major, protocol.minor), (1, 0));
            assert!(PROTOCOL_FAMILIES.contains(&protocol.family.as_str()));
            assert!(
                protocol_owners
                    .insert(protocol.family.clone(), artifact.id.clone())
                    .is_none()
            );
        }

        let path = artifact_path(&root, &artifact.id);
        let bytes = read(&path);
        assert_eq!(artifact.byte_length, bytes.len().to_string());
        assert_eq!(artifact.sha256, sha256(&bytes));
        if artifact.id == "gantry.spec" {
            assert_eq!(artifact.media_type, "text/markdown");
            assert_eq!(sha256(&bytes), specification_sha256);
            assert_eq!(bytes, read(&root.join("SPEC.md")));
        } else {
            assert_eq!(artifact.media_type, "application/json");
            assert_canonical_and_schema_valid(&root, ARTIFACT_SCHEMA_PATH, &bytes);
            let bundle: PublicationArtifact = decode(&bytes, &path.display().to_string());
            assert_eq!(bundle.format, "gantry.publication-artifact/v1");
            assert_eq!(bundle.id, artifact.id);
            assert_eq!(bundle.specification_sha256, specification_sha256);
            assert_eq!(bundle.protocols, artifact.protocols);
            assert_eq!(bundle.profiles, artifact.profiles);
            assert_eq!(bundle.requirements, artifact.requirements);
            assert!(!bundle.files.is_empty());
            assert!(
                bundle
                    .files
                    .windows(2)
                    .all(|pair| pair[0].path < pair[1].path)
            );
            let mut paths = BTreeSet::new();
            for file in &bundle.files {
                assert!(paths.insert(file.path.as_str()));
                assert!(!file.path.starts_with("protocol/publication/v1/"));
                assert_ne!(file.path, INDEX_PATH);
                assert_ne!(file.path, REPORT_PATH);
                assert!(matches!(
                    file.media_type.as_str(),
                    "application/json" | "text/markdown" | "text/plain" | "text/x-rust"
                ));
                assert!(decimal_string(&file.byte_length));
                assert!(lowercase_sha256(&file.sha256));
                let content = file.content.as_bytes();
                assert_eq!(file.byte_length, content.len().to_string(), "{}", file.path);
                assert_eq!(file.sha256, sha256(content), "{}", file.path);
                assert_eq!(content, read(&root.join(&file.path)), "{}", file.path);
            }
            assert!(
                !bytes
                    .windows(publication_set_identity.len())
                    .any(|window| window == publication_set_identity.as_bytes())
            );
        }
        resolved.insert(artifact.id.clone(), (relative_path(&root, &path), bytes));
    }
    assert_eq!(
        protocol_owners
            .keys()
            .map(String::as_str)
            .collect::<Vec<_>>(),
        PROTOCOL_FAMILIES
    );
    assert_required_bundle_members(&root, &resolved);

    let report_bytes = read(&root.join(REPORT_PATH));
    assert_canonical(&report_bytes);
    let report: VerificationReport = decode(&report_bytes, REPORT_PATH);
    assert_eq!(report.format, "gantry.publication-verification/v1");
    assert_eq!(report.publication_set_identity, publication_set_identity);
    assert_eq!(report.index.path, INDEX_PATH);
    assert_eq!(report.index.byte_length, index_bytes.len().to_string());
    assert_eq!(report.index.sha256, sha256(&index_bytes));
    assert_eq!(report.artifacts.len(), REQUIRED_ARTIFACTS.len());
    for artifact in &report.artifacts {
        let (path, bytes) = resolved
            .get(&artifact.id)
            .unwrap_or_else(|| panic!("unknown report artifact {}", artifact.id));
        assert_eq!(&artifact.path, path);
        assert_eq!(artifact.byte_length, bytes.len().to_string());
        assert_eq!(artifact.sha256, sha256(bytes));
    }
}

#[test]
fn active_publication_set_rejects_all_integrity_mutations() {
    let root = workspace_root();
    let source: Value = read_json(&root.join(INDEX_PATH));
    let negatives: NegativeVectors = read_json(&root.join(NEGATIVES_PATH));
    assert_eq!(negatives.format, "gantry.publication-index-negatives/v1");
    assert_eq!(negatives.cases.len(), 20);
    for case in negatives.cases {
        let mutated = mutate(&source, &case.mutation);
        assert!(
            validate_active_index(&root, &mutated).is_err(),
            "accepted active-index mutation {} ({})",
            case.name,
            case.mutation
        );
    }
}

fn validate_active_index(root: &Path, value: &Value) -> Result<(), String> {
    let object = exact_object(
        value,
        &[
            "artifacts",
            "publication_index",
            "publication_revision",
            "source_language",
        ],
    )?;
    validate_version(field(object, "publication_index")?)?;
    validate_version(field(object, "source_language")?)?;
    if string(field(object, "publication_revision")?)?.is_empty() {
        return Err("empty publication revision".to_owned());
    }
    let artifacts = array(field(object, "artifacts")?)?;
    if artifacts.len() != REQUIRED_ARTIFACTS.len() {
        return Err("publication member count differs".to_owned());
    }
    let requirements = registered_requirements(root);
    let profiles = BTreeSet::from([
        "analyzer",
        "concurrent-evaluator",
        "durable-runtime",
        "embedding",
        "evaluator",
        "frontend",
    ]);
    let protocols = PROTOCOL_FAMILIES.into_iter().collect::<BTreeSet<_>>();
    let mut ids = BTreeSet::new();
    let mut uris = BTreeSet::new();
    let mut definitions = BTreeSet::new();
    for (position, artifact) in artifacts.iter().enumerate() {
        let artifact = exact_object(
            artifact,
            &[
                "byte_length",
                "id",
                "media_type",
                "profiles",
                "protocols",
                "requirements",
                "sha256",
                "uri",
            ],
        )?;
        let id = string(field(artifact, "id")?)?;
        if REQUIRED_ARTIFACTS.get(position) != Some(&id) || !ids.insert(id) {
            return Err("artifact identifiers differ".to_owned());
        }
        let uri = string(field(artifact, "uri")?)?;
        if !uri.starts_with("https://") || !uri.contains("/v1.0.0/") || !uris.insert(uri) {
            return Err("artifact URI differs".to_owned());
        }
        let media_type = string(field(artifact, "media_type")?)?;
        if !matches!(media_type, "application/json" | "text/markdown") {
            return Err("artifact media type differs".to_owned());
        }
        let byte_length = string(field(artifact, "byte_length")?)?;
        let digest = string(field(artifact, "sha256")?)?;
        if !decimal_string(byte_length) || !lowercase_sha256(digest) {
            return Err("artifact integrity metadata is malformed".to_owned());
        }
        let path = artifact_path(root, id);
        let bytes =
            fs::read(&path).map_err(|error| format!("missing {}: {error}", path.display()))?;
        if byte_length != bytes.len().to_string() || digest != sha256(&bytes) {
            return Err("artifact integrity metadata differs".to_owned());
        }
        validate_sorted_allowed(field(artifact, "profiles")?, &profiles)?;
        validate_sorted_allowed(field(artifact, "requirements")?, &requirements)?;
        let mut prior = None;
        for protocol in array(field(artifact, "protocols")?)? {
            let protocol = exact_object(protocol, &["family", "major", "minor"])?;
            let family = string(field(protocol, "family")?)?;
            if prior.is_some_and(|prior| prior >= family)
                || !protocols.contains(family)
                || !definitions.insert(family)
            {
                return Err("protocol definitions differ".to_owned());
            }
            prior = Some(family);
            if field(protocol, "major")?.as_u64() != Some(1)
                || field(protocol, "minor")?.as_u64() != Some(0)
            {
                return Err("protocol version differs".to_owned());
            }
        }
    }
    if ids != REQUIRED_ARTIFACTS.into_iter().collect() || definitions != protocols {
        return Err("publication membership differs".to_owned());
    }
    Ok(())
}

fn assert_required_bundle_members(root: &Path, resolved: &BTreeMap<String, (String, Vec<u8>)>) {
    let required = BTreeMap::from([
        (
            "gantry.authoring",
            [
                "SPEC.md",
                "crates/gantry-conformance/tests/frontend_parser_evidence.rs",
                "protocol/requirements/section14-v1.json",
            ]
            .as_slice(),
        ),
        (
            "gantry.conformance",
            [
                "protocol/conformance/corpus-index-v1.json",
                "protocol/conformance/manifest-v1.json",
                "docs/async-execution-release.md",
                "protocol/goldens/publication-index-v1.canonical.json",
                "protocol/goldens/publication-index-v1.negatives.json",
                "protocol/schemas/conformance-corpus-index-v1.schema.json",
                "protocol/schemas/conformance-manifest-v1.schema.json",
                "protocol/schemas/publication-index-v1.schema.json",
            ]
            .as_slice(),
        ),
        (
            "gantry.embedding",
            [
                "protocol/catalogs/embedding-contracts-v1.json",
                "protocol/goldens/embedding-envelope-negatives-v1.json",
                "protocol/schemas/embedding-contracts-v1.schema.json",
            ]
            .as_slice(),
        ),
        (
            "gantry.ir",
            [
                "protocol/catalogs/ir-contracts-v1.json",
                "protocol/goldens/ir-artifact-vectors-v1.json",
                "protocol/schemas/canonical-ir-v1.schema.json",
                "protocol/schemas/package-source-manifest-v1.schema.json",
                "protocol/schemas/source-map-v1.schema.json",
            ]
            .as_slice(),
        ),
        (
            "gantry.journal",
            [
                "protocol/catalogs/public-formats-v1.json",
                "protocol/goldens/public-formats-v1.json",
                "protocol/schemas/public-checkpoint-formats-v1.schema.json",
                "protocol/schemas/public-journal-formats-v1.schema.json",
            ]
            .as_slice(),
        ),
        (
            "gantry.values",
            [
                "protocol/catalogs/portable-contracts-v1.json",
                "protocol/goldens/diagnostic-machine-v1.json",
                "protocol/goldens/value-kernel-v1.json",
                "protocol/schemas/canonical-transcript-v1.schema.json",
                "protocol/schemas/value-kernel-v1.schema.json",
            ]
            .as_slice(),
        ),
    ]);
    for (id, paths) in required {
        let (_, bytes) = resolved
            .get(id)
            .unwrap_or_else(|| panic!("missing required bundle {id}"));
        let bundle: PublicationArtifact = decode(bytes, id);
        let members = bundle
            .files
            .iter()
            .map(|file| file.path.as_str())
            .collect::<BTreeSet<_>>();
        for path in paths {
            assert!(members.contains(path), "{id} omits {path}");
            assert!(root.join(path).is_file());
        }
    }
}

fn mutate(source: &Value, mutation: &str) -> Value {
    let mut value = source.clone();
    let root = value
        .as_object_mut()
        .unwrap_or_else(|| unreachable!("active index is an object"));
    match mutation {
        "add-root-field" => {
            root.insert("unexpected".to_owned(), Value::Bool(true));
        }
        "duplicate-family-definition" => {
            let protocols = artifact_mut(root, 3)["protocols"]
                .as_array_mut()
                .unwrap_or_else(|| unreachable!("protocols are an array"));
            protocols.push(protocols[0].clone());
        }
        "duplicate-artifact-id" => copy_artifact_field(root, 0, 1, "id"),
        "duplicate-artifact-uri" => copy_artifact_field(root, 0, 1, "uri"),
        "leading-zero-byte-length" => set_artifact(root, 0, "byte_length", "00"),
        "invalid-media-type" => set_artifact(root, 0, "media_type", "not-a-media-type"),
        "uppercase-sha256" => set_artifact(root, 0, "sha256", &"A".repeat(64)),
        "remove-required-artifact" => {
            artifacts_mut(root).pop();
        }
        "reverse-artifact-order" => artifacts_mut(root).reverse(),
        "reverse-profile-order" => artifact_mut(root, 1)["profiles"]
            .as_array_mut()
            .unwrap_or_else(|| unreachable!("profiles are an array"))
            .reverse(),
        "reverse-protocol-order" => artifact_mut(root, 2)["protocols"]
            .as_array_mut()
            .unwrap_or_else(|| unreachable!("protocols are an array"))
            .reverse(),
        "reverse-requirement-order" => artifact_mut(root, 0)["requirements"]
            .as_array_mut()
            .unwrap_or_else(|| unreachable!("requirements are an array"))
            .reverse(),
        "embed-active-index-digest" => {
            root.insert(
                "active_index_digest".to_owned(),
                Value::String("0".repeat(64)),
            );
        }
        "unknown-profile" => artifact_mut(root, 0)["profiles"] = serde_json::json!(["unknown"]),
        "unknown-protocol" => {
            artifact_mut(root, 2)["protocols"][0]["family"] = Value::String("unknown".to_owned());
        }
        "unknown-requirement" => {
            artifact_mut(root, 0)["requirements"] = serde_json::json!(["GNT-UNKNOWN"]);
        }
        "unversioned-uri" => set_artifact(
            root,
            0,
            "uri",
            "https://github.com/NFJones/gantry/releases/download/gantry.authoring.json",
        ),
        "wrong-byte-length" => set_artifact(root, 0, "byte_length", "1"),
        "wrong-digest" => set_artifact(root, 0, "sha256", &"0".repeat(64)),
        "wrong-index-version" => root["publication_index"]["major"] = Value::from(2),
        other => panic!("unknown publication mutation {other}"),
    }
    value
}

fn artifact_path(root: &Path, id: &str) -> PathBuf {
    let name = if id == "gantry.spec" {
        "SPEC.md".to_owned()
    } else {
        format!("{id}.json")
    };
    root.join("protocol/publication/v1").join(name)
}

fn assert_canonical_and_schema_valid(root: &Path, schema_path: &str, bytes: &[u8]) {
    let document = StrictJsonDocument::decode(bytes.to_vec(), json_limits(16_000_000))
        .unwrap_or_else(|error| panic!("strict JSON failed: {error:?}"));
    let canonical = CanonicalJson::from_document(&document)
        .unwrap_or_else(|error| panic!("canonicalization failed: {error:?}"));
    assert_eq!(
        canonical.bytes(),
        bytes.strip_suffix(b"\n").unwrap_or(bytes)
    );
    let validator =
        SchemaValidator::compile(read(&root.join(schema_path)), json_limits(16_000_000))
            .unwrap_or_else(|error| panic!("could not compile {schema_path}: {error:?}"));
    assert_eq!(validator.validate(&document), Ok(Vec::new()));
}

fn assert_canonical(bytes: &[u8]) {
    let document = StrictJsonDocument::decode(bytes.to_vec(), json_limits(16_000_000))
        .unwrap_or_else(|error| panic!("strict JSON failed: {error:?}"));
    let canonical = CanonicalJson::from_document(&document)
        .unwrap_or_else(|error| panic!("canonicalization failed: {error:?}"));
    assert_eq!(
        canonical.bytes(),
        bytes.strip_suffix(b"\n").unwrap_or(bytes)
    );
}

fn registered_requirements(root: &Path) -> BTreeSet<String> {
    let registry: Value = read_json(&root.join(REQUIREMENTS_PATH));
    registry["requirements"]
        .as_array()
        .unwrap_or_else(|| panic!("requirement registry has no requirements"))
        .iter()
        .map(|requirement| {
            requirement["id"]
                .as_str()
                .unwrap_or_else(|| panic!("requirement has no id"))
                .to_owned()
        })
        .collect()
}

fn validate_sorted_allowed<T>(value: &Value, allowed: &BTreeSet<T>) -> Result<(), String>
where
    T: std::borrow::Borrow<str> + Ord,
{
    let values = array(value)?;
    let mut prior = None;
    for value in values {
        let value = string(value)?;
        if prior.is_some_and(|prior| prior >= value) || !allowed.contains(value) {
            return Err("member list differs".to_owned());
        }
        prior = Some(value);
    }
    Ok(())
}

fn validate_version(value: &Value) -> Result<(), String> {
    let version = exact_object(value, &["major", "minor"])?;
    if field(version, "major")?.as_u64() != Some(1) || field(version, "minor")?.as_u64() != Some(0)
    {
        return Err("version differs".to_owned());
    }
    Ok(())
}

fn exact_object<'a>(value: &'a Value, fields: &[&str]) -> Result<&'a Map<String, Value>, String> {
    let object = value
        .as_object()
        .ok_or_else(|| "expected object".to_owned())?;
    let actual = object.keys().map(String::as_str).collect::<BTreeSet<_>>();
    let expected = fields.iter().copied().collect::<BTreeSet<_>>();
    (actual == expected)
        .then_some(object)
        .ok_or_else(|| "object fields differ".to_owned())
}

fn field<'a>(object: &'a Map<String, Value>, name: &str) -> Result<&'a Value, String> {
    object
        .get(name)
        .ok_or_else(|| format!("missing field {name}"))
}

fn array(value: &Value) -> Result<&[Value], String> {
    value
        .as_array()
        .map(Vec::as_slice)
        .ok_or_else(|| "expected array".to_owned())
}

fn string(value: &Value) -> Result<&str, String> {
    value.as_str().ok_or_else(|| "expected string".to_owned())
}

fn decimal_string(value: &str) -> bool {
    value == "0"
        || (!value.starts_with('0')
            && !value.is_empty()
            && value.bytes().all(|byte| byte.is_ascii_digit()))
}

fn lowercase_sha256(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
}

fn artifact_mut(root: &mut Map<String, Value>, index: usize) -> &mut Value {
    artifacts_mut(root)
        .get_mut(index)
        .unwrap_or_else(|| unreachable!("artifact exists"))
}

fn artifacts_mut(root: &mut Map<String, Value>) -> &mut Vec<Value> {
    root.get_mut("artifacts")
        .and_then(Value::as_array_mut)
        .unwrap_or_else(|| unreachable!("artifacts are an array"))
}

fn set_artifact(root: &mut Map<String, Value>, index: usize, field: &str, value: &str) {
    artifact_mut(root, index)[field] = Value::String(value.to_owned());
}

fn copy_artifact_field(root: &mut Map<String, Value>, source: usize, target: usize, field: &str) {
    let value = artifacts_mut(root)[source][field].clone();
    artifacts_mut(root)[target][field] = value;
}

fn relative_path(root: &Path, path: &Path) -> String {
    path.strip_prefix(root)
        .unwrap_or_else(|_| panic!("{} is outside workspace", path.display()))
        .to_string_lossy()
        .replace('\\', "/")
}

fn sha256(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

const fn json_limits(maximum: u64) -> JsonLimits {
    JsonLimits {
        maximum_bytes: maximum,
        maximum_nesting_depth: maximum,
        maximum_nodes: maximum,
        maximum_string_scalars: maximum,
        maximum_list_items: maximum,
    }
}

fn decode<T: serde::de::DeserializeOwned>(bytes: &[u8], path: &str) -> T {
    serde_json::from_slice(bytes).unwrap_or_else(|error| panic!("could not decode {path}: {error}"))
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    decode(&read(path), &path.display().to_string())
}

fn read(path: &Path) -> Vec<u8> {
    fs::read(path).unwrap_or_else(|error| panic!("could not read {}: {error}", path.display()))
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

//! Machine-checked conformance for the authenticated package-acquisition and registry-trust
//! model of `SPEC.md` Section 27, clauses `GNT-27.1` .. `GNT-27.14`.
//!
//! These tests exercise the public `gantry::ir::registry` surface that Section 27 publishes, one
//! test per clause:
//! `GNT-27.1-immutable-source-identity-and-source-kind-vocabulary`,
//! `GNT-27.2-canonical-publication-names-and-external-name-mapping`,
//! `GNT-27.3-authenticated-metadata-snapshot-and-client-verification`,
//! `GNT-27.4-trust-roots-and-delegated-authority`,
//! `GNT-27.5-key-rotation-and-compromise-recovery`,
//! `GNT-27.6-expiry-freshness-and-offline-mode`,
//! `GNT-27.7-rollback-and-freeze-resistance`,
//! `GNT-27.8-publication-immutability`,
//! `GNT-27.9-yank-semantics`,
//! `GNT-27.10-security-revocation`,
//! `GNT-27.11-vcs-path-and-vendor-source-verification`,
//! `GNT-27.12-lockfile-evidence-binding`,
//! `GNT-27.13-trust-failure-attribution`, and
//! `GNT-27.14-registry-non-claims`.
//!
//! Every test is a pure function of its own arguments: no test reads a clock, a host path, an
//! environment variable, a network answer, or a registry response, and no test waits on a handle.
//! Epochs, checkouts, vendored directories, mirror bindings, and signature values are declared
//! inputs, and every digest is derived here from a declared seed, so every verdict below is
//! reproducible from its own inputs.
//!
//! Each test states one admissible path and at least one falsifiable refusal: an unauthorized
//! publisher, changed bytes, stale or expired metadata, a refused key rotation, a rollback or
//! freeze, a yank, a revocation, a pinned checkout, a modified path, a vendored directory, a
//! mirror substitution, and stale lockfile evidence are each decided here.

use gantry::ir::TargetKind;
use gantry::ir::registry::{
    AcquisitionRouteKind, AdvisoryBoundary, AdvisoryScope, AdvisorySetProof, AdvisoryStore,
    AliasBinding, AliasBindings, AuthorityScope, AuthorizationDefect, CommitId, Compromise,
    ConfigurationAlias, DeclaredSignature, Delegation, DelegationTiming, DeliveredRelease,
    EntryAuthority, EpochObservation, EvidenceDefect, ExternalAliasMap, ExternalName,
    FreshnessMode, KeyId, KeyRecord, LockedDependency, Lockfile, LockfileInputs, LockfileRecord,
    MetadataSnapshot, MirrorBinding, MirrorDefect, PathPin, PinDefect, PinnedTree,
    PublicationDefect, PublicationLedger, PublicationNameSet, PublicationState, PublisherIdentity,
    REGISTRY_CLAUSES, REGISTRY_NON_CLAIM_ORDER, REGISTRY_NON_CLAIMS, RegistryDiagnosticCode,
    RegistryError, RegistryName, RegistryNameKind, RegistryNonClaim, RegistryNonClaimAssertion,
    RegistryRefusal, RetainedState, RootId, RootSelectionPolicy, RotationContext, RotationDefect,
    RotationEvidence, RotationSignatures, RotationTiming, RunRequest, SecurityAdvisory, Severity,
    SnapshotDependency, SnapshotEntry, SourceAlias, SourceDeclaration, SourceIdentity, SourceKind,
    TargetArtifact, TrustFailureReason, TrustRoot, TrustStore, VcsPin, VendorDefect,
    VendorDirectory, VendorEntry, VerificationInput, VerifiedSnapshot, check_registry_non_claims,
    collision, declared_signature, resolve_new_release, resolve_source, verify_mirror,
    verify_path_tree, verify_pinned_tree, verify_vendor,
};
use sha2::{Digest, Sha256};

/// Returns one declared digest derived from one declared seed.
fn digest(seed: &str) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(seed.as_bytes());
    hasher.finalize().into()
}

/// Returns the admitted value of one trust decision.
fn admit<T>(outcome: Result<T, RegistryRefusal>, context: &str) -> T {
    match outcome {
        Ok(value) => value,
        Err(refusal) => panic!("{context}: {refusal}"),
    }
}

/// Returns the refusal that prevented one trust decision.
fn refuse<T>(outcome: Result<T, RegistryRefusal>, context: &str) -> RegistryRefusal {
    match outcome {
        Ok(_) => panic!("{context}: the decision was admitted"),
        Err(refusal) => refusal,
    }
}

/// Keeps single-record fixtures explicit about the sealed admission boundary they exercise.
#[allow(clippy::result_large_err)]
trait RotationTestExt {
    /// Admits one one-member sealed rotation set.
    fn rotate(
        &mut self,
        declaration: &SourceDeclaration,
        evidence: RotationEvidence,
        keys: &[KeyRecord],
    ) -> Result<(), RegistryRefusal>;

    /// Admits one one-member sealed rotation set under the selected root policy.
    fn rotate_with_root_selection(
        &mut self,
        declaration: &SourceDeclaration,
        evidence: RotationEvidence,
        keys: &[KeyRecord],
        root_policy: &RootSelectionPolicy,
    ) -> Result<(), RegistryRefusal>;
}

impl RotationTestExt for TrustStore {
    fn rotate(
        &mut self,
        declaration: &SourceDeclaration,
        evidence: RotationEvidence,
        keys: &[KeyRecord],
    ) -> Result<(), RegistryRefusal> {
        self.rotate_batch(declaration, std::slice::from_ref(&evidence), keys)
    }

    fn rotate_with_root_selection(
        &mut self,
        declaration: &SourceDeclaration,
        evidence: RotationEvidence,
        keys: &[KeyRecord],
        root_policy: &RootSelectionPolicy,
    ) -> Result<(), RegistryRefusal> {
        self.rotate_batch_with_root_selection(
            declaration,
            std::slice::from_ref(&evidence),
            keys,
            root_policy,
        )
    }
}

/// Returns the admitted value of one declaration decision.
fn accept<T>(outcome: Result<T, RegistryError>, context: &str) -> T {
    match outcome {
        Ok(value) => value,
        Err(error) => panic!("{context}: {error:?}"),
    }
}

/// Returns the typed condition that refused one declaration.
fn reject<T>(outcome: Result<T, RegistryError>, context: &str) -> RegistryError {
    match outcome {
        Ok(_) => panic!("{context}: the declaration was admitted"),
        Err(error) => error,
    }
}

/// Returns one validated name of one kind.
fn name(kind: RegistryNameKind, spelling: &str) -> RegistryName {
    accept(
        RegistryName::new(kind, spelling),
        "the declared name is valid",
    )
}

/// Returns one registry service identity for the namespace that publishes a package.
fn registry_source(namespace: &str, package: &str) -> SourceIdentity {
    let _ = package;
    accept(
        SourceIdentity::registry(&format!("{namespace}-registry")),
        "the declared registry source identity is valid",
    )
}

/// Returns one source declaration with an explicit package subject.
fn source_declaration(
    index: usize,
    alias: &str,
    package: &str,
    identity: SourceIdentity,
) -> SourceDeclaration {
    accept(
        SourceDeclaration::new(
            index,
            &format!("manifest:dependency:{index}"),
            alias,
            package,
            identity,
        ),
        "the declared source declaration is valid",
    )
}

/// Returns one source declaration with an explicit package subject.
#[allow(clippy::result_large_err)]
fn source_declaration_for(
    index: usize,
    alias: &str,
    package: &str,
    identity: SourceIdentity,
) -> Result<SourceDeclaration, RegistryError> {
    SourceDeclaration::new(
        index,
        &format!("manifest:dependency:{index}"),
        alias,
        package,
        identity,
    )
}

/// Returns one publisher identity.
fn publisher(name: &str, key: &str) -> PublisherIdentity {
    accept(
        PublisherIdentity::of(name, key),
        "the declared publisher identity is valid",
    )
}

/// Returns one key record whose declared material derives from its identity.
fn key(spelling: &str) -> KeyRecord {
    let identity = accept(KeyId::new(spelling), "the declared key identity is valid");
    accept(
        KeyRecord::new(identity, digest(spelling)),
        "the declared key record is valid",
    )
}

/// Returns one pinned commit identity.
fn commit(spelling: &str) -> CommitId {
    accept(
        CommitId::new(spelling),
        "the declared commit identity is valid",
    )
}

/// Returns one published snapshot entry.
fn entry(
    namespace: &str,
    package: &str,
    version: &str,
    publisher: &PublisherIdentity,
    manifest: &str,
    artifact: &str,
) -> SnapshotEntry {
    accept(
        SnapshotEntry::new(
            registry_source(namespace, package),
            namespace,
            package,
            version,
            publisher.clone(),
        ),
        "the declared snapshot entry is valid",
    )
    .with_manifest(digest(manifest))
    .with_artifact(digest(artifact))
    .with_target_artifact(accept(
        TargetArtifact::new(TargetKind::Library, digest(artifact)),
        "the declared target artifact is valid",
    ))
    .with_source_content(digest(&format!("source:{manifest}")))
    .with_generated(digest(&format!("generated:{artifact}")))
    .with_interface(digest(&format!("interface:{manifest}")))
}

/// Returns one published snapshot entry bound to an explicit non-registry source.
#[allow(clippy::too_many_arguments)]
fn entry_for_source(
    source: SourceIdentity,
    namespace: &str,
    package: &str,
    version: &str,
    publisher: &PublisherIdentity,
    manifest: &str,
    artifact: &str,
    source_content: [u8; 32],
) -> SnapshotEntry {
    entry(namespace, package, version, publisher, manifest, artifact)
        .with_source(source)
        .with_source_content(source_content)
}

/// Returns one metadata snapshot over one declared epoch window.
fn snapshot_of(
    sequence: u64,
    issue_epoch: u64,
    expiry_epoch: u64,
    entries: &[SnapshotEntry],
) -> MetadataSnapshot {
    accept(
        MetadataSnapshot::new(
            MetadataSnapshot::VERSION,
            entries[0].source().clone(),
            sequence,
            issue_epoch,
            expiry_epoch,
            entries,
        ),
        "the declared metadata snapshot is valid",
    )
}

/// Returns an authenticated snapshot fixture and its retained rollback evidence.
fn authenticated_fixture(
    _declaration: &SourceDeclaration,
    snapshot: &MetadataSnapshot,
) -> (TrustStore, RetainedState, Vec<DeclaredSignature>) {
    let entry = &snapshot.entries()[0];
    let record = key(entry.publisher().key().as_str());
    let trust = store_of(
        std::slice::from_ref(&root(
            "fixture-root",
            snapshot.source().clone(),
            entry.publisher().clone(),
            scope_of_namespace(entry.namespace().spelling()),
        )),
        std::slice::from_ref(&record),
        &[],
    );
    let retained = RetainedState::for_source(snapshot.source().clone(), snapshot.sequence())
        .with_content(snapshot.sequence(), snapshot.content_digest());
    let signatures = vec![declared_signature(&record, snapshot.content_digest())];
    (trust, retained, signatures)
}

/// Builds verification input with a signed proof for the authenticated empty advisory set.
fn verification_input<'a>(
    declarations: &'a [SourceDeclaration],
    snapshot: &'a MetadataSnapshot,
    signatures: &'a [DeclaredSignature],
    retained: &'a [RetainedState],
    publications: &'a PublicationLedger,
    observation: EpochObservation,
    freshness: FreshnessMode,
) -> VerificationInput<'a> {
    verification_input_with_advisories(
        declarations,
        snapshot,
        signatures,
        retained,
        publications,
        observation,
        freshness,
        AdvisoryStore::new(),
    )
}

/// Builds verification input with a signed proof for the supplied advisory set.
#[allow(clippy::too_many_arguments)]
fn verification_input_with_advisories<'a>(
    declarations: &'a [SourceDeclaration],
    snapshot: &'a MetadataSnapshot,
    signatures: &'a [DeclaredSignature],
    retained: &'a [RetainedState],
    publications: &'a PublicationLedger,
    observation: EpochObservation,
    freshness: FreshnessMode,
    advisories: AdvisoryStore,
) -> VerificationInput<'a> {
    verification_input_with_advisories_and_policy(
        declarations,
        snapshot,
        signatures,
        retained,
        publications,
        observation,
        freshness,
        advisories,
        RootSelectionPolicy::Unspecified,
    )
}

/// Builds verification input with a signed proof for the supplied advisory set and root policy.
#[allow(clippy::too_many_arguments)]
fn verification_input_with_advisories_and_policy<'a>(
    declarations: &'a [SourceDeclaration],
    snapshot: &'a MetadataSnapshot,
    signatures: &'a [DeclaredSignature],
    retained: &'a [RetainedState],
    publications: &'a PublicationLedger,
    observation: EpochObservation,
    freshness: FreshnessMode,
    advisories: AdvisoryStore,
    root_policy: RootSelectionPolicy,
) -> VerificationInput<'a> {
    let signer = key(snapshot.entries()[0].publisher().key().as_str());
    let proof = AdvisorySetProof::authenticated(
        snapshot,
        &advisories,
        root_policy.clone(),
        snapshot.entries()[0].publisher().clone(),
        &signer,
    );
    VerificationInput::new(
        declarations,
        snapshot,
        signatures,
        retained,
        publications,
        observation,
        freshness,
    )
    .with_root_selection(root_policy)
    .with_advisory_proof(advisories, proof)
}

/// Returns one ledger whose occupancy entered only through snapshot verification.
fn ledger_of(declaration: &SourceDeclaration, snapshot: &MetadataSnapshot) -> PublicationLedger {
    let (trust, retained, signatures) = authenticated_fixture(declaration, snapshot);
    let declarations = snapshot
        .entries()
        .iter()
        .enumerate()
        .map(|(index, entry)| {
            accept(
                source_declaration_for(
                    index,
                    &format!("fixture_{index}"),
                    entry.package().spelling(),
                    entry.source().clone(),
                ),
                "the fixture declaration owns the entry package subject",
            )
        })
        .collect::<Vec<_>>();
    let empty = PublicationLedger::new();
    let input = verification_input(
        &declarations,
        snapshot,
        &signatures,
        std::slice::from_ref(&retained),
        &empty,
        EpochObservation::at(snapshot.issue_epoch()),
        FreshnessMode::online(),
    );
    let verified = admit_snapshot(&trust, &input);
    let mut ledger = PublicationLedger::new();
    admit(
        ledger.admit_verified(&verified, &declarations),
        "the verified snapshot occupies the publication ledger",
    );
    ledger
}

/// Returns a historical lockfile record bound to prior authenticated evidence.
fn record_of(
    entry: &SnapshotEntry,
    snapshot: &MetadataSnapshot,
    declaration: &SourceDeclaration,
) -> LockfileRecord {
    record_with_inputs(
        entry,
        snapshot,
        declaration,
        LockfileInputs {
            targets: entry
                .target_artifacts()
                .iter()
                .map(TargetArtifact::target)
                .collect(),
            target_artifacts: entry.target_artifacts().to_vec(),
            ..LockfileInputs::default()
        },
    )
}

/// Returns a historical lockfile record with every caller-supplied bound input.
fn record_with_inputs(
    entry: &SnapshotEntry,
    snapshot: &MetadataSnapshot,
    declaration: &SourceDeclaration,
    inputs: LockfileInputs,
) -> LockfileRecord {
    let (trust, retained, signatures) = authenticated_fixture(declaration, snapshot);
    let declarations = snapshot
        .entries()
        .iter()
        .enumerate()
        .map(|(index, entry)| {
            accept(
                source_declaration_for(
                    index,
                    &format!("record_{index}"),
                    entry.package().spelling(),
                    entry.source().clone(),
                ),
                "the record fixture declaration owns the entry package subject",
            )
        })
        .collect::<Vec<_>>();
    let empty = PublicationLedger::new();
    let input = verification_input(
        &declarations,
        snapshot,
        &signatures,
        std::slice::from_ref(&retained),
        &empty,
        EpochObservation::at(snapshot.issue_epoch()),
        FreshnessMode::online(),
    );
    let verified = admit_snapshot(&trust, &input);
    admit(
        LockfileRecord::historical(entry, &verified, &retained, declaration, inputs),
        "the declared lockfile record is valid",
    )
}

/// Returns one lockfile.
fn lockfile_of(records: &[LockfileRecord]) -> Lockfile {
    accept(Lockfile::new(records), "the declared lockfile is valid")
}

/// Returns one package scope.
fn scope_of_package(namespace: &str, package: &str) -> AuthorityScope {
    accept(
        AuthorityScope::of_package(namespace, package),
        "the declared package scope is valid",
    )
}

/// Returns one whole-namespace scope.
fn scope_of_namespace(namespace: &str) -> AuthorityScope {
    accept(
        AuthorityScope::of_namespace(namespace),
        "the declared namespace scope is valid",
    )
}

/// Returns one source-scoped trust root.
fn root(
    id: &str,
    source: SourceIdentity,
    publisher: PublisherIdentity,
    scope: AuthorityScope,
) -> TrustRoot {
    accept(
        TrustRoot::new(id, source, publisher, scope),
        "the declared trust root is valid",
    )
}

/// Returns one trust store.
fn store_of(roots: &[TrustRoot], keys: &[KeyRecord], delegations: &[Delegation]) -> TrustStore {
    accept(
        TrustStore::new(roots, keys, delegations),
        "the declared trust store is valid",
    )
}

/// Returns authenticated delegation evidence over one source-scoped grant.
fn delegation(
    source: SourceIdentity,
    delegator: PublisherIdentity,
    delegate: PublisherIdentity,
    scope: AuthorityScope,
    effective_sequence: u64,
    key: &KeyRecord,
) -> Delegation {
    let timing = accept(
        DelegationTiming::new(0, u64::MAX, effective_sequence),
        "the declared delegation timing is valid",
    );
    let payload = Delegation::payload(
        &source,
        &delegator,
        &delegate,
        &scope,
        timing.not_before_epoch(),
        timing.expiry_epoch(),
        timing.effective_sequence(),
    );
    accept(
        Delegation::authenticated(
            source,
            delegator,
            delegate,
            scope,
            timing,
            declared_signature(key, payload),
        ),
        "the declared delegation is valid",
    )
}

/// Returns canonical dual-signed rotation evidence for one source-scoped authority.
fn rotation(
    source: SourceIdentity,
    scope: AuthorityScope,
    old: &KeyRecord,
    next: &KeyRecord,
    effective_sequence: u64,
    old_signature: DeclaredSignature,
    new_signature: DeclaredSignature,
) -> RotationEvidence {
    let timing = accept(
        RotationTiming::new(
            effective_sequence,
            effective_sequence,
            effective_sequence.saturating_add(1),
        ),
        "the declared rotation timing is valid",
    );
    let context = accept(
        RotationContext::new(
            source,
            scope,
            publisher("acme", old.key().as_str()),
            old.key().clone(),
            next.key().clone(),
            timing,
        ),
        "the declared rotation context is valid",
    );
    accept(
        RotationEvidence::authenticated(
            context,
            RotationSignatures::new(old_signature, new_signature),
        ),
        "the declared rotation evidence is valid",
    )
}

/// Returns the verified snapshot of one trust decision.
fn admit_snapshot<'a>(
    store: &'a TrustStore,
    input: &'a VerificationInput<'a>,
) -> VerifiedSnapshot<'a> {
    match store.verify(input) {
        Ok(verified) => verified,
        Err(refusal) => panic!("the declared snapshot verifies: {refusal}"),
    }
}

/// Returns the refusal that prevented one snapshot verification.
fn refuse_snapshot<'a>(store: &'a TrustStore, input: &'a VerificationInput<'a>) -> RegistryRefusal {
    match store.verify(input) {
        Ok(_) => panic!("the declared snapshot was expected to be refused"),
        Err(refusal) => refusal,
    }
}

/// `GNT-27.1-immutable-source-identity-and-source-kind-vocabulary` requires one canonical source identity per declaration, no fallback
/// between kinds, and configuration aliases that bind identity without becoming one.
#[test]
fn gnt_27_1_a_declaration_binds_one_canonical_source_identity() {
    assert!(
        REGISTRY_CLAUSES.contains(&"GNT-27.1-immutable-source-identity-and-source-kind-vocabulary")
    );

    let registry = registry_source("acme", "widget");
    assert_eq!(registry, registry_source("acme", "gadget"));
    let spelling = "a".repeat(40);
    let checkout = accept(
        SourceIdentity::vcs("acme.widget", &commit(&spelling)),
        "the declared version-control identity is valid",
    );
    assert!(
        SourceIdentity::vcs("https://example.invalid/acme/widget", &commit(&spelling)).is_err()
    );
    assert!(SourceIdentity::path("/home/neil/widget").is_err());
    assert!(SourceIdentity::vendored("../widget").is_err());
    let declarations = vec![
        source_declaration(0, "widget", "widget", registry.clone()),
        source_declaration(1, "widget_vcs", "widget_vcs", checkout.clone()),
    ];

    // An admissible path: the declared identity resolves to exactly its own declaration.
    let bound = admit(
        resolve_source(&declarations, &declarations[0], &registry),
        "the declared registry source resolves",
    );
    assert_eq!(bound.index(), 0);
    assert_eq!(bound.identity(), &registry);
    assert_eq!(bound.identity().kind(), SourceKind::Registry);
    assert_eq!(bound.identity().canonical_text(), "registry:acme-registry");
    assert_eq!(bound.identity().digest_hex().len(), 64);
    assert_eq!(bound.alias().spelling(), "widget");
    assert_eq!(
        admit(
            resolve_source(&declarations, &declarations[1], &checkout),
            "the declared version-control source resolves"
        )
        .index(),
        1
    );

    // A configuration alias binds an authenticated identity and is never itself an identity.
    let binding = accept(
        AliasBinding::new("local_widget", registry.clone()),
        "the declared alias binding is valid",
    );
    let aliases = accept(
        AliasBindings::new(std::slice::from_ref(&binding)),
        "the declared alias bindings are valid",
    );
    let alias = accept(
        ConfigurationAlias::new("local_widget"),
        "the declared alias spelling is valid",
    );
    assert_eq!(aliases.bound_identity(&alias), Some(&registry));
    assert_eq!(aliases.len(), 1);
    let refusal = refuse(
        aliases.semantic_identity(&declarations[0], &alias),
        "an alias is not a semantic identity",
    );
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::ConfigAliasNotIdentity)
    );
    assert_eq!(
        refusal.clause(),
        "GNT-27.1-immutable-source-identity-and-source-kind-vocabulary"
    );
    assert_eq!(refusal.declaration_identity(), &registry);

    // A same-named source of another kind never substitutes for the declared one.
    let same_text = accept(
        SourceIdentity::path(registry.canonical_text()),
        "the declared identity text is valid",
    );
    let refusal = refuse(
        resolve_source(&declarations, &declarations[0], &same_text),
        "resolution never falls back between kinds",
    );
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::SourceKindFallback)
    );
    assert_eq!(
        refusal.clause(),
        "GNT-27.1-immutable-source-identity-and-source-kind-vocabulary"
    );
    assert!(refusal.is_bound());
    assert_eq!(refusal.declaration_index(), 0);
    assert_eq!(refusal.declaration_identity(), &registry);

    let undeclared = registry_source("other", "widget");
    let refusal = refuse(
        resolve_source(&declarations, &declarations[0], &undeclared),
        "an undeclared source never resolves",
    );
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::SourceNotDeclared)
    );
    assert_eq!(refusal.causing_entry(), None);
}

/// `GNT-27.2-canonical-publication-names-and-external-name-mapping` requires one canonical byte representation per name, refuses
/// noncanonical publication names and canonical collisions, and maps external names to explicit
/// collision-free source aliases.
#[test]
fn gnt_27_2_canonical_names_admit_one_byte_representation() {
    let canonical = name(RegistryNameKind::Package, "widget");
    assert_eq!(canonical.spelling(), "widget");
    assert_eq!(canonical.canonical_bytes(), b"widget");
    assert_eq!(canonical.kind(), RegistryNameKind::Package);
    assert_eq!(canonical, name(RegistryNameKind::Package, "widget"));
    assert_eq!(canonical.digest_hex().len(), 64);

    // A noncanonical publication name is refused instead of normalized silently.
    let decomposed = reject(
        RegistryName::namespace("cafe\u{301}"),
        "a noncanonical name is refused",
    );
    assert_eq!(
        decomposed.code(),
        Some(RegistryDiagnosticCode::NameNoncanonical)
    );
    assert_eq!(
        decomposed.clause(),
        "GNT-27.2-canonical-publication-names-and-external-name-mapping"
    );
    let malformed = reject(
        RegistryName::package("widget/sub"),
        "a malformed name is refused",
    );
    assert_eq!(malformed.code(), None);
    assert_eq!(
        malformed.clause(),
        "GNT-27.2-canonical-publication-names-and-external-name-mapping"
    );

    // A canonical collision is refused rather than resolved by preference.
    let mut admitted = PublicationNameSet::new();
    accept(
        admitted.admit(name(RegistryNameKind::Publisher, "Acme")),
        "the declared publisher name is admitted",
    );
    assert_eq!(admitted.len(), 1);
    accept(
        admitted.admit(name(RegistryNameKind::Publisher, "Acme")),
        "the same publication name admits once",
    );
    assert!(admitted.contains(&name(RegistryNameKind::Publisher, "Acme")));
    let collision_error = reject(
        admitted.admit(name(RegistryNameKind::Publisher, "acme")),
        "a case-folded collision is refused",
    );
    assert_eq!(
        collision_error.code(),
        Some(RegistryDiagnosticCode::NameCollision)
    );
    assert!(
        collision(
            &name(RegistryNameKind::Package, "widget"),
            &name(RegistryNameKind::Namespace, "widget")
        )
        .is_none()
    );

    // Two external names sharing one alias skeleton are refused.
    let mut aliases = ExternalAliasMap::new();
    let first = accept(
        ExternalName::new(RegistryNameKind::Package, "widget"),
        "the declared external name is valid",
    );
    let second = accept(
        ExternalName::new(RegistryNameKind::Package, "WIDGET"),
        "the declared external name is valid",
    );
    let alias = accept(
        aliases.insert(first.clone()),
        "the declared external name is mapped",
    );
    assert_eq!(alias.as_str(), "ext_package_widget");
    assert_eq!(
        aliases.alias(&first).map(SourceAlias::as_str),
        Some("ext_package_widget")
    );
    let collision_error = reject(
        aliases.insert(second),
        "two external names sharing one skeleton are refused",
    );
    assert_eq!(
        collision_error.code(),
        Some(RegistryDiagnosticCode::ExternalAliasCollision)
    );
    let other = accept(
        ExternalName::new(RegistryNameKind::Package, "gadget"),
        "the declared external name is valid",
    );
    let other_alias = accept(aliases.insert(other.clone()), "a second name maps too");
    assert_ne!(other_alias.as_str(), alias.as_str());
    assert_eq!(aliases.external(&alias), Some(&first));
    assert_eq!(aliases.len(), 2);
}

/// `GNT-27.3-authenticated-metadata-snapshot-and-client-verification` requires a versioned snapshot over a monotone sequence whose
/// verification returns either a verified snapshot or a typed refusal naming the causing entry.
#[test]
fn gnt_27_3_a_snapshot_verifies_or_refuses_with_its_causing_entry() {
    let acme_key = key("acme-key");
    let acme = publisher("acme", "acme-key");
    let widget = entry("acme", "widget", "1.0.0", &acme, "manifest-a", "artifact-a");
    let gadget = entry("acme", "gadget", "1.0.0", &acme, "manifest-b", "artifact-b");
    let acme_root = root(
        "acme-root",
        widget.source().clone(),
        acme.clone(),
        scope_of_namespace("acme"),
    );
    let store = store_of(
        std::slice::from_ref(&acme_root),
        std::slice::from_ref(&acme_key),
        &[],
    );
    let snapshot = snapshot_of(4, 100, 200, &[widget.clone(), gadget.clone()]);
    assert_eq!(snapshot.version(), MetadataSnapshot::VERSION);
    assert_eq!(snapshot.sequence(), 4);
    assert_eq!(snapshot.entries().len(), 2);
    assert_eq!(snapshot.expiry_epoch(), 200);
    let declarations = vec![
        source_declaration(0, "widget", "widget", widget.source().clone()),
        source_declaration(1, "gadget", "gadget", gadget.source().clone()),
    ];
    let ledger = ledger_of(&declarations[0], &snapshot);
    let retained = [RetainedState::for_source(widget.source().clone(), 1)];
    let signatures = vec![declared_signature(&acme_key, snapshot.content_digest())];
    let input = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        &retained,
        &ledger,
        EpochObservation::at(150),
        FreshnessMode::online(),
    );

    // An admissible path: the snapshot verifies with one authority per entry.
    let verified = admit_snapshot(&store, &input);
    assert_eq!(verified.snapshot().sequence(), 4);
    assert_eq!(verified.identity(), snapshot.identity());
    assert_eq!(verified.entries().len(), 2);
    assert_eq!(verified.authorities().len(), 2);
    assert_eq!(verified.entries()[0].package().spelling(), "gadget");
    assert_eq!(
        verified.authority(0).map(EntryAuthority::declaration),
        Some(1)
    );
    assert_eq!(
        verified.authority(1).map(EntryAuthority::declaration),
        Some(0)
    );
    assert_eq!(
        verified
            .authority(0)
            .and_then(|authority| declarations
                .iter()
                .find(|declaration| declaration.index() == authority.declaration()))
            .map(|declaration| declaration.coordinate().as_str()),
        Some("manifest:dependency:1")
    );
    assert_eq!(
        verified
            .authority(1)
            .map(|authority| authority.grant().root().as_str()),
        Some("acme-root")
    );
    assert!(verified.freshness().is_online());
    assert_eq!(verified.freshness().age(), 50);

    // A declared signature that does not verify is refused.
    let forged = vec![DeclaredSignature::declared(
        acme_key.key().clone(),
        digest("forged-signature"),
    )];
    let forged_input = verification_input(
        &declarations,
        &snapshot,
        &forged,
        &retained,
        &ledger,
        EpochObservation::at(150),
        FreshnessMode::online(),
    )
    .with_snapshot_declaration(1);
    let refusal = refuse_snapshot(&store, &forged_input);
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::SignatureUnverified)
    );
    assert_eq!(
        refusal.clause(),
        "GNT-27.4-trust-roots-and-delegated-authority"
    );
    assert_eq!(refusal.declaration_index(), 1);
    assert_eq!(refusal.declaration_identity(), declarations[1].identity());

    // An entry that no declaration binds is refused before any other check reads it.
    let foreign = registry_source("other", "widget");
    let unbound = snapshot_of(
        5,
        100,
        200,
        std::slice::from_ref(&widget.clone().with_source(foreign.clone())),
    );
    let unbound_signatures = vec![declared_signature(&acme_key, unbound.content_digest())];
    let unbound_input = verification_input(
        &declarations,
        &unbound,
        &unbound_signatures,
        &retained,
        &ledger,
        EpochObservation::at(150),
        FreshnessMode::online(),
    );
    let refusal = refuse_snapshot(&store, &unbound_input);
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::AttributionMissing)
    );
    assert_eq!(refusal.clause(), "GNT-27.13-trust-failure-attribution");
    assert!(!refusal.is_bound());
    assert_eq!(refusal.causing_entry(), Some(0));
    assert_eq!(refusal.declaration_identity(), &foreign);

    // An unsupported snapshot format version is refused before a snapshot value exists.
    let mut unsupported = MetadataSnapshot::VERSION;
    unsupported.major = 9;
    let error = reject(
        MetadataSnapshot::new(
            unsupported,
            widget.source().clone(),
            4,
            100,
            200,
            std::slice::from_ref(&widget),
        ),
        "an unsupported snapshot version is refused",
    );
    assert_eq!(
        error.code(),
        Some(RegistryDiagnosticCode::SnapshotVersionUnsupported)
    );
    assert_eq!(
        error.clause(),
        "GNT-27.3-authenticated-metadata-snapshot-and-client-verification"
    );
}

/// `GNT-27.4-trust-roots-and-delegated-authority` requires explicit roots, scope narrowing only, and no
/// ambient or fallback trust.
#[test]
fn gnt_27_4_explicit_roots_and_narrowing_delegations_decide_authority() {
    let root_key = key("root-key");
    let delegate_key = key("delegate-key");
    let acme = publisher("acme", "root-key");
    let acme_tools = publisher("acme-tools", "delegate-key");
    let keys = vec![root_key, delegate_key];
    let narrow_root = root(
        "acme-root",
        registry_source("acme", "widget"),
        acme.clone(),
        scope_of_package("acme", "widget"),
    );

    // A delegation that would widen its delegator's authority is refused.
    let widening = delegation(
        registry_source("acme", "widget"),
        acme.clone(),
        acme_tools.clone(),
        scope_of_namespace("acme"),
        1,
        &keys[0],
    );
    let error = reject(
        TrustStore::new(
            std::slice::from_ref(&narrow_root),
            &keys,
            std::slice::from_ref(&widening),
        ),
        "a widening delegation is refused",
    );
    assert_eq!(
        error.code(),
        Some(RegistryDiagnosticCode::DelegationOutOfScope)
    );
    assert_eq!(
        error.clause(),
        "GNT-27.4-trust-roots-and-delegated-authority"
    );

    // An admissible path: a narrowing delegation admits the delegate inside one package.
    let narrowing = delegation(
        registry_source("acme", "widget"),
        acme.clone(),
        acme_tools.clone(),
        scope_of_package("acme", "widget"),
        1,
        &keys[0],
    );
    let store = store_of(
        std::slice::from_ref(&narrow_root),
        &keys,
        std::slice::from_ref(&narrowing),
    );
    assert_eq!(store.roots().len(), 1);
    assert_eq!(store.delegations().len(), 1);
    assert_eq!(store.delegations()[0].root().as_str(), "acme-root");
    assert_eq!(store.delegations()[0].ancestors().len(), 1);
    let inside = entry(
        "acme",
        "widget",
        "1.0.0",
        &acme_tools,
        "manifest-a",
        "artifact-a",
    );
    let inside_declaration = source_declaration(0, "widget", "widget", inside.source().clone());
    let grant = admit(
        store.authorize(&inside_declaration, &inside, 2),
        "the narrowed delegate is authorized inside its scope",
    );
    assert!(grant.is_delegated());
    assert!(!grant.is_inherited());
    assert_eq!(grant.authorized_by().as_str(), "delegate-key");
    assert_eq!(grant.root_key().as_str(), "root-key");
    assert_eq!(
        grant.scope().package().map(RegistryName::spelling),
        Some("widget")
    );
    let rooted = entry("acme", "widget", "0.9.0", &acme, "manifest-c", "artifact-c");
    let rooted_declaration =
        source_declaration(1, "widget_root", "widget_root", rooted.source().clone());
    let grant = admit(
        store.authorize(&rooted_declaration, &rooted, 2),
        "the root itself is authorized across its scope",
    );
    assert!(!grant.is_delegated());
    assert_eq!(grant.authorized_by().as_str(), "root-key");

    // An entry outside the delegated scope is refused with the authority that was found.
    let outside = entry(
        "acme",
        "gadget",
        "1.0.0",
        &acme_tools,
        "manifest-b",
        "artifact-b",
    );
    let outside_declaration = source_declaration(1, "gadget", "gadget", outside.source().clone());
    let refusal = refuse(
        store.authorize(&outside_declaration, &outside, 2),
        "an out-of-scope entry is refused",
    );
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::DelegationOutOfScope)
    );
    assert!(refusal.is_bound());
    assert_eq!(refusal.declaration_index(), 1);
    assert!(matches!(
        refusal.condition(),
        RegistryError::DelegationOutOfScope { .. }
    ));

    // No ambient trust: a publisher no root and no delegation names holds no authority.
    let stranger = entry(
        "acme",
        "widget",
        "1.0.0",
        &publisher("stranger", "stranger-key"),
        "manifest-d",
        "artifact-d",
    );
    let stranger_declaration =
        source_declaration(2, "stranger", "stranger", stranger.source().clone());
    let refusal = refuse(
        store.authorize(&stranger_declaration, &stranger, 2),
        "an unnamed publisher holds no authority",
    );
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::PublisherUnauthorized)
    );
    assert!(matches!(
        refusal.condition(),
        RegistryError::PublisherUnauthorized {
            defect: AuthorizationDefect::UnknownPublisher,
            ..
        }
    ));
    let empty_store = store_of(&[], &keys, &[]);
    let refusal = refuse(
        empty_store.authorize(&stranger_declaration, &stranger, 2),
        "an empty store authorizes nothing",
    );
    assert_eq!(refusal.code(), None);
    assert_eq!(refusal.reason(), TrustFailureReason::AbsentTrustRoot);
    assert_eq!(
        refusal.requirement_anchor(),
        "GNT-27.4-trust-roots-and-delegated-authority"
    );
}

/// `GNT-27.5-key-rotation-and-compromise-recovery` requires rotation evidence under both keys, a
/// successor that inherits the retired key's authority, and a compromise that revokes it.
#[test]
fn gnt_27_5_rotation_and_compromise_decide_the_signing_key() {
    let old = key("acme-key");
    let next = key("next-key");
    let acme = publisher("acme", "acme-key");
    let acme_root = root(
        "acme-root",
        registry_source("acme", "widget"),
        acme.clone(),
        scope_of_package("acme", "widget"),
    );
    let mut store = store_of(
        std::slice::from_ref(&acme_root),
        std::slice::from_ref(&old),
        &[],
    );
    let source = registry_source("acme", "widget");
    let scope = scope_of_package("acme", "widget");
    let timing = accept(
        RotationTiming::new(4, 4, 5),
        "the declared rotation timing is valid",
    );
    let payload = RotationEvidence::payload(&source, &scope, &acme, old.key(), next.key(), timing);

    // A rotation whose evidence is valid under one key only is refused.
    let one_sided = rotation(
        source.clone(),
        scope.clone(),
        &old,
        &next,
        4,
        declared_signature(&old, payload),
        DeclaredSignature::declared(next.key().clone(), digest("forged-rotation")),
    );
    let refusal = refuse(
        store.rotate(
            &source_declaration(0, "widget", "widget", registry_source("acme", "widget")),
            one_sided,
            std::slice::from_ref(&next),
        ),
        "rotation evidence under one key is refused",
    );
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::RotationEvidenceInvalid)
    );
    assert_eq!(
        refusal.clause(),
        "GNT-27.5-signing-key-rotation-and-compromise-recovery"
    );
    // An admissible path: evidence under both keys rotates the key.
    let evidence = rotation(
        source,
        scope,
        &old,
        &next,
        4,
        declared_signature(&old, payload),
        declared_signature(&next, payload),
    );
    let rotation_declaration =
        source_declaration(0, "widget", "widget", registry_source("acme", "widget"));
    admit(
        store.rotate(&rotation_declaration, evidence, std::slice::from_ref(&next)),
        "evidence under both keys rotates the key",
    );
    assert_eq!(store.rotations().len(), 1);
    assert_eq!(store.rotations()[0].old_key().as_str(), "acme-key");
    assert_eq!(store.rotations()[0].new_key().as_str(), "next-key");

    // Metadata signed by the successor inherits the retired key's authority.
    let upgraded = entry(
        "acme",
        "widget",
        "2.0.0",
        &publisher("acme", "next-key"),
        "manifest-b",
        "artifact-b",
    );
    let upgraded_declaration = source_declaration(0, "widget", "widget", upgraded.source().clone());
    let upgraded_grant = admit(
        store.authorize(&upgraded_declaration, &upgraded, 5),
        "the rotated key holds the retired key's authority",
    );
    assert!(upgraded_grant.is_inherited());
    assert_eq!(
        upgraded_grant.inherited_from().map(KeyId::as_str),
        Some("acme-key")
    );
    assert_eq!(upgraded_grant.authorized_by().as_str(), "next-key");
    assert_eq!(upgraded_grant.root().as_str(), "acme-root");
    assert!(!upgraded_grant.is_delegated());

    // Metadata signed only by the retired key after the rotation is refused.
    let retired = entry("acme", "widget", "1.0.0", &acme, "manifest-a", "artifact-a");
    let retired_declaration = source_declaration(
        1,
        "widget_retired",
        "widget_retired",
        retired.source().clone(),
    );
    let refusal = refuse(
        store.authorize(&retired_declaration, &retired, 5),
        "a superseded key signs nothing after its rotation",
    );
    assert_eq!(refusal.code(), Some(RegistryDiagnosticCode::KeySuperseded));
    assert_eq!(
        refusal.clause(),
        "GNT-27.5-signing-key-rotation-and-compromise-recovery"
    );
    assert_eq!(refusal.declaration_index(), 1);
    admit(
        store.authorize(&retired_declaration, &retired, 3),
        "metadata that precedes the rotation stays authorized",
    );

    // A source-scoped compromise is authorized by the successor after the retiring key's
    // overlap closes, then revokes the retired key and its inherited authority.
    let compromise_scope = scope_of_package("acme", "widget");
    let recovered = publisher("acme", "next-key");
    let compromise_payload = Compromise::payload(
        retired.source(),
        &compromise_scope,
        &recovered,
        old.key(),
        6,
        6,
    );
    let compromise = accept(
        Compromise::authenticated(
            retired.source().clone(),
            compromise_scope,
            recovered,
            old.key().clone(),
            6,
            6,
            declared_signature(&next, compromise_payload),
        ),
        "the declared compromise evidence is valid",
    );
    admit(
        store.compromise(&retired_declaration, compromise),
        "the signed source-scoped compromise is admitted",
    );
    let refusal = refuse(
        store.authorize(&retired_declaration, &retired, 6),
        "a compromised key holds no authority",
    );
    assert_eq!(refusal.code(), Some(RegistryDiagnosticCode::KeyCompromised));
    let refusal = refuse(
        store.authorize(&upgraded_declaration, &upgraded, 6),
        "a successor descended from a compromised key is refused",
    );
    assert_eq!(refusal.code(), Some(RegistryDiagnosticCode::KeyCompromised));
    assert_eq!(refusal.declaration_index(), upgraded_declaration.index());
    assert_eq!(
        refusal.requirement_anchor(),
        "GNT-27.5-signing-key-rotation-and-compromise-recovery"
    );
    assert_eq!(
        refusal
            .attribution()
            .coordinate()
            .map(|coordinate| coordinate.as_str()),
        Some("manifest:dependency:0")
    );
}

/// `GNT-27.6-expiry-freshness-and-offline-mode` requires expired metadata to fail closed and an explicit
/// offline pinned path that reports its age and is distinguished from an online check.
#[test]
fn gnt_27_6_expiry_fails_closed_and_a_pinned_path_reports_its_age() {
    let acme_key = key("acme-key");
    let acme = publisher("acme", "acme-key");
    let acme_root = root(
        "acme-root",
        registry_source("acme", "widget"),
        acme.clone(),
        scope_of_package("acme", "widget"),
    );
    let store = store_of(
        std::slice::from_ref(&acme_root),
        std::slice::from_ref(&acme_key),
        &[],
    );
    let widget = entry("acme", "widget", "1.0.0", &acme, "manifest-a", "artifact-a");
    let snapshot = snapshot_of(4, 100, 200, std::slice::from_ref(&widget));
    let declaration = source_declaration(0, "widget", "widget", widget.source().clone());
    let declarations = vec![declaration.clone()];
    let ledger = ledger_of(&declaration, &snapshot);
    let retained = RetainedState::for_source(widget.source().clone(), 1);
    let signatures = vec![declared_signature(&acme_key, snapshot.content_digest())];
    assert_eq!(snapshot.issue_epoch(), 100);

    // An admissible path: an online observation inside the declared window verifies.
    let online = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        std::slice::from_ref(&retained),
        &ledger,
        EpochObservation::at(150),
        FreshnessMode::online(),
    );
    let verified = admit_snapshot(&store, &online);
    assert!(verified.freshness().is_online());
    assert_eq!(verified.freshness().age(), 50);
    assert_eq!(verified.freshness().observed_epoch(), 150);
    assert!(!verified.freshness().snapshot_expired());
    assert_eq!(verified.freshness().mode(), FreshnessMode::Online);
    let offline_witness = accept(
        verified.offline_witness(declaration.identity(), 199),
        "the verified snapshot mints an offline witness",
    );
    assert!(
        verified
            .offline_witness(declaration.identity(), 200)
            .is_ok()
    );

    // An observation past the declared expiry fails closed.
    let expired = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        std::slice::from_ref(&retained),
        &ledger,
        EpochObservation::at(200),
        FreshnessMode::online(),
    )
    .with_snapshot_declaration(declaration.index());
    let refusal = refuse_snapshot(&store, &expired);
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::SnapshotExpired)
    );
    assert_eq!(
        refusal.clause(),
        "GNT-27.6-expiry-freshness-and-offline-mode"
    );
    assert!(refusal.is_bound());
    assert_eq!(refusal.causing_entry(), None);
    let early = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        std::slice::from_ref(&retained),
        &ledger,
        EpochObservation::at(99),
        FreshnessMode::online(),
    )
    .with_snapshot_declaration(declaration.index());
    assert_eq!(
        refuse_snapshot(&store, &early).code(),
        Some(RegistryDiagnosticCode::SnapshotEpochInconsistent)
    );

    // An explicit offline witness admits only the same snapshot during its own validity window.
    let offline = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        std::slice::from_ref(&retained),
        &ledger,
        EpochObservation::at(199),
        FreshnessMode::offline(offline_witness.clone()),
    );
    let verified = admit_snapshot(&store, &offline);
    assert!(!verified.freshness().is_online());
    assert!(!verified.freshness().snapshot_expired());
    assert_eq!(verified.freshness().age(), 99);
    assert_eq!(verified.freshness().expiry_epoch(), 200);
    assert_ne!(verified.freshness().mode(), FreshnessMode::Online);

    // A witness cannot extend the snapshot's declared expiry.
    let beyond = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        std::slice::from_ref(&retained),
        &ledger,
        EpochObservation::at(200),
        FreshnessMode::offline(offline_witness),
    )
    .with_snapshot_declaration(declaration.index());
    assert_eq!(
        refuse_snapshot(&store, &beyond).code(),
        Some(RegistryDiagnosticCode::SnapshotExpired)
    );
    let unresolvable = reject(
        verified.offline_witness(declaration.identity(), 99),
        "a witness whose bound precedes snapshot issuance is refused",
    );
    assert_eq!(
        unresolvable.code(),
        Some(RegistryDiagnosticCode::SnapshotEpochInconsistent)
    );
}

/// `GNT-27.7-rollback-and-freeze-resistance` requires a retained minimum trusted sequence and
/// monotone evidence, and refuses a rollback and an unchanged sequence with changed content.
#[test]
fn gnt_27_7_a_rollback_or_a_freeze_is_refused_against_retained_state() {
    let acme_key = key("acme-key");
    let acme = publisher("acme", "acme-key");
    let acme_root = root(
        "acme-root",
        registry_source("acme", "widget"),
        acme.clone(),
        scope_of_package("acme", "widget"),
    );
    let store = store_of(
        std::slice::from_ref(&acme_root),
        std::slice::from_ref(&acme_key),
        &[],
    );
    let widget = entry("acme", "widget", "1.0.0", &acme, "manifest-a", "artifact-a");
    let snapshot = snapshot_of(4, 100, 200, std::slice::from_ref(&widget));
    let declaration = source_declaration(0, "widget", "widget", widget.source().clone());
    let declarations = vec![declaration.clone()];
    let ledger = ledger_of(&declaration, &snapshot);
    let signatures = vec![declared_signature(&acme_key, snapshot.content_digest())];

    // An admissible path: the retained sequence itself carries the same content.
    let monotone = RetainedState::for_source(widget.source().clone(), 4)
        .with_content(4, snapshot.content_digest());
    let accepted = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        std::slice::from_ref(&monotone),
        &ledger,
        EpochObservation::at(150),
        FreshnessMode::online(),
    );
    let verified = admit_snapshot(&store, &accepted);
    assert_eq!(verified.identity(), snapshot.identity());
    assert_eq!(monotone.minimum_sequence(), 4);
    assert_eq!(monotone.sequences().count(), 1);
    assert_eq!(
        monotone.retained_content(4),
        Some(snapshot.content_digest())
    );

    let duplicate = RetainedState::for_source(widget.source().clone(), 4)
        .with_content(4, snapshot.content_digest());
    for retained_states in [
        &[monotone.clone(), duplicate.clone()][..],
        &[duplicate, monotone][..],
    ] {
        let refusal = refuse_snapshot(
            &store,
            &verification_input(
                &declarations,
                &snapshot,
                &signatures,
                retained_states,
                &ledger,
                EpochObservation::at(150),
                FreshnessMode::online(),
            ),
        );
        assert!(matches!(
            refusal.condition(),
            RegistryError::RetainedStateAmbiguous { supplied: 2, .. }
        ));
        assert_eq!(refusal.reason(), TrustFailureReason::RetainedStateAmbiguous);
        assert_eq!(refusal.requirement_anchor(), refusal.reason().anchor());
    }

    // A snapshot older than the retained minimum is a rollback.
    let advanced = RetainedState::for_source(widget.source().clone(), 5);
    let rollback = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        std::slice::from_ref(&advanced),
        &ledger,
        EpochObservation::at(150),
        FreshnessMode::online(),
    );
    let refusal = refuse_snapshot(&store, &rollback);
    assert_eq!(refusal.code(), Some(RegistryDiagnosticCode::Rollback));
    assert_eq!(refusal.clause(), "GNT-27.7-rollback-and-freeze-resistance");
    assert!(refusal.is_bound());
    assert_eq!(refusal.declaration_index(), 0);
    assert!(matches!(
        refusal.condition(),
        RegistryError::Rollback {
            declared: 4,
            retained_minimum: 5,
        }
    ));

    // One retained sequence that now carries another content is a freeze or equivocation.
    let equivocated = RetainedState::for_source(widget.source().clone(), 1)
        .with_content(4, digest("other-content"));
    let frozen = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        std::slice::from_ref(&equivocated),
        &ledger,
        EpochObservation::at(150),
        FreshnessMode::online(),
    );
    let refusal = refuse_snapshot(&store, &frozen);
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::FreezeEquivocation)
    );
    assert_eq!(refusal.clause(), "GNT-27.7-rollback-and-freeze-resistance");
    assert!(matches!(
        refusal.condition(),
        RegistryError::FreezeEquivocation { sequence: 4, .. }
    ));
    // A declared source staleness bound detects a freeze even when the sequence is unchanged.
    let stale_source = RetainedState::for_source(widget.source().clone(), 4)
        .with_content(4, snapshot.content_digest())
        .with_maximum_staleness(25)
        .with_expiry_epoch(100);
    let frozen = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        std::slice::from_ref(&stale_source),
        &ledger,
        EpochObservation::at(150),
        FreshnessMode::online(),
    );
    let refusal = refuse_snapshot(&store, &frozen);
    assert_eq!(refusal.code(), Some(RegistryDiagnosticCode::FreezeDetected));
    assert!(matches!(
        refusal.condition(),
        RegistryError::FreezeDetected {
            sequence: 4,
            maximum_staleness: 25,
            observed_epoch: 150,
        }
    ));
    let mut progressing = RetainedState::for_source(widget.source().clone(), 4)
        .with_content(4, snapshot.content_digest());
    progressing.advance(9, digest("later-content"));
    assert_eq!(progressing.minimum_sequence(), 9);
    assert_eq!(progressing.sequences().count(), 2);
}

/// `GNT-27.8-publication-immutability` requires one authenticated tuple to name one set of
/// manifest, source, and artifact bytes forever.
#[test]
fn gnt_27_8_a_publication_tuple_never_names_two_byte_sets() {
    let acme_key = key("acme-key");
    let acme = publisher("acme", "acme-key");
    let acme_root = root(
        "acme-root",
        registry_source("acme", "widget"),
        acme.clone(),
        scope_of_package("acme", "widget"),
    );
    let store = store_of(
        std::slice::from_ref(&acme_root),
        std::slice::from_ref(&acme_key),
        &[],
    );
    let published = entry("acme", "widget", "1.0.0", &acme, "manifest-a", "artifact-a");
    let _replay = entry("acme", "widget", "1.0.0", &acme, "manifest-a", "artifact-a");
    let declaration = source_declaration(0, "widget", "widget", published.source().clone());

    // An authenticated snapshot, not a raw publication record, occupies the ledger.
    let published_snapshot = snapshot_of(3, 100, 200, std::slice::from_ref(&published));
    let mut ledger = ledger_of(&declaration, &published_snapshot);
    assert_eq!(ledger.len(), 1);
    let (replay_trust, replay_retained, replay_signatures) =
        authenticated_fixture(&declaration, &published_snapshot);
    let replay_declarations = [declaration.clone()];
    let replay_empty = PublicationLedger::new();
    let replay_input = verification_input(
        &replay_declarations,
        &published_snapshot,
        &replay_signatures,
        std::slice::from_ref(&replay_retained),
        &replay_empty,
        EpochObservation::at(100),
        FreshnessMode::online(),
    );
    let replay_verified = admit_snapshot(&replay_trust, &replay_input);
    admit(
        ledger.admit_verified(&replay_verified, &replay_declarations),
        "an identical verified snapshot retains no second publication",
    );
    assert_eq!(ledger.len(), 1);

    // A differing publication of the same tuple is refused before it can occupy the ledger.
    let changed = entry("acme", "widget", "1.0.0", &acme, "manifest-a", "artifact-z")
        .with_generated(digest("generated:artifact-a"));
    let snapshot = snapshot_of(4, 100, 200, std::slice::from_ref(&changed));
    let declarations = vec![declaration.clone()];
    let signatures = vec![declared_signature(&acme_key, snapshot.content_digest())];
    let retained = RetainedState::for_source(changed.source().clone(), 1);
    let input = verification_input(
        &declarations,
        &snapshot,
        &signatures,
        std::slice::from_ref(&retained),
        &ledger,
        EpochObservation::at(150),
        FreshnessMode::online(),
    );
    let refusal = refuse_snapshot(&store, &input);
    assert_eq!(
        refusal.code(),
        Some(RegistryDiagnosticCode::PublicationImmutable)
    );
    assert!(refusal.is_bound());
    assert_eq!(refusal.causing_entry(), Some(0));
    assert!(matches!(
        refusal.condition(),
        RegistryError::PublicationImmutable {
            defect: PublicationDefect::ChangedArtifact,
            recorded,
            observed,
            ..
        } if *recorded == digest("artifact-a") && *observed == digest("artifact-z")
    ));

    // A correction requires a new version and a separately verified snapshot admission.
    let corrected = entry("acme", "widget", "2.0.0", &acme, "manifest-b", "artifact-b");
    let corrected_snapshot = snapshot_of(5, 100, 200, std::slice::from_ref(&corrected));
    let corrected_signatures = vec![declared_signature(
        &acme_key,
        corrected_snapshot.content_digest(),
    )];
    let verification_ledger = ledger.clone();
    let corrected_input = verification_input(
        &declarations,
        &corrected_snapshot,
        &corrected_signatures,
        std::slice::from_ref(&retained),
        &verification_ledger,
        EpochObservation::at(150),
        FreshnessMode::online(),
    );
    let corrected_verified = admit_snapshot(&store, &corrected_input);
    admit(
        ledger.admit_verified(&corrected_verified, &declarations),
        "a correction under a new version is recorded after verification",
    );
    assert_eq!(ledger.len(), 2);
}

/// `GNT-27.9-yank-semantics` requires a yank to remove a release from ordinary new resolution
/// without ever rewriting a lockfile.
#[test]
fn gnt_27_9_a_yank_stops_new_resolution_without_rewriting_a_lockfile() {
    let acme_key = key("acme-key");
