    );
    admit(
        store.rotate(
            &declaration,
            rotation(
                source.clone(),
                scope.clone(),
                &old,
                &next,
                4,
                declared_signature(&old, payload),
                declared_signature(&next, payload),
            ),
            std::slice::from_ref(&next),
        ),
        "the rotation retires the old key after its overlap",
    );

    let delegation_timing = accept(
        DelegationTiming::new(5, u64::MAX, 5),
