    let gadget_declaration = source_declaration(1, "gadget", "gadget", source.clone());
    let declarations = [widget_declaration.clone(), gadget_declaration.clone()];
    let reviewer_delegation = delegation(
        source.clone(),
        acme.clone(),
        reviewer.clone(),
        scope_of_package("acme", "widget"),
