fn supervisor(executor: Arc<DeterministicConcurrentExecutor>) -> TaskSupervisor {
    let executor: Arc<dyn ExecutorAdapter> = executor;
    let capacities = AsyncCapacityLimits::new(1, 1, 1, 1, 1, 1, 1, 1, 1)
        .unwrap_or_else(|error| panic!("capacity fixture failed: {error}"));
    TaskSupervisor::new(executor, AsyncAdmission::new(capacities))
}

fn session_fixture(
    execution_byte: u8,
    session_byte: u8,
) -> (ProtocolIdentity, gantry::runtime::LogicalSessionV1) {
    let execution = fresh(IdentityKind::Execution, execution_byte);
    let session_id = fresh(IdentityKind::Session, session_byte);
    let registry = LogicalSessionRegistryV1::new(
        execution,
        session_id,
        SessionCreationModeV1::GantryRoot,
        CanonicalTranscriptV1::empty(),
    )
    .unwrap_or_else(|error| panic!("session fixture failed: {error:?}"));
    let session = registry
        .get(session_id)
        .cloned()
        .unwrap_or_else(|| unreachable!("root session exists"));
    (execution, session)
}

fn established_response() -> Result<HostResponse, HostError> {
    HostResponse::new(
        EmbeddingVersion::V1,
        EmbeddingOperation::EstablishSession,
        Arc::from(&b"{\"result\":\"established\"}"[..]),
    )
    .map_err(|_| host_error("response-invariant"))
}

fn host_error(code: &str) -> HostError {
    HostError {
        code: Arc::from(code),
        protected_diagnostic: None,
    }
}

fn fresh(kind: IdentityKind, byte: u8) -> ProtocolIdentity {
    ProtocolIdentity::from_fresh_material(kind, [byte; 32])
        .unwrap_or_else(|error| panic!("identity fixture failed: {error}"))
}

fn poll_once<F: Future>(future: Pin<&mut F>, waker: &Waker) -> Poll<F::Output> {
    future.poll(&mut Context::from_waker(waker))
}

fn block_on<F: Future>(future: F) -> F::Output {
    let mut future = Box::pin(future);
    loop {
        match poll_once(future.as_mut(), Waker::noop()) {
            Poll::Ready(output) => return output,
            Poll::Pending => std::thread::yield_now(),
        }
    }
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    let bytes =
        fs::read(path).unwrap_or_else(|error| panic!("could not read {}: {error}", path.display()));
    serde_json::from_slice(&bytes)
        .unwrap_or_else(|error| panic!("could not decode {}: {error}", path.display()))
}

//! Section 35 scalar and binary foundation evidence.

use std::cmp::Ordering;

use gantry::ir::{
    ByteBufferValue, ByteValue, BytesValue, CharValue, IntegerValue, OverflowMode, SCALAR_CLAUSES,
    ScalarDiagnosticCode, ScalarKind, ScalarNonClaimAssertion, ScalarNonClaimName, ScalarQuota,
    ScalarWidth, StorageStrategy, check_scalar_non_claims,
};

/// Returns the refusal produced by one rejected scalar decision.
trait Refused<E> {
    fn refused(self, context: &str) -> E;
}

impl<T, E> Refused<E> for Result<T, E> {
    fn refused(self, context: &str) -> E {
        match self {
            Ok(_) => panic!("{context}: the decision must be refused"),
            Err(error) => error,
        }
    }
}

const I8: ScalarKind = ScalarKind::Signed(ScalarWidth::W8);
const U8: ScalarKind = ScalarKind::Unsigned(ScalarWidth::W8);
const U64: ScalarKind = ScalarKind::Unsigned(ScalarWidth::W64);

fn value(kind: ScalarKind, text: &str) -> IntegerValue {
    IntegerValue::parse(kind, text).unwrap_or_else(|error| panic!("canonical literal: {error}"))
}

#[test]
