fn root_machine(
    program: Arc<MachineProgram>,
    machine_limits: MachineLimits,
    budget: ExecutionBudget,
) -> Machine {
    Machine::new_with_budget(
        program,
        &path("crate::main"),
        Vec::new(),
        execution(),
        machine_limits,
        budget,
    )
    .unwrap_or_else(|error| panic!("root machine failed: {error:?}"))
}

fn child_machine(
    program: Arc<MachineProgram>,
    task_id: ProtocolIdentity,
    task_path: Arc<[Arc<str>]>,
    machine_limits: MachineLimits,
    budget: ExecutionBudget,
    session: Option<ProtocolIdentity>,
) -> Machine {
    Machine::new_concurrent_task_with_budget_and_context(
        program,
        &path("crate::main"),
        Vec::new(),
        execution(),
        task_id,
        task_path,
        machine_limits,
        budget,
        None,
        session,
    )
    .unwrap_or_else(|error| panic!("child machine failed: {error:?}"))
}

fn standalone_child_coordinate() -> (ProtocolIdentity, Arc<[Arc<str>]>) {
    let execution = execution();
    let task_path = Arc::from([Arc::from("spawn:crate::main:0:0")]);
    let key = format!("{{\"execution\":\"{execution}\",\"path\":[\"spawn:crate::main:0:0\"]}}");
    let task_id = ProtocolIdentity::derive(IdentityKind::Task, key.as_bytes())
        .unwrap_or_else(|error| panic!("child task identity failed: {error}"));
    (task_id, task_path)
}

fn single_instruction_program(kind: InstructionKind) -> Arc<MachineProgram> {
    program(vec![instruction(0, kind)])
}

fn return_program() -> Arc<MachineProgram> {
    program(vec![
        instruction(0, InstructionKind::Push(LogicalValue::unit())),
        instruction(1, InstructionKind::Return),
    ])
}

fn program(instructions: Vec<Instruction>) -> Arc<MachineProgram> {
    Arc::new(
        MachineProgram::new(vec![Workflow {
            path: path("crate::main"),
            parameters: Vec::<Parameter>::new(),
            result: TypeDescriptor::UNIT,
            effects: EffectSet::default(),
            instructions,
        }])
        .unwrap_or_else(|error| panic!("program failed: {error:?}")),
    )
}

fn instruction(index: u64, kind: InstructionKind) -> Instruction {
    Instruction {
        site: StructuralPosition::new(vec![index])
            .unwrap_or_else(|error| panic!("site failed: {error}")),
        ty: TypeDescriptor::UNIT,
        kind,
    }
}

fn limits(
    transitions: u64,
    operations: u64,
    loops: u64,
    depth: u64,
    quantum: u64,
) -> MachineLimits {
    MachineLimits::new(
        transitions,
        operations,
        loops,
        depth,
        quantum,
        DEFAULT_VALUE_LIMITS,
    )
    .unwrap_or_else(|| panic!("positive machine limits failed"))
}

fn sessions() -> LogicalSessionRegistryV1 {
    LogicalSessionRegistryV1::new(
        execution(),
        root_session(),
        SessionCreationModeV1::GantryRoot,
        CanonicalTranscriptV1::empty(),
    )
    .unwrap_or_else(|error| panic!("session registry failed: {error:?}"))
}

fn child_request() -> TaskCreationRequestV1 {
    TaskCreationRequestV1 {
        parent_task_id: root_task(),
        handle_name: Arc::from("child"),
        workflow: path("crate::main"),
        spawn_site: StructuralPosition::new(vec![0])
            .unwrap_or_else(|error| panic!("spawn site failed: {error}")),
        spawn_occurrence: 0,
        result_type: TypeDescriptor::UNIT,
        captures: Vec::new(),
        inherited_agent: None,
        parent_session_id: root_session(),
    }
}

fn drive(machine: &mut Machine) -> MachineOutcome {
    for _ in 0..16 {
        match machine.step() {
            MachineStep::Transition(_) => {}
            MachineStep::YieldRequired => assert!(machine.resume_after_yield()),
            MachineStep::Complete(outcome) => return outcome,
            other => panic!("machine remained blocked: {other:?}"),
        }
    }
    panic!("machine did not terminate within the fixture bound")
}

fn execution() -> ProtocolIdentity {
    fresh(IdentityKind::Execution, 1)
}

fn root_task() -> ProtocolIdentity {
    ProtocolIdentity::derive(IdentityKind::Task, b"shared-budget-root")
        .unwrap_or_else(|error| panic!("root task identity failed: {error}"))
}

fn root_session() -> ProtocolIdentity {
    fresh(IdentityKind::Session, 2)
}

fn fresh(kind: IdentityKind, byte: u8) -> ProtocolIdentity {
    ProtocolIdentity::from_fresh_material(kind, [byte; 32])
        .unwrap_or_else(|error| panic!("identity failed: {error}"))
}

fn path(value: &str) -> CanonicalPath {
    CanonicalPath::new(value).unwrap_or_else(|error| panic!("path failed: {error}"))
}

fn journal_id() -> JournalId {
    JournalId::new("shared-execution-budget")
        .unwrap_or_else(|error| panic!("journal id failed: {error:?}"))
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| unreachable!("conformance crate has a workspace root"))
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    let bytes =
        fs::read(path).unwrap_or_else(|error| panic!("could not read {}: {error}", path.display()));
    serde_json::from_slice(&bytes)
        .unwrap_or_else(|error| panic!("could not decode {}: {error}", path.display()))
}

//! Machine-checked conformance for the pure Section 31 source metadata model.
//!
//! These tests validate declarations only; they do not parse, render, execute,
//! generate code, run lints, or invoke editor services.

use std::fs;
use std::path::{Path, PathBuf};

use gantry::ir::{
    DependencyWarningPolicy, Deprecation, DocumentationComment, DocumentationFormat,
    DocumentationLink, ExampleDeclaration, ExampleMode, GeneratedOrigin, LintDeclaration, LintId,
    LintScope, LintSeverity, MetadataDeclarations, MetadataDiagnosticCode, MetadataError,
    MetadataSubject, SOURCE_METADATA_CLAUSES, SemanticAttribute, SemanticMode, ToolMetadata,
    admit_lint_control,
};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .unwrap_or_else(|| panic!("workspace root"))
        .to_path_buf()
}

fn subject(value: &str) -> MetadataSubject {
    MetadataSubject::new(value).unwrap_or_else(|error| panic!("subject {value:?}: {error:?}"))
}

#[test]
fn anchors_vocabulary_and_non_claims_are_published() {
    let spec = fs::read_to_string(root().join("SPEC.md"))
        .unwrap_or_else(|error| panic!("SPEC.md: {error}"));
    assert_eq!(SOURCE_METADATA_CLAUSES.len(), 13);
    for clause in SOURCE_METADATA_CLAUSES {
        assert!(spec.contains(&format!("<a id=\"{clause}\"></a>")));
    }
    assert_eq!(
        DocumentationFormat::ALL.map(DocumentationFormat::wire_name),
        ["markdown", "plain-text"]
    );
    assert_eq!(
        ExampleMode::ALL.map(ExampleMode::wire_name),
        ["compile", "compile-fail", "display-only"]
    );
    assert_eq!(
        SemanticAttribute::ALL.map(SemanticAttribute::wire_name),
        ["entry", "export", "test"]
    );
    assert_eq!(MetadataDiagnosticCode::ALL.len(), 11);
    let non_claims = spec
        .split("<a id=\"GNT-31.12-source-metadata-non-claims\"></a>")
        .nth(1)
        .unwrap_or_else(|| panic!("non-claims"));
    for phrase in [
        "Markdown rendering",
        "example parsing or execution",
        "compile-time plugins",
        "runtime behavior",
    ] {
        assert!(non_claims.contains(phrase));
    }
}

#[test]
fn documentation_attachment_links_and_examples_are_bounded_and_explicit() {
    let link = DocumentationLink::new("std.core::Option")
        .unwrap_or_else(|error| panic!("link: {error:?}"));
    assert_eq!(
        DocumentationLink::new("Option"),
        Err(MetadataError::InvalidLink)
    );
    let comment = DocumentationComment::new(
        subject("std.core::Result"),
        DocumentationFormat::Markdown,
        "A result.",
        vec![link],
    )
    .unwrap_or_else(|error| panic!("comment: {error:?}"));
    let mut declarations = MetadataDeclarations::default();
    assert!(declarations.attach(comment.clone()).is_ok());
    assert_eq!(
        declarations.attach(comment),
        Err(MetadataError::InvalidDocumentationAttachment)
    );
    assert_eq!(
        DocumentationComment::new(subject("x"), DocumentationFormat::PlainText, "", vec![]),
        Err(MetadataError::InvalidDocumentationAttachment)
    );
    assert!(
        ExampleDeclaration::new(
            ExampleMode::Compile,
            Some(SemanticMode::Portable),
            "fn main() {} "
        )
        .is_ok()
    );
    assert!(
        ExampleDeclaration::new(
            ExampleMode::CompileFail,
            Some(SemanticMode::Durable),
            "not source"
        )
        .is_ok()
    );
    assert!(ExampleDeclaration::new(ExampleMode::DisplayOnly, None, "text").is_ok());
    assert_eq!(
        ExampleDeclaration::new(ExampleMode::Compile, None, ""),
        Err(MetadataError::ExampleLimitExceeded)
    );
    assert_eq!(
        ExampleDeclaration::new(
            ExampleMode::DisplayOnly,
            Some(SemanticMode::Application),
            "text"
        ),
        Err(MetadataError::ExampleLimitExceeded)
    );
}

#[test]
fn deprecations_tool_metadata_lints_policies_and_origins_preserve_identity() {
    let old = subject("pkg::old");
    let new = subject("pkg::new");
    let deprecation = Deprecation::new(old.clone(), new.clone(), "use new")
        .unwrap_or_else(|error| panic!("deprecation: {error:?}"));
    assert_eq!(
        Deprecation::new(old.clone(), old.clone(), "self"),
        Err(MetadataError::InvalidDeprecation)
    );
    let tool = ToolMetadata::new("docs", "category", "public")
        .unwrap_or_else(|error| panic!("tool metadata: {error:?}"));
    let mut declarations = MetadataDeclarations::default();
    assert!(declarations.insert_deprecation(&deprecation).is_ok());
    assert_eq!(
        declarations.insert_deprecation(&deprecation),
        Err(MetadataError::InvalidDeprecation)
    );
    assert!(
        declarations
            .insert_tool_metadata(old.clone(), tool.clone())
            .is_ok()
    );
    assert_eq!(
        declarations.insert_tool_metadata(old.clone(), tool),
        Err(MetadataError::InvalidToolMetadata)
    );
    assert_eq!(
        ToolMetadata::new("non ascii Ω", "key", "value"),
        Err(MetadataError::InvalidToolMetadata)
    );
    let lint = LintDeclaration::new(
        old.clone(),
        LintId::new("metadata::missing-doc").unwrap_or_else(|_| panic!()),
        LintSeverity::Warn,
        true,
    );
    assert!(declarations.insert_lint(&lint).is_ok());
    assert_eq!(
        declarations.insert_lint(&lint),
        Err(MetadataError::DuplicateLint)
    );
    assert_eq!(
        admit_lint_control(&lint, LintScope::Item, LintSeverity::Deny),
        Ok((LintScope::Item, LintSeverity::Deny))
    );
    let security = LintDeclaration::new(
        subject("security"),
        LintId::new("security::authority").unwrap_or_else(|_| panic!()),
        LintSeverity::Deny,
        false,
    );
    assert_eq!(
        admit_lint_control(&security, LintScope::Package, LintSeverity::Allow),
        Err(MetadataError::UnsuppressibleLint)
    );
    assert!(
        declarations
            .set_dependency_policy(subject("dep"), DependencyWarningPolicy::Ignore)
            .is_ok()
    );
    assert_eq!(
        declarations.set_dependency_policy(subject("dep"), DependencyWarningPolicy::Warn),
        Err(MetadataError::InvalidDependencyWarningPolicy)
    );
    let origin = GeneratedOrigin::new(subject("generated::item"), new.clone(), "schema-v1")
        .unwrap_or_else(|error| panic!("origin: {error:?}"));
    assert!(declarations.insert_origin(&origin).is_ok());
    assert_eq!(
        declarations.insert_origin(&origin),
        Err(MetadataError::InvalidGeneratedOrigin)
    );
    assert_eq!(
        GeneratedOrigin::new(new.clone(), new, "generator"),
        Err(MetadataError::InvalidGeneratedOrigin)
    );
}

