struct FailAbortExecutor {
    inner: Arc<DeterministicConcurrentExecutor>,
    failed_submission: u64,
    pending_completion: bool,
    submissions: AtomicU64,
}

impl FailAbortExecutor {
    fn new(inner: Arc<DeterministicConcurrentExecutor>, failed_submission: u64) -> Self {
        Self {
            inner,
            failed_submission,
            pending_completion: false,
            submissions: AtomicU64::new(0),
        }
    }

    fn with_pending_completion(
        inner: Arc<DeterministicConcurrentExecutor>,
        failed_submission: u64,
    ) -> Self {
        Self {
            inner,
            failed_submission,
            pending_completion: true,
            submissions: AtomicU64::new(0),
        }
    }
}

impl ExecutorAdapter for FailAbortExecutor {
    fn spawn(&self, task: OwnedTaskFuture) -> Result<Box<dyn SubmittedTask>, HostError> {
        let submission = self.submissions.fetch_add(1, Ordering::AcqRel);
        let task = self.inner.spawn(task)?;
        if submission == self.failed_submission {
            Ok(Box::new(FailAbortTask {
                inner: task,
                pending_completion: self.pending_completion,
            }))
        } else {
            Ok(task)
        }
    }

    fn sleep<'a>(&'a self, duration: DurationMicros) -> HostFuture<'a, Result<(), HostError>> {
        self.inner.sleep(duration)
    }

    fn yield_now<'a>(&'a self) -> HostFuture<'a, Result<(), HostError>> {
        self.inner.yield_now()
    }

    fn sample_inclusive(&self, range: InclusiveJitterRange) -> Result<u64, HostError> {
        self.inner.sample_inclusive(range)
    }
}

struct FailAbortTask {
    inner: Box<dyn SubmittedTask>,
    pending_completion: bool,
}

impl SubmittedTask for FailAbortTask {
    fn completion<'a>(&'a self) -> HostFuture<'a, OwnedTaskCompletion> {
        if self.pending_completion {
            Box::pin(std::future::pending())
        } else {
            self.inner.completion()
        }
    }

    fn abort<'a>(&'a self) -> HostFuture<'a, OwnedTaskAbort> {
        Box::pin(std::future::ready(OwnedTaskAbort::Failed(HostError {
            code: Arc::from("injected-abort-failure"),
            protected_diagnostic: None,
        })))
    }
}

#[derive(Clone)]
struct RecordedEvent {
    event: EventEnvelope,
    executor_task_ids: Vec<u64>,
}

struct RecordingSink {
    executor: Arc<DeterministicConcurrentExecutor>,
    spawn_outcome: DeliveryOutcome,
    events: Mutex<Vec<RecordedEvent>>,
    delivery_observer: Mutex<Option<EventDeliveryObserver>>,
    task_completion_gate: Mutex<Option<Arc<TaskCompletionDeliveryGate>>>,
}

impl RecordingSink {
    fn new(executor: Arc<DeterministicConcurrentExecutor>, spawn_outcome: DeliveryOutcome) -> Self {
        Self {
            executor,
            spawn_outcome,
            events: Mutex::new(Vec::new()),
            delivery_observer: Mutex::new(None),
            task_completion_gate: Mutex::new(None),
        }
    }

    fn events(&self) -> Vec<RecordedEvent> {
        lock(&self.events).clone()
    }

    fn observe_delivery(&self, observer: EventDeliveryObserver) {
        *lock(&self.delivery_observer) = Some(observer);
    }

    fn gate_task_completion(&self, gate: Arc<TaskCompletionDeliveryGate>) {
        *lock(&self.task_completion_gate) = Some(gate);
    }
}

impl EventSink for RecordingSink {
    fn deliver<'a>(
        &'a self,
        request: EventDeliveryRequest,
    ) -> HostFuture<'a, Result<DeliveryOutcome, HostError>> {
        Box::pin(async move {
            let kind = request.event.kind();
            let gated_completion = lock(&self.task_completion_gate)
                .clone()
                .filter(|gate| gate.matches(&request.event));
            if let Some(observer) = lock(&self.delivery_observer).clone() {
                observer(&request.event);
            }
            let executor_task_ids = self.executor.task_ids();
            lock(&self.events).push(RecordedEvent {
                event: request.event,
                executor_task_ids,
            });
            if let Some(gate) = gated_completion {
                gate.wait().await;
            }
            if kind == EventKind::Spawn {
                Ok(self.spawn_outcome)
            } else {
                Ok(DeliveryOutcome::Success)
            }
        })
    }
}

struct TaskCompletionDeliveryGate {
    root_task_id: ProtocolIdentity,
    started: AtomicBool,
    released: AtomicBool,
    waker: Mutex<Option<Waker>>,
}

impl TaskCompletionDeliveryGate {
    fn new(root_task_id: ProtocolIdentity) -> Self {
        Self {
            root_task_id,
            started: AtomicBool::new(false),
            released: AtomicBool::new(false),
            waker: Mutex::new(None),
        }
    }

    fn matches(&self, event: &EventEnvelope) -> bool {
        event.kind() == EventKind::TaskCompletion
            && event
                .task_id()
                .is_some_and(|task_id| task_id != self.root_task_id)
    }

    fn started(&self) -> bool {
        self.started.load(Ordering::Acquire)
    }

    async fn wait(&self) {
        self.started.store(true, Ordering::Release);
        std::future::poll_fn(|context| {
            if self.released.load(Ordering::Acquire) {
                Poll::Ready(())
            } else {
                *lock(&self.waker) = Some(context.waker().clone());
                Poll::Pending
            }
        })
        .await;
    }

    fn release(&self) {
        self.released.store(true, Ordering::Release);
        if let Some(waker) = lock(&self.waker).take() {
            waker.wake();
        }
    }
}

