            if executor.is_runnable(task_id) {
                let _ = executor
                    .poll_task(task_id)
                    .unwrap_or_else(|error| panic!("task {task_id} poll failed: {error:?}"));
            }
        }
        let current = block_on(interpreter.test_durable_observation(execution_id))
            .unwrap_or_else(|| panic!("durable execution observation is absent"));
        if current.run_failure.is_some()
            && current.owner == Some(DurableJournalOwnerState::Released)
        {
            observation = Some(current);
            break;
        }
    }
    let observation = observation.unwrap_or_else(|| {
        panic!("failed child abort did not publish a bounded durable run failure")
    });
    assert!(observation.run_failure.is_some());
    assert_eq!(observation.owner, Some(DurableJournalOwnerState::Released));
}

#[test]
fn child_executor_rejection_settles_without_submitting_another_driver() {
    let root = TempDirectory::new("fn main() { spawn child -> Int { 7 } discard join(child); }");
    let executor = Arc::new(DeterministicConcurrentExecutor::default());
    let integration = Arc::new(ScriptedIntegration::new(
        [ScriptedPreflight::success(
            EmbeddingOperation::ResolveSessions,
            &br#"{"result":"resolved"}"#[..],
        )],
        [],
    ));
    let sink = Arc::new(RecordingSink::new(
        Arc::clone(&executor),
        DeliveryOutcome::Success,
    ));
    let interpreter = interpreter_with_delivery(
        Arc::clone(&executor),
        integration,
        8,
        65_536,
        plan(SinkClass::BestEffort, sink.clone()),
    );
    executor.poll_next_spawn_immediately();
    let accepted = accepted(&interpreter, &root);
    let handle = accepted.handle().clone();
    drop(accepted);

    let rejection_was_published = Arc::new(AtomicBool::new(false));
    let observed_rejection = Arc::clone(&rejection_was_published);
    let observing_interpreter = interpreter.clone();
    let execution_id = handle.execution_id();
    sink.observe_delivery(Arc::new(move |event| {
        if event.kind() != EventKind::TaskCompletion {
            return;
        }
        let task_id = event
            .task_id()
            .unwrap_or_else(|| panic!("task completion omitted its task identity"));
        let state = observing_interpreter
            .test_nondurable_task_state(execution_id)
            .unwrap_or_else(|| panic!("nondurable task state is absent during delivery"));
        if task_id == state.root_task_id() {
            return;
        }
        let Some(child) = state.task(task_id) else {
            return;
        };
        assert!(matches!(
            child.status(),
            ConcurrentTaskStatusV1::Failed(failure)
                if failure.code.as_ref() == "task-submission-failure"
        ));
        assert!(child.handle_is_visible());
        assert!(!state.parent_is_suspended(state.root_task_id()));
        observed_rejection.store(true, Ordering::Release);
    }));

    let child_executor = Arc::clone(&executor);
    interpreter.test_before_nondurable_child_executor_submit(Arc::new(move || {
        child_executor.fail_next_spawn();
    }));
    let snapshot = drive_to_terminal(&executor, &interpreter, &handle);
    drive_event_delivery_to_quiescence(&executor, &interpreter);
    assert!(rejection_was_published.load(Ordering::Acquire));
    assert!(!has_source_child_driver(
        &interpreter,
        handle.execution_id()
    ));
    let task_state = interpreter
        .test_nondurable_task_state(handle.execution_id())
        .unwrap_or_else(|| panic!("nondurable task state is absent"));
    let spawn = spawn_event(&sink);
    let child_id = spawn.event.causal_ids()[1];
    let child = task_state
        .task(child_id)
        .unwrap_or_else(|| panic!("rejected child is absent from task state"));
    assert!(matches!(
        child.status(),
        ConcurrentTaskStatusV1::Failed(failure)
            if failure.code.as_ref() == "task-submission-failure"
    ));
    assert!(child.handle_is_visible());
    assert!(!task_state.parent_is_suspended(task_state.root_task_id()));
    let child_completions = sink
        .events()
        .into_iter()
        .filter(|record| {
            record.event.kind() == EventKind::TaskCompletion
                && record.event.task_id() == Some(child_id)
        })
        .count();
    assert_eq!(child_completions, 1);
    assert!(matches!(
        snapshot.foreground,
        Some(gantry::runtime::MachineOutcome::Failed(ref failure))
            if failure.code
                == gantry::runtime::RuntimeCode::Operation(
                    RuntimeErrorCategory::TaskJoinFailure
                )
    ));
    assert_eq!(
        snapshot
            .terminal
            .as_ref()
            .map(|terminal| &terminal.foreground),
        snapshot.foreground.as_ref()
    );
}

