    assert_eq!(compacted_recovered.cancellation, live.cancellation);
    assert_eq!(
        compacted_recovered.required_delivery_failures,
        live.required_delivery_failures
    );
    assert_eq!(compacted_recovered.terminal, live.terminal);
}

#[test]
fn durable_parent_failure_cancels_only_attached_descendants_before_settlement() {
    let root = TempDirectory::new(
        r#"
fn main() {
    spawn attached -> Int { 7 }
    spawn background -> Int { 8 }
    detach(background);
    discard 1 / 0;
    discard join(attached);
}
"#,
    );
    let executor = Arc::new(DeterministicConcurrentExecutor::default());
    let integration = Arc::new(ScriptedIntegration::new(
        [
            ScriptedPreflight::success(
                EmbeddingOperation::ResolveSessions,
                &br#"{"result":"resolved"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
        ],
        [],
    ));
    let interpreter = interpreter_with_delivery(
        Arc::clone(&executor),
        integration,
        8,
        65_536,
        SinkPlan::default(),
    );
    let storage = Arc::new(InMemoryJournalStore::new());
    let journal_id = JournalId::new("durable-parent-failure-descendant-cancellation")
        .unwrap_or_else(|error| panic!("journal identity failed: {error:?}"));
    let accepted = durable_accepted(&interpreter, &root, storage.clone(), journal_id.clone());
    let execution_id = accepted.execution_id();
    let snapshot = drive_to_terminal(&executor, &interpreter, accepted.handle());
    assert!(matches!(
        snapshot.foreground,
        Some(MachineOutcome::Failed(ref failure))
            if failure.code
                == RuntimeCode::Deterministic(
                    gantry::portable::DeterministicEvaluationCode::IntegerDivisionByZero,
                )
    ));
    assert!(snapshot.cancellation.is_none());

    let prefix = block_on(storage.read_prefix(ReadJournalPrefixV1 {
        journal_id: journal_id.clone(),
    }))
    .unwrap_or_else(|error| panic!("parent-failure journal read failed: {error:?}"));
    let (program, graph_entries) = durable_graph_entries(&prefix);
    let creations = graph_entries
        .iter()
        .filter(|(_, evidence)| evidence.cut() == DurableCommitCutV1::TaskCreation)
        .map(|(_, evidence)| evidence.task_id())
        .collect::<Vec<_>>();
    assert_eq!(creations.len(), 2);
    let detached_id = graph_entries
        .iter()
        .find(|(_, evidence)| evidence.cut() == DurableCommitCutV1::TaskOwnership)
        .map(|(_, evidence)| evidence.task_id())
        .unwrap_or_else(|| panic!("detached ownership cut is absent"));
    let attached_id = creations
        .iter()
        .copied()
        .find(|task_id| *task_id != detached_id)
        .unwrap_or_else(|| panic!("attached child creation is absent"));
    let root_id = graph_entries
        .first()
        .map(|(_, evidence)| evidence.checkpoint().root_task_id())
        .unwrap_or_else(|| panic!("durable graph evidence is absent"));

    let cancellation = graph_entries
        .iter()
        .find(|(_, evidence)| evidence.cut() == DurableCommitCutV1::Cancellation)
        .unwrap_or_else(|| panic!("attached-descendant cancellation cut is absent"));
    assert_eq!(cancellation.1.task_id(), attached_id);
    assert!(matches!(cancellation.1, ConcurrentDurableEvidence::V4(_)));
    assert!(cancellation.1.checkpoint().task_is_cancelled(attached_id));
    assert!(!cancellation.1.checkpoint().task_is_cancelled(root_id));
    assert!(!cancellation.1.checkpoint().task_is_cancelled(detached_id));
    assert_eq!(
        cancellation.1.checkpoint().task_status(root_id),
        Some(TaskStatusKind::Running),
        "parent settlement became visible in the cancellation cut"
    );

    let attached_settlement = graph_entries
        .iter()
        .find(|(_, evidence)| {
            evidence.cut() == DurableCommitCutV1::TaskSettlement
                && evidence.task_id() == attached_id
        })
        .unwrap_or_else(|| panic!("attached descendant settlement is absent"));
    let root_settlement = graph_entries
        .iter()
        .find(|(_, evidence)| {
            evidence.cut() == DurableCommitCutV1::TaskSettlement && evidence.task_id() == root_id
        })
        .unwrap_or_else(|| panic!("failed parent settlement is absent"));
    let detached_settlement = graph_entries
        .iter()
        .find(|(_, evidence)| {
            evidence.cut() == DurableCommitCutV1::TaskSettlement
                && evidence.task_id() == detached_id
        })
        .unwrap_or_else(|| panic!("detached child settlement is absent"));
    assert!(cancellation.0 < attached_settlement.0);
    assert!(attached_settlement.0 < root_settlement.0);
    assert_eq!(
        attached_settlement.1.checkpoint().task_status(attached_id),
        Some(TaskStatusKind::Cancelled)
    );
    assert_eq!(
        detached_settlement.1.checkpoint().task_status(detached_id),
        Some(TaskStatusKind::Succeeded)
    );

    let recovered = recover_concurrent_authoritative_prefix(Arc::clone(&program), &prefix)
        .unwrap_or_else(|error| panic!("parent-failure prefix failed recovery: {error:?}"));
    assert!(recovered.cancellation_reason().is_none());
    let JournalPrefixV1::Full(committed) = &prefix else {
        panic!("expected full cancellation prefix");
    };
    let cause = committed
        .evidence
        .iter()
        .find(|entry| entry.sequence == cancellation.0)
        .unwrap_or_else(|| panic!("missing cancellation cause"))
        .evidence_id;
    let event = recovered
        .events()
        .task_cancellation_for_cause(cause, attached_id)
        .unwrap_or_else(|| panic!("missing descendant cancellation event"));
    assert!(cancellation.0 < event.occurrence_sequence());
    assert!(event.occurrence_sequence() < attached_settlement.0);
    let state = recovered.execution().scheduler().state();
    assert!(matches!(
        state.task(attached_id).map(|task| task.status()),
        Some(ConcurrentTaskStatusV1::Cancelled(_))
    ));
    assert!(matches!(
        state.task(detached_id).map(|task| task.status()),
        Some(ConcurrentTaskStatusV1::Succeeded(_))
    ));
    assert!(matches!(
        state.root_settled_outcome(),
        Some(MachineOutcome::Failed(failure))
            if failure.code
                == RuntimeCode::Deterministic(
                    gantry::portable::DeterministicEvaluationCode::IntegerDivisionByZero,
                )
    ));

    let JournalPrefixV1::Full(full) = &prefix else {
        unreachable!("in-memory journal retains its full prefix")
    };
    let mut tampered_evidence = full.evidence.to_vec();
    let cancellation_envelope = tampered_evidence
        .iter_mut()
        .find(|entry| entry.sequence == cancellation.0)
        .unwrap_or_else(|| panic!("cancellation envelope is absent"));
    assert!(!cancellation_envelope.references.is_empty());
    cancellation_envelope.references = Arc::from([]);
    let tampered = JournalPrefixV1::Full(FullJournalPrefixV1 {
        journal_id: journal_id.clone(),
        evidence: Arc::from(tampered_evidence),
        committed_through: full.committed_through,
    });
    assert!(
        recover_concurrent_authoritative_prefix(program, &tampered).is_err(),
        "recovery accepted a cancellation cut detached from its causal predecessor"
    );
    assert_eq!(snapshot.execution_id, execution_id);
}

#[test]
fn durable_nested_parent_failure_retains_outcome_and_does_not_cancel_siblings() {
    let root = TempDirectory::new(
        r#"
fn main() {
    spawn parent -> Int {
        spawn attached -> Int { 7 }
        spawn background -> Int { 8 }
        detach(background);
        discard 1 / 0;
        discard join(attached);
        0
    }
    spawn sibling -> Int { 9 }
    discard join(parent, sibling);
}
"#,
    );
    let executor = Arc::new(DeterministicConcurrentExecutor::default());
    let integration = Arc::new(ScriptedIntegration::new(
        [
            ScriptedPreflight::success(
                EmbeddingOperation::ResolveSessions,
                &br#"{"result":"resolved"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
        ],
        [],
    ));
    let interpreter = interpreter_with_delivery(
        Arc::clone(&executor),
        integration,
        8,
        65_536,
        SinkPlan::default(),
    );
    let storage = Arc::new(InMemoryJournalStore::new());
    let journal_id = JournalId::new("durable-nested-parent-failure-cancellation")
        .unwrap_or_else(|error| panic!("journal identity failed: {error:?}"));
    let accepted = durable_accepted(&interpreter, &root, storage.clone(), journal_id.clone());

    for _ in 0..64 {
        if executor.task_ids().len() >= 3 {
            break;
        }
        if executor.is_runnable(0) {
            let _ = executor
                .poll_task(0)
                .unwrap_or_else(|error| panic!("root setup poll failed: {error:?}"));
        }
    }
    assert_eq!(executor.task_ids(), [0, 1, 2]);

    let mut cancellation_prefix = None;
    for _ in 0..128 {
        if executor.is_runnable(1) {
            let _ = executor
                .poll_task(1)
                .unwrap_or_else(|error| panic!("parent setup poll failed: {error:?}"));
        }
        let prefix = block_on(storage.read_prefix(ReadJournalPrefixV1 {
            journal_id: journal_id.clone(),
        }))
        .unwrap_or_else(|error| panic!("cancellation-prefix read failed: {error:?}"));
        let (_, entries) = durable_graph_entries(&prefix);
        if entries
            .iter()
            .any(|(_, evidence)| evidence.cut() == DurableCommitCutV1::Cancellation)
        {
            cancellation_prefix = Some(prefix);
            break;
        }
    }
    let cancellation_prefix = cancellation_prefix
        .unwrap_or_else(|| panic!("nested parent did not commit descendant cancellation"));
    let (program, cancellation_entries) = durable_graph_entries(&cancellation_prefix);
    let creations = cancellation_entries
        .iter()
        .filter(|(_, evidence)| evidence.cut() == DurableCommitCutV1::TaskCreation)
        .map(|(_, evidence)| evidence.task_id())
        .collect::<Vec<_>>();
    let [parent_id, sibling_id, attached_id, detached_id] = creations.as_slice() else {
        panic!("unexpected nested task creation order: {creations:?}")
    };
    let cancellation = cancellation_entries
        .iter()
        .find(|(_, evidence)| evidence.cut() == DurableCommitCutV1::Cancellation)
        .unwrap_or_else(|| panic!("nested cancellation cut is absent"));
    assert_eq!(cancellation.1.task_id(), *attached_id);
    assert!(cancellation.1.checkpoint().task_is_cancelled(*attached_id));
    assert!(!cancellation.1.checkpoint().task_is_cancelled(*parent_id));
    assert!(!cancellation.1.checkpoint().task_is_cancelled(*sibling_id));
    assert!(!cancellation.1.checkpoint().task_is_cancelled(*detached_id));
    assert_eq!(
        cancellation.1.checkpoint().task_status(*parent_id),
        Some(TaskStatusKind::Running),
        "parent settlement leaked into its descendant-cancellation cut"
    );

    let recovered_cut =
        recover_concurrent_authoritative_prefix(Arc::clone(&program), &cancellation_prefix)
            .unwrap_or_else(|error| panic!("nested cancellation cut failed recovery: {error:?}"));
    assert!(recovered_cut.cancellation_reason().is_none());
    let cut_state = recovered_cut.execution().scheduler().state();
    assert!(matches!(
        cut_state
            .task_record(*parent_id)
            .and_then(|record| record.pending_outcome()),
        Some(MachineOutcome::Failed(failure))
            if failure.code
                == RuntimeCode::Deterministic(
                    gantry::portable::DeterministicEvaluationCode::IntegerDivisionByZero,
                )
    ));
    assert!(matches!(
        cut_state.task(*attached_id).map(|task| task.status()),
        Some(ConcurrentTaskStatusV1::Running)
    ));
    assert!(matches!(
        cut_state.task(*sibling_id).map(|task| task.status()),
        Some(ConcurrentTaskStatusV1::Running)
    ));
    assert!(matches!(
        cut_state.task(*detached_id).map(|task| task.status()),
        Some(ConcurrentTaskStatusV1::Running)
    ));

    let terminal = drive_to_terminal(&executor, &interpreter, accepted.handle());
    assert!(terminal.terminal.is_some());
    let final_prefix = block_on(storage.read_prefix(ReadJournalPrefixV1 { journal_id }))
        .unwrap_or_else(|error| panic!("final nested journal read failed: {error:?}"));
    let (_, final_entries) = durable_graph_entries(&final_prefix);
    let settlement_sequence = |task_id| {
        final_entries
            .iter()
            .find(|(_, evidence)| {
                evidence.cut() == DurableCommitCutV1::TaskSettlement
                    && evidence.task_id() == task_id
            })
            .map(|(sequence, _)| *sequence)
            .unwrap_or_else(|| panic!("settlement for task {task_id} is absent"))
    };
    let attached_settlement = settlement_sequence(*attached_id);
    let parent_settlement = settlement_sequence(*parent_id);
    assert!(cancellation.0 < attached_settlement);
    assert!(attached_settlement < parent_settlement);

    let recovered_final = recover_concurrent_authoritative_prefix(program, &final_prefix)
        .unwrap_or_else(|error| panic!("final nested prefix failed recovery: {error:?}"));
    let final_state = recovered_final.execution().scheduler().state();
    assert!(matches!(
        final_state.task(*attached_id).map(|task| task.status()),
        Some(ConcurrentTaskStatusV1::Cancelled(_))
    ));
    assert!(matches!(
        final_state.task(*sibling_id).map(|task| task.status()),
        Some(ConcurrentTaskStatusV1::Succeeded(_))
    ));
    assert!(matches!(
        final_state.task(*detached_id).map(|task| task.status()),
        Some(ConcurrentTaskStatusV1::Succeeded(_))
    ));
}

#[test]
fn public_durable_graph_cancellation_commits_before_signalling_and_finishes() {
    let root = TempDirectory::new("fn main() { spawn child -> Int { 7 } discard join(child); }");
    let executor = Arc::new(DeterministicConcurrentExecutor::default());
    let integration = Arc::new(ScriptedIntegration::new(
        [
            ScriptedPreflight::success(
                EmbeddingOperation::ResolveSessions,
                &br#"{"result":"resolved"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
        ],
        [],
    ));
    let interpreter = interpreter_with_delivery(
        Arc::clone(&executor),
        integration,
        8,
        65_536,
        SinkPlan::default(),
    );
    let storage = Arc::new(CountingJournalStore::default());
    let journal_id = JournalId::new("durable-source-spawn-public-cancellation")
        .unwrap_or_else(|error| panic!("journal identity failed: {error:?}"));
    let accepted = durable_accepted(&interpreter, &root, storage.clone(), journal_id.clone());
    let execution_id = accepted.execution_id();
    let signal = accepted
        .handle()
        .cancellation_signal()
        .unwrap_or_else(|error| panic!("cancellation signal failed: {error:?}"));
    assert!(matches!(
        executor.poll_task(0),
        Ok(DeterministicTaskPoll::Pending)
    ));
    assert_eq!(executor.task_ids(), [0, 1]);

    let reason = caller_cancellation_reason(Some(Arc::from("cancel-graph")), 64)
        .unwrap_or_else(|error| panic!("cancellation reason failed: {error:?}"));
    let mut cancellation = pin!(interpreter.cancel_execution(execution_id, reason.clone()));
    assert!(
        cancellation
            .as_mut()
            .poll(&mut Context::from_waker(Waker::noop()))
            .is_pending()
    );
    assert!(!signal.is_cancelled());
    assert!(matches!(
        executor.poll_task(0),
        Ok(DeterministicTaskPoll::Pending | DeterministicTaskPoll::Settled(_))
    ));
    assert!(signal.is_cancelled());

    let record = 'drive: loop {
        if let Poll::Ready(result) = cancellation
            .as_mut()
            .poll(&mut Context::from_waker(Waker::noop()))
        {
            break 'drive result.unwrap_or_else(|error| panic!("cancellation failed: {error:?}"));
        }
        for task_id in executor.task_ids() {
            if executor.is_runnable(task_id) {
                let _ = executor
                    .poll_task(task_id)
                    .unwrap_or_else(|error| panic!("task {task_id} poll failed: {error:?}"));
            }
        }
    };
    assert!(matches!(
        record,
        CancellationRecord::Accepted { reason: ref effective, .. } if effective == &reason
    ));
    assert_eq!(storage.release_count(), 1);
    let snapshot = interpreter
        .query_execution(execution_id)
        .unwrap_or_else(|error| panic!("execution query failed: {error:?}"))
        .unwrap_or_else(|| panic!("cancelled execution disappeared"));
    assert_eq!(snapshot.cancellation, Some(reason.clone()));
    assert!(snapshot.terminal.is_some());

    let prefix = block_on(storage.read_prefix(ReadJournalPrefixV1 {
        journal_id: journal_id.clone(),
    }))
    .unwrap_or_else(|error| panic!("journal read failed: {error:?}"));
    let storage_adapter: Arc<dyn JournalStorage> = storage.clone();
    let queried = block_on(DurableLifecycleCoordinator::new(storage_adapter).query(
        DurableQueryExecutionRequest {
            journal_id,
            expected_execution_id: Some(execution_id),
        },
    ));
    let DurableQueryExecutionResult::Snapshot(recovered) = queried else {
        panic!("cancelled concurrent query did not recover a snapshot: {queried:?}")
    };
    assert_eq!(recovered.cancellation, Some(reason));
    assert!(recovered.terminal.is_some());
    let (program, graph_entries) = durable_graph_entries(&prefix);
    let cancellation_sequence = graph_entries
        .iter()
        .find(|(_, evidence)| evidence.cut() == DurableCommitCutV1::Cancellation)
        .map(|(sequence, _)| *sequence)
        .unwrap_or_else(|| panic!("graph cancellation cut is absent"));
    let first_settlement = graph_entries
        .iter()
        .find(|(sequence, evidence)| {
            *sequence > cancellation_sequence
                && evidence.cut() == DurableCommitCutV1::TaskSettlement
        })
        .map(|(sequence, _)| *sequence)
        .unwrap_or_else(|| panic!("post-cancellation task settlement is absent"));
    let JournalPrefixV1::Full(full) = &prefix else {
        unreachable!("in-memory journal retains its full prefix")
    };
    let cancellation_event_sequence = full
        .evidence
        .iter()
        .find_map(|entry| {
            (entry.kind.as_ref() == DURABLE_EVENT_OCCURRENCE_KIND_V1)
                .then(|| DurableEventOccurrenceV1::decode(&entry.canonical_body).ok())
                .flatten()
                .filter(|occurrence| occurrence.event().kind() == EventKind::Cancellation)
                .map(|_| entry.sequence)
        })
        .unwrap_or_else(|| panic!("durable graph cancellation event is absent"));
    assert!(cancellation_sequence < cancellation_event_sequence);
    assert!(cancellation_event_sequence < first_settlement);

    let cancellation_events = full
        .evidence
        .iter()
        .filter_map(|entry| {
            (entry.kind.as_ref() == DURABLE_EVENT_OCCURRENCE_KIND_V1)
                .then(|| DurableEventOccurrenceV1::decode(&entry.canonical_body).ok())
                .flatten()
        })
        .filter(|occurrence| occurrence.event().kind() == EventKind::Cancellation)
        .collect::<Vec<_>>();
    for task in graph_entries
        .iter()
        .find(|(sequence, _)| *sequence == cancellation_sequence)
        .unwrap_or_else(|| panic!("cancellation checkpoint missing"))
        .1
        .checkpoint()
        .task_ids()
    {
        assert_eq!(
            cancellation_events
                .iter()
                .filter(|occurrence| {
                    let event = occurrence.event();
                    event.task_id() == Some(task)
                        && std::str::from_utf8(event.payload().canonical_bytes())
                            .is_ok_and(|payload| payload.contains("\"target_kind\":\"task\""))
                })
                .count(),
            1,
            "missing live task cancellation event for {task}"
        );
    }

    let cancellation = graph_entries
        .iter()
        .find(|(sequence, _)| *sequence == cancellation_sequence)
        .unwrap_or_else(|| panic!("cancellation graph evidence is absent"));
    let legacy = ConcurrentDurableEvidenceV4::new(
        DurableCommitCutV1::Cancellation,
        cancellation.1.task_id(),
        cancellation.1.checkpoint().clone(),
    )
    .unwrap_or_else(|error| panic!("legacy cancellation fixture failed: {error:?}"));
    let mut evidence = full.evidence.to_vec();
    let envelope = evidence
        .iter_mut()
        .find(|entry| entry.sequence == cancellation_sequence)
        .unwrap_or_else(|| panic!("cancellation envelope is absent"));
    envelope.kind = Arc::from(CONCURRENT_DURABLE_EVIDENCE_KIND_V4);
    envelope.canonical_body = Arc::from(legacy.canonical_body());
    let untyped = JournalPrefixV1::Full(gantry::host::journal::FullJournalPrefixV1 {
        journal_id: full.journal_id.clone(),
        evidence: Arc::from(evidence),
        committed_through: full.committed_through,
    });
    let recovered_untyped = recover_concurrent_authoritative_prefix(program, &untyped)
        .unwrap_or_else(|error| panic!("legacy v4 cancellation did not recover: {error:?}"));
    assert_eq!(recovered_untyped.cancellation_reason(), None);
    assert_eq!(
        recovered_untyped
            .execution()
            .scheduler()
            .state()
            .task_cancellation_reason(cancellation.1.task_id()),
        Some("cancel-graph")
    );
}

#[test]
fn durable_graph_owner_releases_after_physical_quiescence_and_finite_events() {
    let root = TempDirectory::new("fn main() { spawn child -> Int { 7 } discard join(child); }");
    let executor = Arc::new(DeterministicConcurrentExecutor::default());
    let integration = Arc::new(ScriptedIntegration::new(
        [
            ScriptedPreflight::success(
                EmbeddingOperation::ResolveSessions,
                &br#"{"result":"resolved"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
        ],
        [],
    ));
    let sink = Arc::new(RecordingSink::new(
        Arc::clone(&executor),
        DeliveryOutcome::Success,
    ));
    let interpreter = interpreter_with_delivery(
        Arc::clone(&executor),
        integration,
        8,
        65_536,
        plan(SinkClass::BestEffort, sink.clone()),
    );
    let storage = Arc::new(CountingJournalStore::default());
    let terminal_delivered = Arc::new(AtomicBool::new(false));
    let observed_terminal = Arc::clone(&terminal_delivered);
    sink.observe_delivery(Arc::new(move |event| {
        if event.kind() == EventKind::TerminalExecution {
            observed_terminal.store(true, Ordering::Release);
        }
    }));
    storage.observe_release_after(Arc::clone(&terminal_delivered));
    let journal_id = JournalId::new("durable-source-spawn-owner-quiescence")
        .unwrap_or_else(|error| panic!("journal identity failed: {error:?}"));
    executor.poll_next_spawn_immediately();
    let accepted = durable_accepted(&interpreter, &root, storage.clone(), journal_id);
    let handle = accepted.handle().clone();

    let snapshot = drive_to_terminal(&executor, &interpreter, &handle);
    assert!(snapshot.terminal.is_some());
    for task_id in executor.task_ids() {
        if executor.is_runnable(task_id) {
            let _ = executor
                .poll_task(task_id)
                .unwrap_or_else(|error| panic!("finalizer task {task_id} failed: {error:?}"));
        }
    }
    assert_eq!(storage.release_count(), 1);
    assert!(terminal_delivered.load(Ordering::Acquire));
    assert!(!storage.released_too_early());
}

#[test]
fn durable_graph_finalizer_bounds_pending_completion_after_failed_abort() {
    let root = TempDirectory::new("fn main() { spawn child -> Int { 7 } discard join(child); }");
    let executor = Arc::new(DeterministicConcurrentExecutor::default());
    executor.control_sleeps();
    let executor_adapter: Arc<dyn ExecutorAdapter> = Arc::new(
        FailAbortExecutor::with_pending_completion(Arc::clone(&executor), 0),
    );
    let integration = Arc::new(ScriptedIntegration::new(
        [
            ScriptedPreflight::success(
                EmbeddingOperation::ResolveSessions,
                &br#"{"result":"resolved"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
            ScriptedPreflight::success(
                EmbeddingOperation::EstablishSession,
                &br#"{"result":"established"}"#[..],
            ),
        ],
        [],
    ));
    let interpreter = interpreter_with_session_service(
        executor_adapter,
        integration.clone(),
        integration,
        8,
        65_536,
        SinkPlan::default(),
    );
    let storage = Arc::new(CountingJournalStore::default());
    let journal_id = JournalId::new("durable-source-spawn-finalizer-pending-completion")
        .unwrap_or_else(|error| panic!("journal identity failed: {error:?}"));
    executor.poll_next_spawn_immediately();
    let accepted = durable_accepted(&interpreter, &root, storage.clone(), journal_id);
    let execution_id = accepted.execution_id();

    let snapshot = drive_to_terminal(&executor, &interpreter, accepted.handle());
    assert!(snapshot.terminal.is_some());
    let finalizer_task = *executor
        .task_ids()
        .last()
        .unwrap_or_else(|| panic!("terminal graph submitted no finalizer"));
    assert!(matches!(
        executor.poll_task(finalizer_task),
        Ok(DeterministicTaskPoll::Pending | DeterministicTaskPoll::NotRunnable)
    ));
    assert_eq!(
        executor.sleep_durations(),
        [DurationMicros::new(5_000_000)
            .unwrap_or_else(|| unreachable!("configured drain is finite"))]
    );
    executor
        .release_sleep(0)
        .unwrap_or_else(|error| panic!("finalizer deadline release failed: {error:?}"));
    assert!(matches!(
        executor.poll_task(finalizer_task),
        Ok(DeterministicTaskPoll::Settled(_))
    ));

    let observation = block_on(interpreter.test_durable_observation(execution_id))
        .unwrap_or_else(|| panic!("durable execution observation is absent"));
    assert_eq!(observation.run_failure, Some(DurableRunFailure::Internal));
    assert_eq!(observation.owner, Some(DurableJournalOwnerState::Released));
    assert_eq!(storage.release_count(), 1);
    let supervision = interpreter.test_task_supervisor_snapshot();
    assert!(supervision.tasks.iter().any(|task| {
        task.completion.is_none()
            && matches!(task.abort_result, Some(OwnedTaskAbort::Failed(_)))
            && task.control_relinquished
    }));
}

