            assert!(matches!(
                snapshot.foreground,
                Some(MachineOutcome::Failed(ref failure))
                    if failure.code
                        == RuntimeCode::Operation(RuntimeErrorCategory::TaskJoinFailure)
            ));
            assert_eq!(
                snapshot
                    .terminal
                    .as_ref()
                    .map(|terminal| &terminal.foreground),
                snapshot.foreground.as_ref()
            );

