        .code(),
        StdlibDiagnosticCode::InvalidNameClassification
    );
    for path in ["crates::console", "std.", "std::console", "std.IO"] {
        assert_eq!(
            refuse(
                StdName::new(path, NameClass::Module, "std.io"),
                "a malformed logical name"
