#[test]
fn consumers_must_present_the_published_identity_and_digests() {
    let graph = graph_with(&[
        package(PackageFamily::Core, StabilityTier::Foundational, &[], &[]),
        package(PackageFamily::Text, StabilityTier::Stable, &[], &[]),
    ]);
    let contract = StdContractVersion::new(1, 2)
        .unwrap_or_else(|error| panic!("the fixture contract version is valid: {error}"));
    let manifest = graph
        .manifest(contract)
        .unwrap_or_else(|error| panic!("the fixture manifest is valid: {error}"));
    let interfaces: BTreeMap<String, String> = manifest
        .entries()
        .iter()
        .map(|entry| {
            (
                entry.name().to_owned(),
                entry.identity().as_str().to_owned(),
            )
        })
        .collect();
    manifest
        .admit_consumer(contract, manifest.identity().as_str(), &interfaces)
        .unwrap_or_else(|error| panic!("the published consumer is admitted: {error}"));
    assert!(
        manifest
            .entries()
            .iter()
            .all(|entry| { !entry.modes().is_empty() && !entry.targets().is_empty() })
    );

    let other = StdContractVersion::new(1, 3)
        .unwrap_or_else(|error| panic!("the fixture contract version is valid: {error}"));
    assert_eq!(
        refuse(
            manifest.admit_consumer(other, manifest.identity().as_str(), &interfaces),
            "a differing contract version"
        )
        .code(),
        StdlibDiagnosticCode::ContractVersionMismatch
    );
    assert_eq!(
        refuse(
            manifest.admit_consumer(contract, "std-graph-v1:other", &interfaces),
            "a differing graph identity"
        )
        .code(),
        StdlibDiagnosticCode::ContractVersionMismatch
    );
    let mut altered = interfaces.clone();
    let first = manifest
        .entries()
        .first()
        .unwrap_or_else(|| panic!("the fixture manifest has entries"))
        .name()
        .to_owned();
    altered.insert(first.clone(), "std-package-v1:other".to_owned());
    assert_eq!(
        refuse(
            manifest.admit_consumer(contract, manifest.identity().as_str(), &altered),
            "a differing interface digest"
        )
        .code(),
        StdlibDiagnosticCode::ContractVersionMismatch
    );
    let mut incomplete = interfaces.clone();
    incomplete.remove(&first);
    assert_eq!(
        refuse(
            manifest.admit_consumer(contract, manifest.identity().as_str(), &incomplete),
            "a consumer without every interface digest"
        )
        .code(),
        StdlibDiagnosticCode::ContractVersionMismatch
    );
}

#[test]
fn preludes_are_edition_versioned_and_never_silently_extended() {
    let declared = prelude();
    assert_eq!(declared.edition(), "2026");
    let same = declared
        .for_edition("2026", &["std.core::option", "std.core::result"])
        .unwrap_or_else(|error| panic!("a redeclared edition is admitted: {error}"));
    assert_eq!(same.members(), declared.members());
    assert_eq!(
        refuse(
            declared.for_edition("2026", &["std.core::option"]),
            "a silent extension of a declared edition"
        )
        .code(),
        StdlibDiagnosticCode::UnenumeratedPreludeMember
    );
    let next = declared
        .for_edition("2029", &["std.core::option"])
        .unwrap_or_else(|error| panic!("a new edition is admitted: {error}"));
    assert_eq!(next.edition(), "2029");
    assert_eq!(next.members().len(), 1);
    assert_eq!(
        refuse(Prelude::new("", &[]), "an undeclared edition").code(),
        StdlibDiagnosticCode::UnenumeratedPreludeMember
    );
}

//! Machine-checked conformance for execution targets, features, and bindings.
//!
//! These tests exercise the public model of [`gantry::ir`] for `GNT-17.0`
//! through `GNT-17.13-runtime-availability-separation`. They check the pure
//! rules the specification makes normative, not a build system: no test here
//! reads an environment variable, a host path, a clock, a locale, a discovered
//! service, or a filesystem, because a target descriptor, a feature solution,
//! and an artifact binding MUST NOT be derived from those things.

use std::collections::BTreeSet;
use std::sync::Arc;

use gantry::ir::{
    AUTHORITY_RIGHT_ORDER, AbiEnvironment, Architecture, AuthorityRight, BranchDeclaration,
    BranchMatch, BranchOutcome, BuildHostAuthority, BuildHostAuthorityDigest, BuildHostCapability,
    BuildInput, BuildInputDigest, BuildInputRecord, BuildInputRecordDigest, CanonicalIrDigest,
    CanonicalPath, ConditionalSelectionRule, DeclaredFactKind, DeclaredFacts,
    ExecutionTargetDescriptor, ExpectedInputs, FeatureDeclaration, FeatureDeclarations,
    FeatureName, FeatureSolution, FeatureSolutionDigest, GeneratedOutput, GeneratedOutputHash,
    GeneratedOutputSet, GeneratorInputs, InterfaceDigest, ModeAdmission, OperatingSystemFamily,
    PackageIdentity, PackageIdentityInputs, PackageName, PackageSourceIdentity, PackageVersion,
    PredicateOutcome, PredicateOutcomeSet, RetainedClosure, RetainedClosureDigest,
    RunnerCapability, SelectedFeatureSet, SourceManifestDigest, TargetArtifactBinding,
    TargetArtifactBindingRecord, TargetDescriptor, TargetDescriptorDigest, TargetDescriptorField,
    TargetDescriptorRecord, TargetDiagnosticCode, TargetError, TargetFactSet, TargetFactsRecord,
    TargetKind, TargetMatrix, TargetMatrixDigest, TargetMatrixEntry, TargetMatrixState,
    TargetPredicate, TargetPredicateName, TargetSet, ToolchainIdentity,
};
use gantry::portable::DiagnosticCategory;
use gantry::protocol::ProtocolVersion;
use gantry::source::{
    DIAGNOSTIC_CODE_REGISTRY, DiagnosticPhase, validate_diagnostic_code_registry,
};
use sha2::{Digest, Sha256};

/// The model source guarded by the ambient-fact test.
const MODEL_SOURCE: &str = include_str!("../../gantry-ir/src/target.rs");

/// The exact canonical encoding of the fixture descriptor of these tests.
const CANONICAL_DESCRIPTOR: &str = concat!(
    "{\"abi\":\"gnu\",\"architecture\":\"x86_64\",\"edition\":\"2026\",",
    "\"os_family\":\"linux\",\"semantic_mode\":\"portable\",",
    "\"stdlib_contract\":{\"major\":1,\"minor\":0},\"version_of_record\":1}"
);

/// Returns one deterministic lowercase hexadecimal fixture digest.
fn hex(seed: &str) -> String {
    format!("{:x}", Sha256::digest(seed.as_bytes()))
}

/// Returns one labeled package-source-manifest digest.
fn manifest_digest(seed: &str) -> SourceManifestDigest {
    SourceManifestDigest::from_hex(&hex(seed))
        .unwrap_or_else(|_| unreachable!("fixture digest is lowercase hexadecimal"))
}

/// Returns one labeled canonical-IR digest.
fn ir_digest(seed: &str) -> CanonicalIrDigest {
    CanonicalIrDigest::from_hex(&hex(seed))
        .unwrap_or_else(|_| unreachable!("fixture digest is lowercase hexadecimal"))
}

/// Returns one standalone public-interface digest.
fn interface_digest(seed: &str) -> InterfaceDigest {
    InterfaceDigest::from_hex(&hex(seed))
        .unwrap_or_else(|_| unreachable!("fixture digest is lowercase hexadecimal"))
}

/// Returns one standalone target-descriptor digest.
fn descriptor_digest(seed: &str) -> TargetDescriptorDigest {
    TargetDescriptorDigest::from_hex(&hex(seed))
        .unwrap_or_else(|_| unreachable!("fixture digest is lowercase hexadecimal"))
}

/// Returns one standalone toolchain identity.
fn toolchain() -> ToolchainIdentity {
    ToolchainIdentity::from_hex(&hex("toolchain"))
        .unwrap_or_else(|_| unreachable!("fixture digest is lowercase hexadecimal"))
}

/// Returns the fixture package instance that owns a feature solution.
fn root(seed: &str) -> PackageIdentity {
    PackageIdentity::derive(PackageIdentityInputs::new(
        PackageName::new("app").unwrap_or_else(|_| unreachable!("fixture name is valid")),
        PackageVersion::new("1.0.0").unwrap_or_else(|_| unreachable!("fixture version is valid")),
        PackageSourceIdentity::new(
            manifest_digest(&format!("{seed}-manifest")),
            ir_digest(&format!("{seed}-ir")),
        ),
        SelectedFeatureSet::empty(),
        TargetFactSet::empty(),
        TargetFactsRecord::new(
            1,
            descriptor_digest(&format!("{seed}-descriptor")),
            FeatureSolutionDigest::from_hex(&hex(&format!("{seed}-solution")))
                .unwrap_or_else(|_| unreachable!("fixture digest is lowercase hexadecimal")),
        )
        .unwrap_or_else(|_| unreachable!("fixture selection names its version")),
        interface_digest(&format!("{seed}-interface")),
        GeneratorInputs::empty(),
    ))
}

/// Returns the fixture descriptor under the closed version-1 vocabulary.
fn descriptor_with(
    architecture: Architecture,
    operating_system: OperatingSystemFamily,
    abi_environment: AbiEnvironment,
    language_edition: &str,
    stdlib_contract: ProtocolVersion,
    mode: gantry::mode::SemanticMode,
) -> ExecutionTargetDescriptor {
    ExecutionTargetDescriptor::new(
        architecture,
        operating_system,
        abi_environment,
        language_edition,
        stdlib_contract,
        mode,
    )
    .unwrap_or_else(|_| unreachable!("fixture descriptor is well formed"))
}

/// Returns one standard-library contract version fixture.
fn stdlib(major: u64, minor: u64) -> ProtocolVersion {
    ProtocolVersion::new(major, minor).unwrap_or_else(|_| unreachable!("fixture version"))
}

/// Returns the fixture descriptor of these tests.
fn descriptor() -> ExecutionTargetDescriptor {
    descriptor_with(
        Architecture::X86_64,
        OperatingSystemFamily::Linux,
        AbiEnvironment::Gnu,
        "2026",
        stdlib(1, 0),
