{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.example/protocol/schemas/conformance-corpus-index-v1.schema.json",
  "title": "Gantry executable conformance corpus index v1",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "format": { "const": "gantry.conformance-corpus-index/v1" },
    "specification_sha256": { "type": "string", "minLength": 64 },
    "entries": {
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/$defs/entry" }
    }
  },
  "required": ["format", "specification_sha256", "entries"],
  "$defs": {
    "entry": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "evidence": { "type": "string", "minLength": 1 },
        "profiles": {
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/$defs/profile" }
        },
        "roles": {
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/$defs/role" }
        },
        "mappings": {
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/$defs/mapping" }
        }
      },
      "required": ["evidence", "profiles", "roles", "mappings"]
    },
    "mapping": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "requirement": { "type": "string", "minLength": 1 },
        "clause": { "type": "string", "minLength": 1 },
        "profile": { "$ref": "#/$defs/profile" },
        "roles": {
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/$defs/role" }
        }
      },
      "required": ["requirement", "clause", "profile", "roles"]
    },
    "profile": {
      "enum": [
        "analyzer",
        "concurrent-evaluator",
        "durable-runtime",
        "embedding",
        "evaluator",
        "frontend"
      ]
    },
    "role": { "enum": ["harness", "implementation", "integration"] }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.example/protocol/schemas/conformance-manifest-v1.schema.json",
  "title": "Gantry aggregate conformance manifest v1",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "format": { "const": "gantry.conformance-manifest/v1" },
    "specification_sha256": { "type": "string", "minLength": 64 },
    "requirement_registry": { "$ref": "#/$defs/registry" },
    "corpus": { "$ref": "#/$defs/corpus" },
    "schemas": {
      "type": "array",
      "minItems": 2,
      "maxItems": 2,
      "items": { "$ref": "#/$defs/artifact" }
    },
    "negative_vectors": { "$ref": "#/$defs/artifact" },
    "manifests": {
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/$defs/manifest" }
    },
    "gates": {
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/$defs/gate" }
    },
    "profile_results": {
      "type": "array",
      "minItems": 6,
      "maxItems": 6,
      "items": { "$ref": "#/$defs/profile_result" }
    },
    "proofs": {
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/$defs/proof" }
    }
  },
  "required": [
    "format",
    "specification_sha256",
    "requirement_registry",
    "corpus",
    "schemas",
    "negative_vectors",
    "manifests",
    "gates",
    "profile_results",
    "proofs"
  ],
  "$defs": {
    "digest": { "type": "string", "minLength": 64 },
    "count": { "type": "number", "minimum": 0, "maximum": 9007199254740991 },
    "artifact": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "path": { "type": "string", "minLength": 1 },
        "sha256": { "$ref": "#/$defs/digest" }
      },
      "required": ["path", "sha256"]
    },
    "registry": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "path": { "type": "string", "minLength": 1 },
        "sha256": { "$ref": "#/$defs/digest" },
        "requirement_count": { "$ref": "#/$defs/count" },
        "clause_count": { "$ref": "#/$defs/count" },
        "mapping_count": { "$ref": "#/$defs/count" }
      },
      "required": ["path", "sha256", "requirement_count", "clause_count", "mapping_count"]
    },
    "corpus": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "path": { "type": "string", "minLength": 1 },
        "sha256": { "$ref": "#/$defs/digest" },
        "evidence_count": { "$ref": "#/$defs/count" },
        "mapping_count": { "$ref": "#/$defs/count" }
      },
      "required": ["path", "sha256", "evidence_count", "mapping_count"]
    },
    "manifest": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "path": { "type": "string", "minLength": 1 },
        "format": { "type": "string", "minLength": 1 },
        "sha256": { "$ref": "#/$defs/digest" }
      },
      "required": ["path", "format", "sha256"]
    },
    "gate": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "gate": { "type": "string", "minLength": 1 },
        "path": { "type": "string", "minLength": 1 },
        "sha256": { "$ref": "#/$defs/digest" },
        "status": { "enum": ["blocked", "verified"] }
      },
      "required": ["gate", "path", "sha256", "status"]
    },
    "profile_result": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "profile": {
          "enum": [
            "analyzer",
            "concurrent-evaluator",
            "durable-runtime",
            "embedding",
            "evaluator",
            "frontend"
          ]
        },
        "covered_count": { "$ref": "#/$defs/count" },
        "not_applicable_count": { "$ref": "#/$defs/count" },
        "planned_count": { "$ref": "#/$defs/count" },
        "status": { "enum": ["blocked", "verified"] }
      },
      "required": [
        "profile",
        "covered_count",
        "not_applicable_count",
        "planned_count",
        "status"
      ]
    },
    "proof": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "kind": { "enum": ["argument", "model"] },
        "path": { "type": "string", "minLength": 1 },
        "sha256": { "$ref": "#/$defs/digest" }
      },
      "required": ["kind", "path", "sha256"]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.example/protocol/schemas/general-purpose-preregistration-v1.schema.json",
  "title": "Gantry general-purpose preregistration catalog v1",
  "type": "object",
  "additionalProperties": false,
  "required": ["catalog", "major", "minor", "specification_revision", "decision_record_template", "policy", "tasks", "applications", "matrix", "claim_blockers", "material_change_reruns", "issues"],
  "properties": {
    "catalog": {"const": "gantry.general-purpose-preregistration"},
    "major": {"const": 1},
    "minor": {"const": 0},
    "specification_revision": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "decision_record_template": {"type": "array", "minItems": 5, "maxItems": 5, "uniqueItems": true, "items": {"type": "string"}},
    "policy": {
      "type": "object",
      "additionalProperties": false,
      "required": ["supported_platforms", "unsupported_platforms", "provider_integration", "semantic_oracles", "agent_runs_per_task", "human_trials", "performance_gate", "quantitative_performance_thresholds"],
      "properties": {
        "supported_platforms": {"const": ["linux", "macos"]},
        "unsupported_platforms": {"const": ["windows"]},
        "provider_integration": {"const": "embedding-harness-mocked-hooks-only"},
        "semantic_oracles": {"const": ["deterministic-fakes", "mocked-hooks", "recorded-transcripts"]},
        "agent_runs_per_task": {"const": 1},
        "human_trials": {"const": "deferred-until-after-implementation"},
        "performance_gate": {"const": "functionality-first-no-obviously-suboptimal-design"},
        "quantitative_performance_thresholds": {"const": "deferred"}
      }
    },
    "tasks": {"type": "array", "minItems": 7, "maxItems": 7, "items": {"$ref": "#/$defs/task"}},
    "applications": {"type": "array", "minItems": 7, "maxItems": 7, "items": {"$ref": "#/$defs/application"}},
    "matrix": {
      "type": "object",
      "additionalProperties": false,
      "required": ["launches", "modes", "provider_evidence", "failure_cuts"],
      "properties": {
        "launches": {"const": ["embedded", "standalone"]},
        "modes": {"const": ["application", "durable", "portable"]},
        "provider_evidence": {"const": ["deterministic-fake", "mocked-hook", "recorded-transcript"]},
        "failure_cuts": {"type": "array", "minItems": 6, "uniqueItems": true, "items": {"type": "string"}}
      }
    },
    "claim_blockers": {"type": "array", "minItems": 4, "maxItems": 4, "uniqueItems": true, "items": {"type": "string"}},
    "material_change_reruns": {"type": "array", "minItems": 5, "maxItems": 5, "items": {"$ref": "#/$defs/rerun"}},
    "issues": {"type": "array", "minItems": 77, "maxItems": 77, "items": {"$ref": "#/$defs/issue"}}
  },
  "$defs": {
    "task": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "intent", "acceptance"],
      "properties": {"id": {"type": "string", "minLength": 1}, "intent": {"type": "string", "minLength": 1}, "acceptance": {"type": "string", "minLength": 1}}
    },
    "application": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "mode", "intent"],
      "properties": {"id": {"type": "string", "minLength": 1}, "mode": {"enum": ["application", "durable", "portable"]}, "intent": {"type": "string", "minLength": 1}}
    },
    "rerun": {
      "type": "object",
      "additionalProperties": false,
      "required": ["material_change", "rerun"],
      "properties": {"material_change": {"type": "string", "minLength": 1}, "rerun": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "string"}}}
    },
    "issue": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "normative_owner", "compatibility_owner", "evidence_owner", "publication_blocker", "rerun", "depends_on"],
      "properties": {
        "id": {"type": "string", "pattern": "^GNT-GP-[A-Z0-9-]+$"},
        "normative_owner": {"type": "string", "minLength": 1},
        "compatibility_owner": {"type": "string", "minLength": 1},
        "evidence_owner": {"type": "string", "minLength": 1},
        "publication_blocker": {"const": "general-purpose-profile"},
        "rerun": {"const": ["create", "debug", "explain", "modify", "security-review"]},
        "depends_on": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "string", "pattern": "^GNT-GP-[A-Z0-9-]+$"}}
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.example/protocol/schemas/publication-artifact-v1.schema.json",
  "title": "Gantry self-contained publication artifact v1",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "format": { "const": "gantry.publication-artifact/v1" },
    "id": { "type": "string", "minLength": 1 },
    "specification_sha256": { "type": "string", "minLength": 64 },
    "protocols": {
      "type": "array",
      "items": { "$ref": "#/$defs/protocol" }
    },
    "profiles": {
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/$defs/profile" }
    },
    "requirements": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "string", "minLength": 1 }
    },
    "files": {
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/$defs/file" }
    }
  },
  "required": [
    "format",
    "id",
    "specification_sha256",
    "protocols",
    "profiles",
    "requirements",
    "files"
  ],
  "$defs": {
    "protocol": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "family": { "type": "string", "minLength": 1 },
        "major": { "const": 1 },
        "minor": { "const": 0 }
      },
      "required": ["family", "major", "minor"]
    },
    "profile": {
      "enum": [
        "analyzer",
        "concurrent-evaluator",
        "durable-runtime",
        "embedding",
        "evaluator",
        "frontend"
      ]
    },
    "file": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "path": { "type": "string", "minLength": 1 },
        "media_type": {
          "enum": ["application/json", "text/markdown", "text/plain", "text/x-rust"]
        },
        "byte_length": { "type": "string", "minLength": 1 },
        "sha256": { "type": "string", "minLength": 64 },
        "content": { "type": "string" }
      },
      "required": ["path", "media_type", "byte_length", "sha256", "content"]
    }
  }
}

{
  "$id": "https://gantry.example/protocol/schemas/publication-index-v1.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "artifacts": {
      "items": { "$ref": "#/$defs/artifact" },
      "minItems": 7,
      "type": "array",
      "uniqueItems": true
    },
    "publication_index": { "$ref": "#/$defs/version" },
    "publication_revision": { "minLength": 1, "type": "string" },
    "source_language": { "$ref": "#/$defs/version" }
  },
  "required": [
    "publication_index",
    "source_language",
    "publication_revision",
    "artifacts"
  ],
  "$defs": {
    "artifact": {
      "additionalProperties": false,
      "properties": {
        "byte_length": {
          "pattern": "^(?:0|[1-9][0-9]*)$",
          "type": "string"
        },
        "id": {
          "pattern": "^[a-z0-9]+(?:[.-][a-z0-9]+)*$",
          "type": "string"
        },
        "media_type": {
          "pattern": "^[a-z0-9!#$&^_.+-]+/[a-z0-9!#$&^_.+-]+$",
          "type": "string"
        },
        "profiles": {
          "items": { "$ref": "#/$defs/profile" },
          "type": "array",
          "uniqueItems": true
        },
        "protocols": {
          "items": { "$ref": "#/$defs/protocol" },
          "type": "array",
          "uniqueItems": true
        },
        "requirements": {
          "items": {
            "pattern": "^GNT-[A-Za-z0-9.-]+$",
            "type": "string"
          },
          "type": "array",
          "uniqueItems": true
        },
        "sha256": {
          "pattern": "^[0-9a-f]{64}$",
          "type": "string"
        },
        "uri": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "id",
        "uri",
        "media_type",
        "byte_length",
        "sha256",
        "protocols",
        "profiles",
        "requirements"
      ],
      "type": "object"
    },
    "profile": {
      "enum": [
        "analyzer",
        "concurrent-evaluator",
        "durable-runtime",
        "embedding",
        "evaluator",
        "frontend"
      ]
    },
    "protocol": {
      "additionalProperties": false,
      "properties": {
        "family": {
          "pattern": "^[a-z0-9]+(?:-[a-z0-9]+)*$",
          "type": "string"
        },
        "major": { "maximum": 9007199254740991, "minimum": 0, "type": "number" },
        "minor": { "maximum": 9007199254740991, "minimum": 0, "type": "number" }
      },
      "required": ["family", "major", "minor"],
      "type": "object"
    },
    "version": {
      "additionalProperties": false,
      "properties": {
        "major": { "const": 1 },
        "minor": { "const": 0 }
      },
      "required": ["major", "minor"],
      "type": "object"
    }
  },
  "title": "Gantry publication index v1",
  "type": "object"
}
